$RECETARIO = [

  // ═══ VASCA ═══
  // Pintxos y entrantes
  [ "titulo"=>'Gildas',"descripcion"=>'El pintxo más antiguo de San Sebastián: una brocheta de anchoa en vinagre, guindilla y aceituna, servida en la barra desde los años 40.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Gildas_en_Donostia.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Vasca','Entrante'],"ingredientes"=>['12 anchoas en vinagre (boquerones)','12 guindillas verdes encurtidas (piparras)','12 aceitunas verdes deshuesadas (manzanilla)','Palillos de madera','Un chorrito de aceite de oliva virgen extra'],"pasos"=>['Escurrir bien las anchoas, las guindillas y las aceitunas para que no suelten líquido en el plato.','Ensartar en cada palillo, en este orden, una aceituna, una guindilla doblada en zigzag y una anchoa enrollada.','Colocar en una fuente y rociar con un hilo de aceite de oliva justo antes de servir.','Servir bien frías, acompañadas de un vermut o un txakoli.'],"consejo"=>'El nombre viene de la película \'Gilda\' con Rita Hayworth: el pintxo es \'salado, verde y un poco picante\', como la protagonista. No lo prepares con mucha antelación: pierde gracia si las guindillas reblandecen la anchoa.' ],
  [ "titulo"=>'Croquetas de jamón',"descripcion"=>'La croqueta cremosa de bechamel espesa y jamón picado, reina indiscutible de cualquier barra de pintxos vasca.',"tiempo"=>'1 h + reposo',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Vasca',"photoUrl"=>'https://live.staticflickr.com/6027/5921994869_9e1cb04ee9_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Entrante'],"ingredientes"=>['100 g de mantequilla','100 g de harina','1 litro de leche entera','150 g de jamón serrano picado fino','1 cebolla pequeña picada','Nuez moscada, sal y pimienta','2 huevos','Pan rallado','Aceite de oliva para freír'],"pasos"=>['Sofreír la cebolla en la mantequilla hasta que esté transparente.','Añadir el jamón picado y rehogar un minuto.','Incorporar la harina y cocinar 2-3 minutos sin dejar de remover, sin que coja color.','Verter la leche caliente poco a poco, sin dejar de remover, hasta obtener una bechamel espesa y lisa. Cocinar 10 minutos a fuego suave.','Sazonar con nuez moscada, sal y pimienta. Extender en una fuente, cubrir con film a piel y enfriar mínimo 4 horas (mejor de un día para otro).','Formar las croquetas, pasarlas por huevo batido y pan rallado.','Freír en aceite bien caliente hasta que estén doradas. Escurrir sobre papel absorbente.'],"consejo"=>'Una masa demasiado líquida es el error más común: cuanto más tiempo de reposo en frío, mejor se manejará la croqueta al formarla.' ],
  [ "titulo"=>'Tortilla de patatas',"descripcion"=>'Servida en pequeñas porciones sobre pan, es uno de los pintxos fijos de cualquier barra vasca, con cebolla o sin ella según la casa.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'entrante',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/c/c0/Tortilla_de_Patatas_%28Corte_transversal%29.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Entrante'],"ingredientes"=>['1 kg de patatas','2 cebollas medianas','8 huevos','Aceite de oliva virgen extra','Sal'],"pasos"=>['Pelar y cortar las patatas en láminas finas. Cortar la cebolla en juliana.','Freír patatas y cebolla juntas a fuego medio-bajo en abundante aceite, removiendo de vez en cuando, hasta que estén tiernas pero no doradas (unos 20 minutos).','Escurrir bien el aceite y mezclar con los huevos batidos y una pizca de sal. Dejar reposar 5 minutos.','Cuajar en una sartén antiadherente con un poco de aceite, a fuego medio, dando la vuelta con ayuda de un plato para cuajar el otro lado.','Dejar reposar unos minutos antes de cortar en porciones.'],"consejo"=>'El punto vasco clásico es jugoso por dentro: retira la sartén del fuego un poco antes de lo que creas necesario, el calor residual termina de cuajarla.' ],
  [ "titulo"=>'Rabas (calamares a la romana)',"descripcion"=>'Tiras de calamar rebozadas y fritas, crujientes por fuera y tiernas por dentro, típicas de los bares del Casco Viejo de Bilbao.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/74/Calamares_Romana_0984.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Entrante'],"ingredientes"=>['600 g de calamar limpio, cortado en aros o tiras','150 g de harina','Aceite de oliva suave para freír','Sal','1 limón'],"pasos"=>['Secar bien el calamar con papel absorbente.','Salar ligeramente y pasar por harina, sacudiendo el exceso.','Freír en abundante aceite muy caliente, en tandas pequeñas, durante 1-2 minutos hasta que estén dorados.','Escurrir sobre papel absorbente y servir de inmediato con una rodaja de limón.'],"consejo"=>'No sobrecargues la sartén: si añades mucho calamar de golpe, el aceite baja de temperatura y el rebozado queda blando en vez de crujiente.' ],
  [ "titulo"=>'Pimientos del piquillo rellenos de bacalao',"descripcion"=>'Pimientos asados de Lodosa rellenos de una farsa de bacalao desmigado, bañados en su propia salsa.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Vasca',"photoUrl"=>'https://live.staticflickr.com/3126/3151073533_f80a6ffd6c_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Entrante'],"ingredientes"=>['16 pimientos del piquillo asados (de bote o frescos asados)','400 g de bacalao desalado desmigado','1 cebolla picada','2 dientes de ajo','200 ml de nata líquida','Aceite de oliva','Harina (opcional, para la salsa)'],"pasos"=>['Pochar la cebolla y el ajo picados en aceite de oliva a fuego suave hasta que estén tiernos.','Añadir el bacalao desmigado y rehogar 5 minutos hasta que pierda el aspecto crudo.','Triturar la mitad de la mezcla con un poco de nata para ligar el relleno; mezclar con el resto sin triturar para dar textura.','Rellenar con cuidado los pimientos con una cuchara o manga pastelera.','Colocar en una cazuela, cubrir con una salsa ligera hecha con el jugo de los pimientos y el resto de la nata, y calentar a fuego suave 10 minutos sin que hierva con fuerza.'],"consejo"=>'Reserva el líquido de los pimientos de bote: es la base perfecta para la salsa y aporta ese punto ligeramente dulce característico del piquillo.' ],
  [ "titulo"=>'Revuelto de perretxikos',"descripcion"=>'Revuelto suave con perretxikos (setas de San Jorge), muy apreciado en primavera en los caseríos vascos.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Vasca',"photoUrl"=>'https://live.staticflickr.com/2290/5799378172_166bcc57f7_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Ligero para la noche'],"etiquetas"=>['Vasca','Entrante'],"ingredientes"=>['400 g de perretxikos (o setas de temporada)','8 huevos','2 dientes de ajo','Aceite de oliva virgen extra','Sal','Perejil picado (opcional)'],"pasos"=>['Limpiar las setas con un paño húmedo, sin lavarlas en exceso, y trocearlas si son grandes.','Saltear el ajo picado en aceite de oliva y añadir las setas, cocinando a fuego medio hasta que suelten su agua y esta se evapore.','Salar y añadir los huevos ligeramente batidos.','Cuajar a fuego suave, removiendo despacio con una espátula de madera, hasta que el huevo esté cremoso pero no líquido.','Servir de inmediato, espolvoreado con perejil si se desea.'],"consejo"=>'El revuelto perfecto se retira del fuego cuando aún parece un poco crudo: sigue cuajando fuera por el calor residual de la sartén.' ],
  // Pescados y mariscos
  [ "titulo"=>'Bacalao al pil-pil',"descripcion"=>'El plato más emblemático de la cocina vasca: bacalao confitado en aceite de oliva que se liga, sin ningún ligante añadido, en una salsa untuosa gracias a la propia gelatina del pescado.',"tiempo"=>'50 min',"tiempoMin"=>50,"dificultad"=>'Alta',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/f/ff/Bacalao_al_Pil_Pil_%28Vizcaya%29.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['4 lomos de bacalao desalado, con piel','300 ml de aceite de oliva virgen extra','4 dientes de ajo laminados','1-2 guindillas secas'],"pasos"=>['Calentar el aceite en una cazuela de barro a fuego suave y dorar los ajos laminados junto con la guindilla; retirar y reservar.','Dejar templar el aceite antes de añadir el bacalao, con la piel hacia arriba.','Cocinar a fuego muy bajo entre 15 y 20 minutos, moviendo la cazuela con un ligero vaivén (sin remover con cuchara) para que el pescado suelte su gelatina.','Retirar los lomos con cuidado y reservar. Colar el aceite en un bol.','Ir añadiendo el aceite templado poco a poco sobre el jugo de la cazuela, moviendo en círculos o con la ayuda de un colador chino, hasta que emulsione y espese en una salsa untuosa (el pil-pil).','Devolver el bacalao a la cazuela, napar con la salsa y decorar con los ajos y la guindilla reservados.'],"consejo"=>'La temperatura es la clave de todo: si el aceite está demasiado caliente, la gelatina se corta y la salsa nunca ligará. Ve con paciencia, a fuego bajo.' ],
  [ "titulo"=>'Bacalao a la vizcaína',"descripcion"=>'Bacalao bañado en una salsa densa de pimientos choriceros y cebolla, larga cocción, muy propia de las mesas de Bilbao en Navidad.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/0/0b/Bacalao_Vizcaina_%28Marug%C3%A1n%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['4 lomos de bacalao desalado','6 pimientos choriceros (o ñoras)','2 cebollas grandes','2 dientes de ajo','1 tomate maduro','Aceite de oliva','Pan frito o una rebanada de pan duro (para ligar, opcional)'],"pasos"=>['Poner los pimientos choriceros en remojo con agua caliente durante 30 minutos, hasta que estén blandos.','Rehogar la cebolla y el ajo picados muy finos en aceite de oliva a fuego lento durante 30-40 minutos, hasta que estén muy tiernos y dulces.','Añadir el tomate rallado y cocinar 10 minutos más.','Raspar la pulpa de los pimientos choriceros ya hidratados e incorporarla al sofrito.','Triturar toda la salsa hasta obtener una textura fina y homogénea; ajustar de sal.','Añadir el bacalao a la salsa, con la piel hacia arriba, y cocinar a fuego suave 8-10 minutos, sin que hierva fuerte, hasta que esté en su punto.'],"consejo"=>'Cuanto más lenta sea la cocción de la cebolla, más profunda y dulce quedará la salsa: no tengas prisa en este paso, es el alma del plato.' ],
  [ "titulo"=>'Marmitako de bonito',"descripcion"=>'Guiso marinero nacido a bordo de los barcos atuneros: bonito, patata cascada y pimientos, en un caldo con el color del pimiento choricero.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Marmitako_de_at%C3%BAn_%28Espa%C3%B1a%29.jpg/960px-Marmitako_de_at%C3%BAn_%28Espa%C3%B1a%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['600 g de bonito del norte fresco, en tacos','800 g de patatas','1 cebolla','1 pimiento verde','1 pimiento rojo','2 dientes de ajo','2 pimientos choriceros (o 1 cucharada de pulpa de choricero)','1 tomate maduro','500 ml de caldo de pescado o fumet','Aceite de oliva, sal, laurel'],"pasos"=>['Hidratar los pimientos choriceros en agua caliente y extraer su pulpa.','Sofreír cebolla, ajo y pimientos picados en aceite de oliva hasta que estén tiernos.','Añadir el tomate rallado y la pulpa de choricero, cocinar unos minutos.','Cascar las patatas (cortar y romper al final del corte para que suelten almidón) e incorporarlas al sofrito. Rehogar 2-3 minutos.','Cubrir con el caldo de pescado caliente y una hoja de laurel; cocinar a fuego medio 20-25 minutos hasta que la patata esté tierna.','Retirar del fuego, añadir el bonito en tacos y dejar reposar tapado 3-4 minutos: el propio calor del guiso lo cocina sin que quede seco.'],"consejo"=>'Nunca hiervas el bonito directamente en el guiso: se endurece. Añádelo siempre fuera del fuego y déjalo terminar de hacerse con el calor residual.' ],
  [ "titulo"=>'Txangurro a la donostiarra',"descripcion"=>'Carne de centollo o buey de mar guisada con verduras, un chorrito de brandy y gratinada al horno, servida en su propio caparazón.',"tiempo"=>'1 h 15 min',"tiempoMin"=>75,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://live.staticflickr.com/2691/4449695487_6d08e303bd_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['2 centollos o buey de mar cocidos (aprox. 1,2 kg)','1 cebolla picada','1/2 puerro picado','50 ml de aceite de oliva','50 ml de tomate triturado','1 chorrito de brandy','Perejil picado','20 g de mantequilla','Pan rallado'],"pasos"=>['Separar con cuidado la carne del centollo del caparazón, desechando branquias, y desmigar bien. Reservar el caparazón limpio.','Pochar la cebolla y el puerro en aceite de oliva a fuego suave hasta que estén muy tiernos.','Añadir el tomate triturado y cocinar unos minutos.','Incorporar el brandy, dejar reducir, y añadir la carne del centollo. Cocinar 3-4 minutos removiendo con suavidad.','Rellenar los caparazones limpios con la mezcla, espolvorear con pan rallado y unos copos de mantequilla.','Gratinar en el horno a 200 °C durante 8-10 minutos, hasta dorar la superficie.'],"consejo"=>'Desmigar bien la carne y retirar cualquier resto de caparazón es lo más laborioso pero también lo más importante del plato: hazlo con calma y buena luz.' ],
  [ "titulo"=>'Kokotxas de bacalao al pil-pil',"descripcion"=>'Las cocochas, la parte gelatinosa de la garganta del bacalao, cocinadas igual que el pil-pil clásico: una de las texturas más apreciadas de la cocina vasca.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Alta',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/CocotxasPilPil.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['600 g de kokotxas de bacalao desaladas','200 ml de aceite de oliva virgen extra','3 dientes de ajo laminados','1 guindilla seca','Perejil picado'],"pasos"=>['Dorar los ajos laminados con la guindilla en el aceite a fuego suave; retirar y reservar.','Templar el aceite y añadir las kokotxas con la piel hacia abajo.','Cocinar a fuego muy bajo, moviendo la cazuela en vaivén constante (nunca con cuchara), durante 8-10 minutos.','La gelatina que sueltan las kokotxas irá ligando el aceite en una salsa cremosa; si hace falta, ayudar con movimientos circulares de la cazuela.','Servir de inmediato con los ajos, la guindilla y perejil picado por encima.'],"consejo"=>'Las kokotxas son muy delicadas: cocínalas siempre a fuego bajísimo y con movimientos suaves, nunca removiendo con una cuchara, o se deshacen.' ],
  [ "titulo"=>'Txipirones en su tinta',"descripcion"=>'Chipirones pequeños guisados en una salsa oscura de su propia tinta, cebolla y pimiento, tradicionalmente acompañados de arroz blanco.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Zaragoza%20-%20Antiguo%20Bar%20La%20Jota%20-%20Calamares%20en%20su%20tinta.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['1 kg de chipirones pequeños limpios, con sus bolsas de tinta reservadas','2 cebollas picadas','1 pimiento verde picado','2 dientes de ajo','1 tomate maduro rallado','100 ml de vino blanco','Aceite de oliva, sal','Arroz blanco para acompañar'],"pasos"=>['Limpiar los chipirones separando cuerpo, aletas y tentáculos; reservar las bolsas de tinta en un vaso con un poco de agua o vino.','Pochar cebolla, pimiento y ajo en aceite de oliva a fuego lento hasta que estén muy tiernos.','Añadir el tomate rallado y cocinar unos minutos más.','Incorporar los chipirones troceados y el vino blanco, dejar reducir el alcohol.','Triturar la tinta disuelta y añadirla a la cazuela; cocinar a fuego suave 20-25 minutos hasta que los chipirones estén tiernos y la salsa espese.','Servir con arroz blanco como guarnición.'],"consejo"=>'No cuezas los chipirones demasiado tiempo a fuego fuerte: quedan gomosos. Una cocción lenta y suave los deja tiernos de verdad.' ],
  [ "titulo"=>'Angulas a la bilbaína',"descripcion"=>'Angulas salteadas al momento con ajo y guindilla en cazuela de barro, un manjar tradicional de invierno en la ría del Nervión.',"tiempo"=>'5 min',"tiempoMin"=>5,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Angulas%20al%20ajillo%2C%20Bilbao%20%2832941326932%29.jpg',"dietas"=>['Vegana','Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido','Reconfortante / comfort food'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['400 g de angulas (o gulas como alternativa habitual hoy en día)','4 dientes de ajo laminados','2 guindillas secas','Aceite de oliva virgen extra'],"pasos"=>['Calentar el aceite en una cazuela individual de barro con los ajos laminados y la guindilla, hasta que el ajo empiece a dorarse.','Añadir las angulas y saltear apenas unos segundos, removiendo con dos tenedores de madera para que no se peguen.','Retirar del fuego en cuanto pierdan el color transparente (unos 30-40 segundos): se cocinan casi al instante.','Servir de inmediato en la misma cazuela, muy caliente.'],"consejo"=>'El punto justo se pierde en segundos: ten todos los ingredientes preparados de antemano porque este plato no espera.' ],
  [ "titulo"=>'Bonito con tomate',"descripcion"=>'Lomos de bonito del norte guisados suavemente en una salsa de tomate casera, receta veraniega de cuando llega la costera del bonito.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://live.staticflickr.com/3192/2671809615_f139c1ee38_b.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['4 rodajas de bonito del norte','1 kg de tomate maduro','1 cebolla','1 pimiento verde','2 dientes de ajo','Aceite de oliva, sal, azúcar (una pizca)','Harina para enharinar el bonito'],"pasos"=>['Pochar la cebolla, el pimiento y el ajo picados en aceite de oliva hasta que estén tiernos.','Añadir el tomate rallado o triturado y cocinar a fuego suave 25-30 minutos, hasta que la salsa espese. Corregir de sal y una pizca de azúcar si el tomate está ácido.','Salpimentar el bonito, enharinarlo ligeramente y marcarlo en una sartén con un poco de aceite, 1 minuto por cada lado, sin cocinarlo del todo.','Introducir el bonito en la salsa de tomate y terminar de cocinar 3-4 minutos a fuego suave.','Servir caliente, con la salsa por encima.'],"consejo"=>'Marca el bonito muy poco antes de meterlo en la salsa: solo tiene que sellarse por fuera, el resto de la cocción la termina el tomate.' ],
  [ "titulo"=>'Sardinas a la parrilla',"descripcion"=>'Sardinas frescas asadas a la brasa, plato sencillo y muy popular en las fiestas de verano de los pueblos costeros vascos.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Asadas%20al%20carb%C3%B3n.JPG',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['16 sardinas frescas, limpias','Sal gruesa','Aceite de oliva virgen extra','Limón'],"pasos"=>['Salar las sardinas generosamente por ambos lados con sal gruesa.','Asar en parrilla de carbón bien caliente, unos 2-3 minutos por cada lado, hasta que la piel esté dorada y crujiente.','Retirar con cuidado para que no se rompan.','Servir de inmediato con un chorrito de aceite de oliva virgen extra y unos gajos de limón.'],"consejo"=>'No las muevas demasiado en la parrilla: dales tiempo para que la piel se dore y se despeguen solas antes de darles la vuelta.' ],
  [ "titulo"=>'Cogote de merluza a la donostiarra',"descripcion"=>'El cogote, la parte más gelatinosa y sabrosa de la merluza, a la plancha con un refrito de ajo, guindilla y vinagre que hace \'chas\' al servirlo.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Rodaja%20de%20merluza%20a%20la%20plancha%20y%20salsa%20de%20picada%20valenciana.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['1 cogote de merluza grande (o 4 raciones)','4 dientes de ajo laminados','1 guindilla seca','100 ml de aceite de oliva virgen extra','1 cucharada de vinagre de sidra','Sal'],"pasos"=>['Salar el cogote y cocinarlo en una plancha o cazuela con un poco de aceite, a fuego medio, con la piel hacia abajo primero, hasta que esté hecho por dentro (unos 12-15 minutos según grosor).','Aparte, calentar el aceite de oliva en una sartén pequeña y dorar los ajos laminados junto con la guindilla.','Retirar la sartén del fuego, añadir el vinagre con cuidado (salpica) y remover.','Verter este refrito bien caliente sobre el cogote justo antes de servir.'],"consejo"=>'El refrito debe llegar muy caliente a la mesa, verterlo sobre el pescado en el momento: ese chisporroteo final es parte de la experiencia del plato.' ],
  [ "titulo"=>'Changurro relleno al horno',"descripcion"=>'Variante más especiada del txangurro clásico, con un toque de brandy y mostaza, gratinado hasta quedar dorado.',"tiempo"=>'1 h 20 min',"tiempoMin"=>80,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/O_Nobre%20%2842982055121%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['2 centollos cocidos','1 cebolla','1 zanahoria pequeña','2 cucharadas de tomate frito','1 cucharadita de mostaza de Dijon','Brandy','Pan rallado y mantequilla para gratinar'],"pasos"=>['Extraer y desmigar la carne del centollo, reservando los caparazones.','Picar muy fino la cebolla y la zanahoria y pocharlas a fuego lento en un poco de aceite hasta que estén tiernas.','Añadir el tomate frito, la mostaza y un chorrito de brandy; cocinar 2 minutos.','Incorporar la carne de centollo, mezclar bien y rectificar de sal.','Rellenar los caparazones, cubrir con pan rallado y unos trocitos de mantequilla.','Gratinar en el horno a 200 °C hasta que la superficie esté dorada, unos 8 minutos.'],"consejo"=>'La mostaza es opcional pero le da un contrapunto interesante a la dulzura del marisco: añádela poco a poco y prueba antes de rellenar.' ],
  [ "titulo"=>'Gambas a la plancha con ajo',"descripcion"=>'Gambas frescas cocinadas enteras a la plancha con sal gruesa y un refrito de ajo, clásico rápido de cualquier sidrería o asador vasco.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://live.staticflickr.com/3624/3469396193_e3640f7372_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['600 g de gambas frescas enteras','Sal gruesa','3 dientes de ajo laminados','Aceite de oliva virgen extra','Perejil picado'],"pasos"=>['Calentar bien la plancha y añadir un chorrito de aceite de oliva.','Colocar las gambas y espolvorear con sal gruesa. Cocinar 1-2 minutos por lado, sin moverlas demasiado, hasta que estén rosadas.','Aparte, calentar un poco de aceite con el ajo laminado hasta dorarlo ligeramente.','Verter el ajo y su aceite sobre las gambas recién hechas y espolvorear con perejil picado.'],"consejo"=>'No las cocines de más: en cuanto cambien de color y se curven ligeramente, están listas. El exceso de calor las deja gomosas.' ],
  // Carnes
  [ "titulo"=>'Txuletón a la brasa',"descripcion"=>'El chuletón de vaca vieja asado sobre brasas de carbón vegetal, con la sal gruesa como único condimento: el plato insignia de los asadores vascos.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Media',"raciones_base"=>2,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Chuleton_a_la_piedra.JPG',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['1 chuletón de vaca de al menos 1 kg y 4-5 cm de grosor','Sal gruesa en escamas','Aceite de oliva virgen extra (opcional)'],"pasos"=>['Sacar la carne de la nevera al menos 1 hora antes para que esté a temperatura ambiente.','Preparar brasas de carbón de encina bien calientes, sin llama.','Asar el chuletón directamente sobre las brasas, 4-5 minutos por cada lado para un punto poco hecho, sellando bien la superficie.','Colocarlo de canto apoyado sobre el hueso unos minutos para que se termine de hacer sin resecarse.','Salar generosamente con sal gruesa justo después de asar, nunca antes.','Dejar reposar 3-4 minutos antes de cortar en lonchas gruesas.'],"consejo"=>'Sala siempre después de asar, nunca antes: la sal extrae los jugos de la carne y reseca la superficie si se aplica con antelación.' ],
  [ "titulo"=>'Txistorra a la sidra',"descripcion"=>'El embutido fresco de cerdo típico vasco, cocinado a fuego lento con un chorro de sidra natural que aporta un punto ácido.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/a/a8/Chistorra.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['600 g de txistorra','200 ml de sidra natural','1 cucharada de aceite de oliva'],"pasos"=>['Pinchar ligeramente la txistorra con un tenedor para que no reviente al cocinarla.','Dorarla en una sartén con un poco de aceite a fuego medio, dándole vueltas, durante 5-6 minutos.','Añadir la sidra y dejar reducir a fuego medio-alto hasta que se forme una salsa ligera que envuelva la txistorra, unos 8-10 minutos.','Servir bien caliente, cortada en trozos, idealmente con pan o como pintxo.'],"consejo"=>'Si tienes ocasión, prueba a flambear la txistorra con un chorrito de aguardiente antes de añadir la sidra: es una variante tradicional en fiestas y romerías.' ],
  // Verduras y legumbres
  [ "titulo"=>'Alubias de Tolosa',"descripcion"=>'Alubias negras pequeñas, con Denominación de Origen de Tolosa, cocinadas a fuego lento con su sacramento tradicional: berza, chorizo y morcilla.',"tiempo"=>'2 h 30 min',"tiempoMin"=>150,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Tolosako%20babarrunak.jpeg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['500 g de alubias negras de Tolosa','1 cebolla entera','1 cabeza de ajo entera','1 hoja de laurel','2 chorizos frescos','2 morcillas','200 g de berza o repollo','Aceite de oliva, sal'],"pasos"=>['Poner las alubias en remojo la noche anterior en agua fría.','Al día siguiente, escurrir y cubrir con agua fría en una cazuela grande junto con la cebolla entera y la cabeza de ajo.','Cocer a fuego lento, sin sal, \'asustando\' con un chorro de agua fría cada vez que rompan a hervir con fuerza (2-3 veces), para que la piel no se abra.','Cuando lleven cociendo aproximadamente 1 hora y media, añadir el laurel y un chorrito de aceite de oliva.','Cocer aparte la berza en agua con sal hasta que esté tierna, y el chorizo y la morcilla en agua aparte para desgrasarlos.','Añadir la berza escurrida, el chorizo y la morcilla a la cazuela de alubias y cocinar 20-30 minutos más a fuego muy suave hasta que todo esté meloso.','Salar al final de la cocción, nunca al principio.'],"consejo"=>'\'Asustar\' las alubias (añadir agua fría cuando hierven con fuerza) es el secreto para que queden enteras y con esa piel fina característica, sin que se rompan.' ],
  [ "titulo"=>'Porrusalda',"descripcion"=>'Sopa reconfortante de puerro y patata, de origen muy humilde, que da nombre en euskera a este binomio (\'porru\' puerro + \'salda\' caldo).',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/1/19/Porrusalda.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['4 puerros grandes','4 patatas medianas','1 zanahoria','1 cebolla pequeña','Aceite de oliva','Sal','Bacalao desalado en trozos (opcional)'],"pasos"=>['Limpiar bien los puerros y cortarlos en rodajas, junto con la zanahoria y la cebolla.','Pochar ligeramente estas verduras en un poco de aceite de oliva durante 5 minutos.','Añadir las patatas cascadas (cortadas rompiendo el trozo final para que suelten almidón) y cubrir con agua.','Cocer a fuego medio 25-30 minutos hasta que las verduras estén muy tiernas.','Si se desea, añadir el bacalao en los últimos 5 minutos de cocción y dejar reposar tapado.','Rectificar de sal y servir bien caliente.'],"consejo"=>'Cascar las patatas en vez de cortarlas limpiamente hace que suelten almidón y el caldo quede más espeso de forma natural, sin necesidad de triturar nada.' ],
  [ "titulo"=>'Piperrada vasca',"descripcion"=>'Fritada de pimientos verdes y rojos, cebolla y tomate cocinados a fuego lento, base de muchos platos vascos y también protagonista por sí sola.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Piperrada1.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['4 pimientos verdes','2 pimientos rojos','2 cebollas','4 tomates maduros','2 dientes de ajo','Aceite de oliva virgen extra','Sal, una pizca de azúcar'],"pasos"=>['Cortar los pimientos y la cebolla en tiras finas, y picar el ajo.','Rehogar la cebolla y el ajo en aceite de oliva a fuego suave hasta que estén transparentes.','Añadir los pimientos y cocinar a fuego lento, tapado, removiendo de vez en cuando, durante 20 minutos hasta que estén muy tiernos.','Incorporar el tomate pelado y troceado, sazonar y cocinar 15-20 minutos más a fuego suave hasta que todo quede meloso y sin exceso de líquido.','Servir como guarnición o acompañado de huevos, bacalao o jamón.'],"consejo"=>'La piperrada gana con la cocción lenta y larga: cuanto más tiempo a fuego bajo, más se concentran los sabores y menos ácida queda.' ],
  [ "titulo"=>'Menestra de verduras de temporada',"descripcion"=>'Combinado de verduras de huerta cocidas y salteadas por separado, unidas en una cazuela con un ligero refrito, típica de la primavera vasca.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://live.staticflickr.com/5139/5456431519_fc88992e96_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['300 g de habitas tiernas','300 g de guisantes','1 manojo de espárragos trigueros','2 alcachofas','2 zanahorias','100 g de jamón serrano en taquitos','2 dientes de ajo','Aceite de oliva, sal, harina (opcional para la salsa)'],"pasos"=>['Cocer por separado, en agua con sal, cada verdura hasta que esté tierna (las alcachofas y zanahorias tardarán más que las habitas y guisantes); escurrir y reservar el caldo de cocción.','Dorar el jamón y el ajo picado en una cazuela con un poco de aceite.','Añadir todas las verduras cocidas y saltear suavemente 2-3 minutos.','Incorporar un cazo del caldo de cocción de las verduras y dejar que ligue ligeramente a fuego suave 5 minutos.','Rectificar de sal y servir caliente.'],"consejo"=>'Cocer cada verdura por separado en vez de todas juntas evita que unas queden pasadas mientras otras aún están duras: es más trabajo, pero marca la diferencia.' ],
  [ "titulo"=>'Pochas con almejas',"descripcion"=>'Alubias blancas frescas (pochas) guisadas con almejas, un plato de mar y montaña muy apreciado a finales de verano cuando llega la pocha fresca.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Pochas%20a%20la%20riojana.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Vasca','Principal'],"ingredientes"=>['600 g de pochas frescas (o alubias blancas cocidas)','300 g de almejas','1 cebolla','2 dientes de ajo','1 pimiento verde','100 ml de vino blanco','Aceite de oliva, sal, perejil'],"pasos"=>['Poner las almejas en agua con sal durante 30 minutos para que suelten la arena; enjuagar bien.','Cocer las pochas frescas en agua sin sal, a fuego suave, hasta que estén tiernas (unos 30-40 minutos si son frescas).','Aparte, pochar la cebolla, el ajo y el pimiento picados en aceite de oliva.','Añadir el vino blanco y dejar reducir; incorporar las almejas y tapar hasta que se abran.','Añadir las pochas cocidas con un poco de su caldo a la cazuela de almejas y cocinar juntas 5-10 minutos a fuego suave para que se integren los sabores.','Espolvorear con perejil picado y servir caliente.'],"consejo"=>'Descarta cualquier almeja que no se abra al cocinarla: es señal de que no estaba en buen estado.' ],
  // Postres
  [ "titulo"=>'Pastel vasco (Gâteau Basque)',"descripcion"=>'Tarta de masa quebrada rellena de crema pastelera o confitura de cereza negra, originaria del País Vasco francés.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>8,"plato"=>'postre',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/6/6b/G%C3%A2teau_Basque_in_Gastroteka_Bimendi_2020-05_ac.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Vasca','Postre'],"ingredientes"=>['300 g de harina','150 g de mantequilla a temperatura ambiente','150 g de azúcar','2 huevos + 1 yema para pintar','1 cucharadita de levadura','Ralladura de un limón','500 ml de leche','4 yemas','80 g de azúcar (para la crema)','40 g de maicena','1 vaina de vainilla'],"pasos"=>['Preparar la crema pastelera: calentar la leche con la vainilla. Batir las yemas con el azúcar y la maicena, añadir la leche caliente poco a poco y cocinar a fuego suave hasta que espese. Dejar enfriar cubierta con film a piel.','Para la masa, batir la mantequilla con el azúcar hasta blanquear, añadir los huevos uno a uno y la ralladura de limón.','Incorporar la harina y la levadura hasta formar una masa homogénea. Envolver en film y refrigerar 30 minutos.','Dividir la masa en dos, estirar cada mitad y forrar un molde con la primera, rellenar con la crema pastelera fría y cubrir con la segunda lámina, sellando bien los bordes.','Pintar con la yema batida y marcar la superficie con un tenedor formando el clásico dibujo de cuadrícula o la cruz vasca.','Hornear a 180 °C durante 35-40 minutos hasta que esté bien dorado.'],"consejo"=>'Refrigera bien la masa antes de trabajarla: es muy mantecosa y a temperatura ambiente resulta difícil de manejar sin que se rompa.' ],
  [ "titulo"=>'Tarta de queso donostiarra',"descripcion"=>'La famosa tarta de queso \'quemada\', sin base ni corteza, creada en el bar La Viña de San Sebastián: exterior oscuro y caramelizado, interior cremoso.',"tiempo"=>'1 h + reposo',"tiempoMin"=>60,"dificultad"=>'Fácil',"raciones_base"=>8,"plato"=>'postre',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Basque-cheesecake.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Vasca','Postre'],"ingredientes"=>['1 kg de queso crema','400 g de azúcar','6 huevos','500 ml de nata para montar (35% M.G.)','1 cucharada de harina','Una pizca de sal'],"pasos"=>['Precalentar el horno a 220-230 °C y forrar un molde desmontable con papel de horno, dejando que sobresalga bastante por los bordes.','Batir el queso crema con el azúcar hasta que quede liso.','Añadir los huevos de uno en uno, integrando bien cada uno antes de agregar el siguiente.','Incorporar la nata, la harina tamizada y la sal, mezclando hasta obtener una masa homogénea y sin grumos.','Verter en el molde y hornear entre 45 y 55 minutos, hasta que la superficie esté muy oscura y el centro tiemble ligeramente al mover el molde.','Dejar enfriar por completo a temperatura ambiente y refrigerar varias horas antes de desmoldar.'],"consejo"=>'No te asustes si la superficie queda muy oscura, casi quemada: es la seña de identidad de esta tarta. El centro debe quedar cremoso, casi líquido en caliente, y asentarse al enfriar.' ],
  [ "titulo"=>'Goxua',"descripcion"=>'Postre de Vitoria-Gasteiz servido en cazuelita individual, con capas de nata montada, bizcocho y crema catalana caramelizada por encima.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/8e/Goxua.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Vasca','Postre'],"ingredientes"=>['4 trozos de bizcocho tipo plancha','200 ml de almíbar o vino dulce (para calar el bizcocho)','300 ml de nata para montar','30 g de azúcar glas','500 ml de leche','4 yemas','80 g de azúcar','30 g de maicena','Azúcar para caramelizar'],"pasos"=>['Preparar una crema pastelera espesa: calentar la leche, batir las yemas con el azúcar y la maicena, mezclar con la leche caliente y cocer a fuego suave hasta que espese. Enfriar.','Montar la nata con el azúcar glas hasta que esté firme.','Calar los trozos de bizcocho en el almíbar y colocarlos en el fondo de cada cazuelita individual.','Cubrir con una capa de nata montada y encima una capa de crema pastelera fría.','Espolvorear con azúcar por encima y caramelizar con soplete de cocina o bajo el grill del horno hasta dorar.'],"consejo"=>'Sirve el goxua recién caramelizado: el contraste entre la costra crujiente aún caliente y la crema fría de debajo es lo que hace especial a este postre.' ],
  [ "titulo"=>'Intxaursaltsa',"descripcion"=>'Crema de nueces con leche y canela, postre navideño tradicional que se toma en Nochebuena en muchos hogares vascos.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Vasca',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/0/0f/Cuisine_of_the_Basque_Country-Intxaursaltsa_001.JPG',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Vasca','Postre'],"ingredientes"=>['200 g de nueces peladas','1 litro de leche entera','150 g de azúcar','1 rama de canela','Canela molida para decorar'],"pasos"=>['Triturar las nueces hasta obtener una pasta fina, o machacarlas en un mortero para una textura más rústica.','Calentar la leche con la rama de canela y el azúcar sin dejar que hierva con fuerza.','Añadir las nueces trituradas y cocinar a fuego muy suave, removiendo con frecuencia, durante 15-20 minutos hasta que espese ligeramente.','Retirar la rama de canela, repartir en cuencos individuales y dejar enfriar.','Espolvorear con canela molida antes de servir.'],"consejo"=>'Remueve con frecuencia mientras espesa: al llevar frutos secos, se pega con facilidad en el fondo de la cazuela y puede quemarse.' ],
  [ "titulo"=>'Mamia (cuajada de oveja)',"descripcion"=>'Postre tradicional de leche de oveja cuajada, servido con miel o azúcar, herencia directa de la trashumancia y los pastores vascos.',"tiempo"=>'20 min + reposo',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Vasca',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Cuajada_cropped_-_juantigues.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Vasca','Postre'],"ingredientes"=>['1 litro de leche de oveja fresca','1 pastilla de cuajo (o unas gotas de cuajo líquido)','Miel para acompañar'],"pasos"=>['Calentar la leche de oveja hasta que esté tibia (unos 37 °C), sin que llegue a hervir.','Disolver el cuajo según las indicaciones del fabricante y mezclarlo con la leche templada.','Repartir en cuencos individuales de barro y dejar reposar sin mover durante 30-40 minutos hasta que cuaje por completo.','Refrigerar antes de servir.','Acompañar con un buen chorro de miel al gusto.'],"consejo"=>'No muevas ni remuevas los cuencos mientras cuaja: cualquier movimiento puede romper la cuajada y que no llegue a tomar cuerpo.' ],

  // ═══ INDIA ═══
  // Panes y aperitivos
  [ "titulo"=>'Samosas de patata y guisantes',"descripcion"=>'Empanadillas triangulares de masa crujiente rellenas de patata especiada y guisantes, el snack callejero más extendido de India.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/c/c4/Samosas%2C_snack_food_at_Wikipedia%27s_16th_Birthday_celebration_in_Chittagong_%2801%29.jpg',"dietas"=>['Vegana','Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['India','Entrante'],"ingredientes"=>['250 g de harina','4 cucharadas de aceite o ghee','Agua, sal','3 patatas cocidas y troceadas','100 g de guisantes','1 cebolla picada','Jengibre rallado','1 cucharadita de comino','1 cucharadita de cilantro molido','Garam masala, chile verde picado','Cilantro fresco','Aceite para freír'],"pasos"=>['Amasar la harina con el aceite, sal y agua hasta lograr una masa firme; dejar reposar tapada 20 minutos.','Sofreír la cebolla y el jengibre en aceite, añadir el comino y dejar que chisporrotee.','Incorporar la patata cocida troceada, los guisantes y las especias; cocinar 5 minutos y dejar enfriar.','Estirar la masa, cortarla en círculos y luego por la mitad para formar semicírculos.','Formar un cono con cada semicírculo, sellando el borde con un poco de agua, y rellenar con la mezcla de patata.','Cerrar bien el borde superior y freír en aceite a temperatura media hasta que doren por completo.'],"consejo"=>'Fríe a fuego medio, nunca alto: así el interior se calienta bien sin que la masa se queme por fuera antes de tiempo.' ],
  [ "titulo"=>'Pakoras de cebolla',"descripcion"=>'Buñuelos de cebolla rebozados en masa de harina de garbanzo especiada y fritos, aperitivo típico de los días de lluvia monzónica.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'India',"photoUrl"=>'https://live.staticflickr.com/8426/7867988816_257d74d2ae.jpg',"dietas"=>['Vegana','Vegetariana','Amante del picante'],"objetivos"=>['Ligero para la noche'],"etiquetas"=>['India','Entrante'],"ingredientes"=>['2 cebollas en juliana fina','150 g de harina de garbanzo (besan)','1 cucharadita de comino','1 cucharadita de cilantro molido','1/2 cucharadita de cúrcuma','Chile en polvo al gusto','Sal','Agua','Aceite para freír','Cilantro fresco picado'],"pasos"=>['Mezclar la cebolla en juliana con la sal y las especias, dejar reposar 10 minutos para que suelte agua.','Añadir la harina de garbanzo poco a poco, junto con un poco de agua si hace falta, hasta lograr una masa espesa que recubra bien la cebolla.','Formar pequeños montoncitos con las manos o una cuchara.','Freír en aceite bien caliente hasta que estén dorados y crujientes por ambos lados.','Escurrir sobre papel absorbente y servir calientes.'],"consejo"=>'Deja reposar la cebolla con sal antes de mezclarla con la harina: el agua que suelta ayuda a formar la masa sin necesidad de añadir demasiada agua extra.' ],
  [ "titulo"=>'Naan de ajo',"descripcion"=>'Pan plano de trigo, esponjoso y con burbujas doradas, cocido tradicionalmente en horno tandoor, aquí adaptado a sartén, con mantequilla y ajo.',"tiempo"=>'2 h (con reposo)',"tiempoMin"=>120,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/4e/Annapurna_Naan.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['India','Entrante'],"ingredientes"=>['400 g de harina','1 cucharadita de levadura seca','1 cucharadita de azúcar','200 ml de yogur natural','Agua tibia','Sal','3 dientes de ajo picados','Mantequilla derretida','Cilantro fresco picado'],"pasos"=>['Disolver la levadura y el azúcar en agua tibia y dejar activar 10 minutos hasta que haga espuma.','Mezclar la harina, la sal, el yogur y la levadura activada; amasar 8-10 minutos hasta obtener una masa elástica.','Dejar fermentar tapada en un lugar cálido durante 1 hora, hasta que doble su volumen.','Dividir en 8 porciones y estirar cada una en forma ovalada.','Cocinar en una sartén de hierro muy caliente, sin aceite, 2 minutos por cada lado, hasta que se formen burbujas doradas.','Pintar recién hecho con mantequilla derretida mezclada con el ajo picado y el cilantro fresco.'],"consejo"=>'Una sartén de hierro fundido bien caliente, sin nada de aceite, imita mejor el calor seco del horno tandoor que una sartén antiadherente.' ],
  [ "titulo"=>'Roti integral (chapati)',"descripcion"=>'Pan plano sencillo de trigo integral, sin levadura, que acompaña a diario cualquier curry en los hogares indios.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/f/fe/2_Chapati_warm_and_ready_to_be_eaten.jpg',"dietas"=>['Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['India','Entrante'],"ingredientes"=>['300 g de harina integral (atta)','Agua tibia','Una pizca de sal','Ghee o mantequilla clarificada para pintar'],"pasos"=>['Mezclar la harina, la sal y el agua tibia hasta formar una masa suave y homogénea.','Amasar 5 minutos y dejar reposar tapada 15 minutos.','Dividir en bolitas y estirar cada una fina y bien redonda con un rodillo.','Cocinar en una sartén o comal caliente, sin aceite, unos 30-40 segundos por cada lado hasta que aparezcan pequeñas manchas doradas.','Si se dispone de fuego directo, acercar el roti un instante a la llama para que se hinche.','Pintar con ghee al servir.'],"consejo"=>'Estira el roti con presión uniforme desde el centro hacia fuera para que quede del mismo grosor en todos los puntos y se cocine parejo.' ],
  // Platos principales
  [ "titulo"=>'Pollo tikka masala',"descripcion"=>'Trozos de pollo marinados en yogur y especias, asados y terminados en una salsa cremosa de tomate: uno de los platos indios más populares fuera de India.',"tiempo"=>'1 h + marinado',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/85/Chicken_Tikka_Masala.jpeg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['India','Principal'],"ingredientes"=>['600 g de pechuga de pollo en dados','200 g de yogur natural','1 cucharada de jengibre y ajo picados','1 cucharadita de comino','1 cucharadita de pimentón','1/2 cucharadita de cúrcuma','Zumo de limón, sal','1 cebolla','2 dientes de ajo','400 g de tomate triturado','100 ml de nata','1 cucharadita de garam masala','Mantequilla, cilantro fresco'],"pasos"=>['Marinar el pollo con el yogur, el jengibre-ajo, las especias y el zumo de limón durante al menos 1 hora, mejor toda la noche.','Asar o dorar el pollo marinado en una sartén bien caliente hasta que esté hecho por fuera; reservar.','En la misma sartén, sofreír la cebolla y el ajo en mantequilla hasta dorar.','Añadir el tomate triturado y el garam masala; cocinar a fuego suave 15 minutos.','Incorporar la nata y remover hasta que la salsa quede homogénea.','Añadir el pollo a la salsa y cocinar 5-10 minutos más; decorar con cilantro fresco.'],"consejo"=>'Marina el pollo el mayor tiempo posible: el yogur ácido ablanda la carne y hace que las especias penetren mejor.' ],
  [ "titulo"=>'Butter chicken (Murgh Makhani)',"descripcion"=>'Variante aún más suave y mantecosa del tikka masala, nacida en Delhi, con una salsa de tomate, mantequilla y nata.',"tiempo"=>'1 h + marinado',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/41/Butter_Chicken_%26_Butter_Naan_-_Home_-_Chandigarh_-_India_-_0006.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['India','Principal'],"ingredientes"=>['600 g de muslos de pollo deshuesados','Yogur, jengibre-ajo, garam masala, pimentón y zumo de limón (para la marinada)','500 g de tomate triturado','50 g de mantequilla','100 ml de nata','1 cucharada de miel o azúcar','1 cucharadita de fenogreco seco (kasuri methi)','Garam masala, chile en polvo al gusto'],"pasos"=>['Marinar el pollo igual que en el tikka masala, mínimo 1 hora.','Asar o saltear el pollo hasta dorar por fuera; reservar.','Derretir la mantequilla, añadir el tomate triturado y cocinar a fuego suave 15-20 minutos hasta que reduzca.','Triturar la salsa hasta que quede fina y homogénea.','Volver a poner al fuego, añadir la nata, la miel y el fenogreco seco desmenuzado entre los dedos.','Incorporar el pollo a la salsa y cocinar 10 minutos más a fuego suave.'],"consejo"=>'El fenogreco seco (kasuri methi), frotado entre los dedos antes de añadirlo, aporta el aroma característico de este plato: si puedes encontrarlo, no lo sustituyas.' ],
  [ "titulo"=>'Rogan josh de cordero',"descripcion"=>'Guiso de cordero originario de Cachemira, de color rojo intenso gracias al pimentón de Cachemira, con un aroma profundo a especias enteras.',"tiempo"=>'2 h',"tiempoMin"=>120,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'India',"photoUrl"=>'https://live.staticflickr.com/2591/4175528358_a13ff155b9_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['India','Principal'],"ingredientes"=>['800 g de cordero para guisar','2 cebollas','4 dientes de ajo','Jengibre','2 cucharadas de pimentón de Cachemira (o dulce)','1 cucharadita de cilantro molido','4 vainas de cardamomo','2 hojas de laurel','1 rama de canela','200 g de yogur','Aceite, sal'],"pasos"=>['Dorar el cordero en aceite caliente por tandas, sin amontonarlo; reservar.','En la misma olla, sofreír la cebolla, el ajo y el jengibre picados.','Añadir las especias enteras (cardamomo, canela, laurel) y tostarlas unos segundos.','Incorporar el pimentón y el cilantro molido, remover bien.','Añadir el yogur poco a poco, sin dejar de remover, para que no se corte.','Devolver el cordero a la olla, cubrir con agua y cocinar tapado a fuego lento 1 hora y 30 minutos hasta que la carne esté muy tierna.'],"consejo"=>'Añade el yogur fuera del punto de mayor calor y remuévelo sin parar al incorporarlo: así evitas que se corte con el calor de la olla.' ],
  [ "titulo"=>'Palak paneer',"descripcion"=>'Queso fresco indio (paneer) en una crema suave de espinacas especiadas, uno de los platos vegetarianos más extendidos del norte de India.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/d/de/Shahi_paneer_and_palak_paneer.JPG',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['India','Principal'],"ingredientes"=>['400 g de paneer en dados','500 g de espinacas frescas','1 cebolla','2 dientes de ajo','Jengibre','1 tomate','1 cucharadita de comino','1/2 cucharadita de cúrcuma','100 ml de nata','Mantequilla, sal'],"pasos"=>['Escaldar las espinacas en agua hirviendo 2 minutos, enfriar en agua con hielo y triturar hasta obtener un puré fino.','Sofreír la cebolla, el ajo y el jengibre en mantequilla hasta dorar.','Añadir el tomate picado y las especias, cocinar 5 minutos.','Incorporar el puré de espinacas y cocinar 5 minutos más.','Añadir la nata y el paneer en dados; cocinar a fuego suave 5-8 minutos sin que hierva con fuerza.'],"consejo"=>'Si el paneer está muy firme, saltéalo brevemente en mantequilla antes de añadirlo: gana en sabor y en textura.' ],
  [ "titulo"=>'Dal tadka',"descripcion"=>'Lentejas amarillas cocidas y aderezadas con un \'tadka\', un chisporroteo final de especias en ghee que se vierte por encima; plato diario en cualquier casa india.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'India',"photoUrl"=>'https://live.staticflickr.com/8735/16947046775_4551e37465_b.jpg',"dietas"=>['Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['India','Principal'],"ingredientes"=>['250 g de lentejas amarillas (toor dal o similar)','1/2 cucharadita de cúrcuma','Sal','2 cucharadas de ghee o mantequilla clarificada','1 cucharadita de semillas de comino','2 dientes de ajo laminados','1 chile seco','1/2 cebolla picada','Cilantro fresco'],"pasos"=>['Cocer las lentejas con agua, la cúrcuma y sal hasta que estén blandas, unos 25-30 minutos, añadiendo agua si hace falta.','Triturar ligeramente con un batidor de mano para lograr una textura cremosa.','Aparte, calentar el ghee y freír las semillas de comino hasta que salten.','Añadir el ajo laminado, el chile seco y la cebolla; sofreír hasta dorar.','Verter este tadka caliente sobre las lentejas justo antes de servir y decorar con cilantro.'],"consejo"=>'El tadka se vierte siempre al final, hirviendo, directamente sobre el dal ya servido en el plato: ese chisporroteo es lo que aporta el aroma característico.' ],
  [ "titulo"=>'Chana masala',"descripcion"=>'Garbanzos guisados en una salsa especiada de tomate y cebolla, plato vegetariano de Punjab muy habitual como plato único.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/8e/Chana_masala.jpg',"dietas"=>['Vegana','Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['India','Principal'],"ingredientes"=>['400 g de garbanzos cocidos','1 cebolla','2 dientes de ajo','Jengibre','2 tomates','1 cucharadita de comino','1 cucharadita de cilantro molido','1/2 cucharadita de cúrcuma','1 cucharadita de garam masala','Chile en polvo, aceite','Cilantro fresco, zumo de limón'],"pasos"=>['Sofreír la cebolla, el ajo y el jengibre en aceite hasta dorar.','Añadir el tomate picado y las especias secas; cocinar 10 minutos hasta que espese.','Incorporar los garbanzos escurridos junto con un poco de su agua de cocción.','Cocinar a fuego medio 15-20 minutos hasta que la salsa espese y los garbanzos tomen sabor.','Terminar con el garam masala, cilantro fresco y un chorro de limón.'],"consejo"=>'Chafa unos pocos garbanzos contra la olla mientras se cocinan: espesarán la salsa de forma natural sin necesidad de añadir nada más.' ],
  // Arroces y guarniciones
  [ "titulo"=>'Biryani de pollo',"descripcion"=>'Arroz basmati cocido en capas con pollo especiado, azafrán y hierbas frescas; plato festivo que se sirve en ocasiones especiales en toda India.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Alta',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/5a/%22Hyderabadi_Dum_Biryani%22.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['India','Principal'],"ingredientes"=>['500 g de arroz basmati','600 g de muslos de pollo','200 g de yogur','Jengibre-ajo picados','Garam masala, chile en polvo','2 cebollas (una de ellas frita hasta quedar crujiente)','Unas hebras de azafrán en leche templada','Ghee','Hojas de menta y cilantro','Especias enteras: canela, cardamomo, clavo, laurel'],"pasos"=>['Marinar el pollo con el yogur y las especias durante al menos 1 hora.','Remojar el arroz 30 minutos y cocerlo en agua con las especias enteras hasta que esté un 70% hecho, aún firme en el centro; escurrir.','En una olla aparte, cocinar el pollo marinado junto con la cebolla pochada hasta que esté hecho y la salsa haya espesado.','Montar el biryani en capas dentro de una olla: pollo en el fondo, arroz encima, un poco de leche con azafrán, cebolla frita y hierbas frescas; repetir las capas.','Tapar herméticamente (con papel de aluminio bajo la tapa) y cocinar a fuego muy bajo (\'dum\') 20-25 minutos para que los sabores se integren.','Servir mezclando las capas con cuidado en el momento de emplatar.'],"consejo"=>'Sella bien la olla antes de la cocción final \'dum\' para que el vapor no escape: así el arroz termina de hacerse con su propio calor sin perder aroma.' ],
  [ "titulo"=>'Arroz jeera (arroz al comino)',"descripcion"=>'Guarnición sencilla de arroz basmati salteado con semillas de comino tostadas, acompañamiento habitual de cualquier curry.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/5e/Jeera-rice.JPG',"dietas"=>['Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['India','Principal'],"ingredientes"=>['300 g de arroz basmati','1 cucharada de ghee o mantequilla','1 cucharadita de semillas de comino','1 hoja de laurel','Sal'],"pasos"=>['Lavar el arroz varias veces hasta que el agua salga clara; dejar en remojo 20 minutos y escurrir.','Calentar el ghee y tostar las semillas de comino junto con el laurel hasta que suelten aroma.','Añadir el arroz escurrido y saltear 2 minutos.','Cubrir con agua en proporción 1:1,5, salar y cocinar tapado a fuego bajo 12-15 minutos sin destapar.','Dejar reposar 5 minutos antes de remover con un tenedor.'],"consejo"=>'No remuevas el arroz mientras se cocina: los granos de basmati son delicados y se rompen con facilidad si se manipulan demasiado.' ],
  [ "titulo"=>'Raita de pepino',"descripcion"=>'Yogur refrescante con pepino rallado y especias suaves, el contrapunto fresco perfecto para acompañar los platos más picantes.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/78/Cucumber-raita.jpg',"dietas"=>['Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['India','Principal'],"ingredientes"=>['300 g de yogur natural','1 pepino','1/2 cucharadita de comino tostado y molido','Sal, pimienta negra','Cilantro o menta fresca picada'],"pasos"=>['Rallar el pepino y escurrir el exceso de agua apretándolo con las manos o un paño.','Batir el yogur hasta que esté liso.','Mezclar el yogur con el pepino escurrido, el comino tostado, sal y pimienta.','Decorar con cilantro o menta fresca picada.','Refrigerar antes de servir.'],"consejo"=>'Tostar las semillas de comino en una sartén seca antes de molerlas realza mucho más su aroma que usar comino molido comprado directamente.' ],
  // Postres
  [ "titulo"=>'Gulab jamun',"descripcion"=>'Bolitas de leche en polvo fritas y bañadas en un almíbar aromatizado con cardamomo y agua de rosas, el postre indio más extendido en celebraciones.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'postre',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/56/Gulab_Jamun.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['India','Postre'],"ingredientes"=>['200 g de leche en polvo','50 g de harina','1/4 cucharadita de bicarbonato','2 cucharadas de ghee','Leche líquida (para amasar)','400 g de azúcar','400 ml de agua','4 vainas de cardamomo machacadas','Unas gotas de agua de rosas','Aceite para freír'],"pasos"=>['Preparar el almíbar hirviendo el azúcar con el agua y el cardamomo 8-10 minutos hasta que espese ligeramente; añadir el agua de rosas y reservar templado.','Mezclar la leche en polvo, la harina y el bicarbonato; incorporar el ghee y suficiente leche líquida hasta formar una masa suave y sin grumos.','Formar bolitas lisas, sin grietas en la superficie.','Freír en aceite templado, no muy caliente, a fuego medio-bajo, moviéndolas constantemente, hasta que doren de forma uniforme por todos lados.','Sumergir inmediatamente en el almíbar templado y dejar reposar al menos 1 hora para que lo absorban bien.'],"consejo"=>'Fríe a fuego medio-bajo y sin prisa: si el aceite está demasiado caliente, se doran por fuera antes de cocinarse por dentro y quedan crudas en el centro.' ],
  [ "titulo"=>'Kheer (arroz con leche indio)',"descripcion"=>'Postre de arroz cocido lentamente en leche con azúcar, cardamomo y frutos secos; la versión india del arroz con leche.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'India',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/46/Kheer.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['India','Postre'],"ingredientes"=>['100 g de arroz de grano corto','1 litro de leche entera','100 g de azúcar','4 vainas de cardamomo machacadas','Un puñado de anacardos y almendras laminadas','Unas hebras de azafrán','Ghee'],"pasos"=>['Lavar el arroz y dejarlo en remojo 20 minutos.','Llevar la leche a ebullición suave, añadir el arroz escurrido y cocinar a fuego bajo, removiendo con frecuencia, durante 30-40 minutos hasta que el arroz esté muy tierno y la leche haya espesado.','Añadir el azúcar y el cardamomo, cocinar 10 minutos más.','Aparte, dorar los frutos secos en un poco de ghee.','Incorporar los frutos secos y el azafrán al kheer y servir templado o frío.'],"consejo"=>'Remueve con frecuencia mientras espesa, sobre todo hacia el final: el azúcar y el almidón del arroz hacen que se pegue con facilidad al fondo de la cazuela.' ],

  // ═══ JAPONESA ═══
  // Sopas y aperitivos
  [ "titulo"=>'Miso shiru (sopa de miso)',"descripcion"=>'Sopa ligera de caldo dashi y pasta de miso, con tofu y alga wakame, que abre casi cualquier comida japonesa.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Japonesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/e8/Miso_Soup_001.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Reconfortante / comfort food','Ligero para la noche'],"etiquetas"=>['Japonesa','Entrante'],"ingredientes"=>['1 litro de caldo dashi (o agua con alga kombu y katsuobushi)','3 cucharadas de pasta de miso','200 g de tofu en dados','2 cucharadas de alga wakame deshidratada','1 cebolleta picada'],"pasos"=>['Preparar el caldo dashi calentando agua con kombu y katsuobushi, y colar.','Rehidratar el alga wakame en agua unos minutos y escurrir.','Calentar el caldo sin que llegue a hervir con fuerza y añadir el tofu y el wakame.','Disolver el miso en un cucharón con un poco de caldo templado y añadirlo al final, fuera del hervor.','Servir de inmediato con la cebolleta picada por encima.'],"consejo"=>'Nunca hiervas el caldo después de añadir el miso: el hervor destruye buena parte de su aroma.' ],
  [ "titulo"=>'Gyoza',"descripcion"=>'Empanadillas japonesas de cerdo y col, doradas por un lado y cocidas al vapor por el otro.',"tiempo"=>'50 min',"tiempoMin"=>50,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Japonesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/f/ff/Jiaozi.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Japonesa','Entrante'],"ingredientes"=>['24 obleas de gyoza','300 g de carne picada de cerdo','150 g de col china picada y escurrida','1 cebolleta picada','1 cucharada de jengibre rallado','1 diente de ajo','1 cucharada de salsa de soja','1 cucharadita de aceite de sésamo','Aceite vegetal, agua'],"pasos"=>['Mezclar la carne con la col escurrida, la cebolleta, el jengibre, el ajo, la soja y el aceite de sésamo.','Colocar una cucharadita de relleno en el centro de cada oblea, humedecer el borde y sellar en pliegues.','Calentar aceite en una sartén antiadherente y dorar la base de las gyozas 2 minutos.','Añadir un chorrito de agua, tapar y cocer al vapor 4-5 minutos.','Destapar y dejar que se evapore el agua restante hasta que la base quede crujiente.'],"consejo"=>'No despegues las gyozas de la sartén hasta que hayan dorado bien la base: se soltarán solas cuando estén listas.' ],
  [ "titulo"=>'Edamame con sal',"descripcion"=>'Vainas de soja verde hervidas y salpimentadas, el aperitivo más simple de cualquier izakaya japonesa.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Japonesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/e7/Edamame_by_Zesmerelda_in_Chicago.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Japonesa','Entrante'],"ingredientes"=>['400 g de edamame con vaina (congelado o fresco)','Sal gruesa','Agua'],"pasos"=>['Hervir abundante agua con sal.','Cocer los edamame entre 4 y 5 minutos hasta que estén tiernos.','Escurrir y enfriar brevemente bajo agua fría si se van a servir fríos.','Espolvorear con sal gruesa adicional antes de servir.'],"consejo"=>'Frota los edamame con un poco de sal antes de hervirlos: ayuda a que se adhiera mejor a la vaina.' ],
  [ "titulo"=>'Tempura de verduras y gambas',"descripcion"=>'Verduras y gambas rebozadas en una masa ligera y crujiente, fritas a alta temperatura y servidas con salsa tentsuyu.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Japonesa',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Ligaz%C3%B3n%20-%20Tempura%20de%20verdura.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Japonesa','Entrante'],"ingredientes"=>['12 gambas peladas dejando la cola','1 berenjena, 1 boniato, 1 pimiento','100 g de harina','100 g de maicena','Agua muy fría','1 huevo','Aceite para freír','Dashi, salsa de soja y mirin (para la salsa tentsuyu)'],"pasos"=>['Mezclar harina, maicena, huevo y agua helada sin batir demasiado, dejando grumos.','Cortar las verduras en láminas finas y secar bien las gambas.','Pasar cada ingrediente por la masa y freír en aceite muy caliente hasta que esté dorada y crujiente, sin dorar en exceso.','Escurrir sobre papel absorbente.','Preparar la salsa tentsuyu calentando dashi con soja y mirin y servir aparte.'],"consejo"=>'No batas la masa hasta que quede lisa: los grumos y el agua muy fría son lo que hace que la tempura quede ligera.' ],
  // Platos principales
  [ "titulo"=>'Sushi nigiri (variado)',"descripcion"=>'Bolitas de arroz avinagrado cubiertas con una lámina de pescado fresco, la forma más pura del sushi.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Alta',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Japonesa',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Various%20sushi%2C%20beautiful%20October%20night%20at%20midnight.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Japonesa','Principal'],"ingredientes"=>['400 g de arroz de sushi','60 ml de vinagre de arroz','2 cucharadas de azúcar','1 cucharadita de sal','300 g de pescado fresco apto para consumo crudo (salmón, atún, dorada)','Wasabi, salsa de soja'],"pasos"=>['Cocer el arroz según las instrucciones del paquete.','Mezclar vinagre, azúcar y sal, calentar hasta disolver y mezclar con el arroz recién hecho, abanicando mientras se enfría.','Cortar el pescado en láminas finas del tamaño de un bocado.','Humedecerse las manos y formar pequeños óvalos de arroz.','Poner una pizca de wasabi sobre el arroz y colocar la lámina de pescado encima presionando con suavidad.'],"consejo"=>'Humedece siempre las manos con agua con un poco de vinagre antes de formar cada nigiri: el arroz es muy pegajoso.' ],
  [ "titulo"=>'Sashimi de atún',"descripcion"=>'Láminas finas de atún fresco de máxima calidad, servidas sin nada más que soja, wasabi y jengibre encurtido.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Japonesa',"photoUrl"=>'https://live.staticflickr.com/3064/2974339358_24cf6d1887_b.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Japonesa','Principal'],"ingredientes"=>['400 g de atún fresco de calidad sashimi','Salsa de soja','Wasabi fresco o en pasta','Jengibre encurtido (gari)','Daikon rallado (opcional)'],"pasos"=>['Con un cuchillo muy afilado, cortar el atún en láminas de unos 5 mm de grosor, en un único movimiento limpio.','Disponer las láminas sobre un plato frío, idealmente sobre daikon rallado.','Servir con wasabi, jengibre encurtido y salsa de soja aparte para mojar.'],"consejo"=>'Corta siempre en un solo movimiento, sin serrar: serrar el pescado rompe las fibras y arruina la textura.' ],
  [ "titulo"=>'Teriyaki de pollo',"descripcion"=>'Muslos de pollo dorados y glaseados en una salsa dulce y brillante de soja, mirin y azúcar.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Japonesa',"photoUrl"=>'https://live.staticflickr.com/5142/5623883890_7d90a6fbff_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Japonesa','Principal'],"ingredientes"=>['4 muslos de pollo deshuesados','4 cucharadas de salsa de soja','3 cucharadas de mirin','2 cucharadas de sake','2 cucharadas de azúcar','Aceite, sésamo tostado, cebolleta'],"pasos"=>['Dorar el pollo con la piel hacia abajo en una sartén con un poco de aceite hasta que esté crujiente.','Dar la vuelta y cocinar por el otro lado.','Mezclar la soja, el mirin, el sake y el azúcar, y verter sobre el pollo.','Cocinar a fuego medio, girando y napando el pollo, hasta que la salsa reduzca y quede brillante.','Cortar en lonchas, espolvorear con sésamo y cebolleta.'],"consejo"=>'Retira el exceso de grasa de la sartén antes de añadir la salsa: si no, no reduce bien y queda aguada.' ],
  [ "titulo"=>'Tonkatsu',"descripcion"=>'Chuleta de cerdo empanada con panko y frita hasta quedar extra crujiente, servida con col en juliana.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Japonesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/d/d5/Tonkatsu_of_Kimukatsu.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Japonesa','Principal'],"ingredientes"=>['4 chuletas de cerdo sin hueso','Sal, pimienta','Harina','2 huevos batidos','Panko (pan rallado japonés)','Aceite para freír','Col blanca en juliana fina','Salsa tonkatsu'],"pasos"=>['Salpimentar las chuletas y golpearlas ligeramente para ablandarlas.','Pasarlas por harina, huevo batido y panko, presionando bien para que se adhiera.','Freír en aceite abundante a 170 °C, 3-4 minutos por lado, hasta dorar.','Escurrir sobre una rejilla y cortar en tiras.','Servir sobre col en juliana muy fina con la salsa tonkatsu.'],"consejo"=>'Deja escurrir la carne sobre una rejilla, no sobre papel: así el vapor no reblandece el rebozado por debajo.' ],
  [ "titulo"=>'Sukiyaki',"descripcion"=>'Guiso de ternera fileteada muy fina, verduras y tofu cocinados en un caldo dulce de soja, que se moja en huevo crudo batido.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Japonesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/3/32/Sukiyaki_01.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Japonesa','Principal'],"ingredientes"=>['500 g de ternera en lonchas muy finas','200 g de tofu firme','Setas shiitake','Puerro japonés (negi)','Col china','Fideos shirataki','4 huevos (para mojar)','Soja, mirin, sake, azúcar, agua (salsa)'],"pasos"=>['Mezclar la salsa (soja, mirin, sake, azúcar y agua) y calentarla en una cazuela ancha.','Añadir primero la ternera en tandas, cocinando apenas unos segundos por lado.','Incorporar el tofu, las setas, el puerro y la col por tandas.','Cada comensal casca un huevo en un cuenco, lo bate y moja en él los ingredientes recién cocinados.'],"consejo"=>'No sobrecargues la cazuela de golpe: añade los ingredientes en tandas pequeñas para que se cocinen en su punto.' ],
  // Arroz y fideos
  [ "titulo"=>'Ramen tonkotsu',"descripcion"=>'Sopa de fideos con un caldo denso de hueso de cerdo cocido muchas horas, chashu, huevo marinado y alga nori.',"tiempo"=>'4 h (caldo) + 30 min montaje',"tiempoMin"=>270,"dificultad"=>'Alta',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Japonesa',"photoUrl"=>'https://live.staticflickr.com/3027/3024811224_44373f7091_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Japonesa','Principal'],"ingredientes"=>['1,5 kg de huesos de cerdo','300 g de panceta de cerdo enrollada','Fideos de ramen frescos','4 huevos','Salsa de soja, mirin','Alga nori, cebolleta, brotes de bambú'],"pasos"=>['Blanquear los huesos en agua hirviendo 5 minutos y enjuagar bien.','Cubrir con agua fresca y cocer a hervor constante durante 4-6 horas, reponiendo agua, hasta que el caldo quede blanco y denso.','Marinar huevos cocidos (7 minutos) en soja y mirin varias horas.','Cocinar la panceta enrollada a fuego lento en soja y mirin hasta que esté tierna, y cortarla en lonchas.','Cocer los fideos frescos al momento y montar el bol con caldo, fideos, chashu, medio huevo marinado, nori y cebolleta.'],"consejo"=>'El hervor vigoroso y sostenido es lo que emulsiona la grasa del hueso y da al caldo su color blanco y su cremosidad.' ],
  [ "titulo"=>'Yakisoba',"descripcion"=>'Fideos de trigo salteados con verduras y cerdo en una salsa agridulce, plato rápido de festivales callejeros.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Japonesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/59/Sauce_fried_noodles_of_Gyoza-no-Manshu.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Japonesa','Principal'],"ingredientes"=>['400 g de fideos yakisoba (o de trigo cocidos)','200 g de panceta de cerdo en tiras','Col en juliana, zanahoria, cebolla','Salsa yakisoba (o Worcestershire, kétchup y soja)','Aceite, alga aonori, jengibre encurtido'],"pasos"=>['Saltear la panceta en un wok caliente hasta dorar.','Añadir la cebolla y la zanahoria y saltear 2 minutos.','Incorporar la col y saltear hasta que empiece a ablandar.','Añadir los fideos y la salsa, saltear todo junto a fuego fuerte hasta integrar.','Servir espolvoreado con aonori y jengibre encurtido.'],"consejo"=>'Cocina a fuego muy fuerte y sin parar de remover: el yakisoba se hace en minutos.' ],
  [ "titulo"=>'Onigiri',"descripcion"=>'Triángulos de arroz rellenos, envueltos en una tira de alga nori, el clásico tentempié portátil japonés.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Japonesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/22/Japanese_rice_balls_%28onigiri%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Japonesa','Principal'],"ingredientes"=>['400 g de arroz japonés cocido','Sal','Relleno al gusto (salmón a la plancha desmenuzado, umeboshi, atún con mayonesa)','Láminas de alga nori'],"pasos"=>['Cocer el arroz y dejarlo templar ligeramente.','Humedecer las manos con agua y sal.','Tomar una porción de arroz, hacer un hueco en el centro, añadir el relleno y cubrir con más arroz.','Formar un triángulo presionando con las manos ahuecadas.','Envolver la base con una tira de alga nori.'],"consejo"=>'Trabaja con el arroz templado, no caliente: se maneja mucho mejor sin quemarte las manos.' ],
  [ "titulo"=>'Katsudon',"descripcion"=>'Tonkatsu bañado en huevo y cebolla sobre un bol de arroz, plato reconfortante muy popular en Japón.',"tiempo"=>'35 min',"tiempoMin"=>35,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Japonesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/a/ad/Katsudon_001.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Japonesa','Principal'],"ingredientes"=>['4 chuletas de cerdo empanadas y fritas (tonkatsu), en tiras','1 cebolla en juliana','Caldo dashi, salsa de soja, mirin, azúcar','8 huevos','Arroz japonés cocido, cebolleta'],"pasos"=>['Cocer la cebolla en una mezcla de dashi, soja, mirin y azúcar en una sartén pequeña hasta que esté tierna.','Colocar encima las tiras de tonkatsu.','Verter el huevo batido por encima, tapar y cocinar a fuego suave hasta que cuaje pero quede jugoso.','Servir directamente sobre un bol de arroz caliente, decorado con cebolleta.'],"consejo"=>'No cuajes el huevo del todo: debe quedar ligeramente jugoso para que empape el arroz al servir.' ],
  // Postres
  [ "titulo"=>'Dorayaki',"descripcion"=>'Dos pequeñas tortitas esponjosas rellenas de pasta de judía roja dulce (anko).',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Japonesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/7f/Dorayaki_001.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Japonesa','Postre'],"ingredientes"=>['2 huevos','100 g de azúcar','1 cucharada de miel','130 g de harina','1 cucharadita de levadura','80 ml de agua','300 g de pasta de judía roja dulce (anko)'],"pasos"=>['Batir los huevos con el azúcar y la miel hasta espumar.','Añadir la harina y la levadura tamizadas, mezclar.','Incorporar el agua poco a poco hasta lograr una masa fluida y dejar reposar 15 minutos.','Cocinar pequeñas tortitas en una sartén antiadherente sin aceite, a fuego medio-bajo, hasta que doren por ambos lados.','Rellenar dos tortitas con una cucharada generosa de anko.'],"consejo"=>'Deja reposar la masa antes de cocinarla: la levadura necesita ese tiempo para que las tortitas queden esponjosas.' ],
  [ "titulo"=>'Mochi de té verde',"descripcion"=>'Pastelitos de arroz glutinoso elásticos, rellenos de pasta dulce de judía y aromatizados con matcha.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Japonesa',"photoUrl"=>'https://live.staticflickr.com/5613/15483566922_5217c4d6d5_b.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Japonesa','Postre'],"ingredientes"=>['200 g de harina de arroz glutinoso (mochiko)','100 g de azúcar','250 ml de agua','1 cucharada de matcha','Maicena para espolvorear','250 g de pasta de judía dulce (anko)'],"pasos"=>['Mezclar la harina de arroz glutinoso, el azúcar, el matcha y el agua hasta obtener una masa lisa.','Cocinar al vapor o en microondas por tandas cortas, removiendo entre cada una, hasta que quede translúcida y elástica.','Volcar sobre una superficie bien espolvoreada con maicena.','Dejar templar, dividir en porciones, aplanar y rellenar con una bolita de anko, cerrando en forma de bola lisa.'],"consejo"=>'Trabaja la masa mientras aún está templada: al enfriarse del todo se vuelve mucho más difícil de manejar.' ],

  // ═══ GRIEGA ═══
  // Aperitivos y salsas
  [ "titulo"=>'Tzatziki',"descripcion"=>'Salsa fría de yogur griego, pepino rallado y ajo, aliñada con aceite de oliva y eneldo.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/f/f7/Yogurt_with_cucumber%3B_Yogur_con_pepino_%28Las_Siete_Orillas_project%29.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Griega','Entrante'],"ingredientes"=>['400 g de yogur griego espeso','1 pepino','2 dientes de ajo','2 cucharadas de aceite de oliva virgen extra','1 cucharada de vinagre o zumo de limón','Eneldo fresco picado, sal'],"pasos"=>['Rallar el pepino y escurrir bien el exceso de agua con un paño.','Machacar el ajo hasta obtener una pasta.','Mezclar el yogur con el pepino escurrido, el ajo, el aceite y el vinagre.','Salar al gusto, añadir el eneldo y refrigerar al menos 30 minutos antes de servir.'],"consejo"=>'Escurre muy bien el pepino: es lo que marca la diferencia entre un tzatziki espeso y uno aguado.' ],
  [ "titulo"=>'Spanakopita',"descripcion"=>'Empanada de hojaldre filo rellena de espinacas y queso feta, horneada hasta quedar crujiente.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'entrante',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/78/Spanokopita_cropped.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Griega','Entrante'],"ingredientes"=>['500 g de espinacas frescas','200 g de queso feta desmenuzado','1 cebolla','2 huevos','Eneldo fresco','10 láminas de pasta filo','Aceite de oliva o mantequilla derretida'],"pasos"=>['Rehogar la cebolla en aceite hasta que esté transparente.','Añadir las espinacas y cocinar hasta que reduzcan, escurrir bien el líquido.','Mezclar las espinacas con el feta, los huevos batidos y el eneldo.','Forrar un molde con láminas de filo pintadas de aceite entre capa y capa.','Rellenar con la mezcla, cubrir con más filo pintado y hornear a 180 °C 35-40 minutos hasta dorar.'],"consejo"=>'Pinta cada lámina de filo con aceite antes de añadir la siguiente: es lo que da la textura de capas crujientes.' ],
  [ "titulo"=>'Dolmades',"descripcion"=>'Hojas de parra rellenas de arroz y hierbas, cocinadas lentamente y servidas templadas con limón.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/75/Sarma.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Griega','Entrante'],"ingredientes"=>['30 hojas de parra en salmuera','200 g de arroz de grano redondo','1 cebolla picada','Eneldo y menta fresca picados','Aceite de oliva, zumo de limón','Caldo de verduras'],"pasos"=>['Escaldar las hojas de parra en agua hirviendo 2 minutos y escurrir.','Rehogar la cebolla en aceite, añadir el arroz y remover 2 minutos, retirar del fuego y añadir las hierbas.','Colocar una cucharada de relleno en cada hoja y enrollar bien prieto.','Colocar los rollitos muy juntos en una cazuela, cubrir con caldo, aceite y limón.','Cocinar tapados a fuego suave 40-45 minutos.'],"consejo"=>'Coloca los dolmades muy apretados en la cazuela: así no se desenrollan durante la cocción.' ],
  [ "titulo"=>'Saganaki',"descripcion"=>'Queso duro griego frito hasta formar una costra dorada y crujiente, servido con un chorro de limón.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/a/a8/Saganaki.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Griega','Entrante'],"ingredientes"=>['300 g de queso kefalotyri o graviera en una loncha gruesa','Harina','Aceite de oliva','Limón'],"pasos"=>['Pasar la loncha de queso por harina, sacudiendo el exceso.','Calentar aceite de oliva en una sartén a fuego medio-alto.','Freír el queso 1-2 minutos por cada lado hasta que forme una costra dorada.','Servir de inmediato con un chorro de limón.'],"consejo"=>'Fríelo en aceite ya bien caliente: si no, el queso se derrite antes de dorarse por fuera.' ],
  // Platos principales
  [ "titulo"=>'Souvlaki de cerdo',"descripcion"=>'Brochetas de cerdo marinadas en aceite de oliva, limón y orégano, asadas a la parrilla.',"tiempo"=>'30 min + marinado',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/e8/Souvlaki_in_Athens.JPG',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Griega','Principal'],"ingredientes"=>['700 g de aguja de cerdo en dados','Aceite de oliva, zumo de limón','Orégano seco, ajo picado','Sal, pimienta','Pan de pita, tzatziki para acompañar'],"pasos"=>['Marinar el cerdo con aceite, limón, orégano, ajo, sal y pimienta al menos 1 hora.','Ensartar en brochetas.','Asar a la parrilla o plancha bien caliente, 3-4 minutos por lado, hasta dorar y quedar jugosas.','Servir con pan de pita templado y tzatziki.'],"consejo"=>'No cortes los trozos de carne demasiado pequeños: se secan antes de dorarse bien por fuera.' ],
  [ "titulo"=>'Moussaka',"descripcion"=>'Pastel de capas de berenjena frita, carne picada especiada con canela y bechamel gratinada.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/a/a8/MussakasMeMelitsanesKePatates01.JPG',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Griega','Principal'],"ingredientes"=>['3 berenjenas grandes en láminas','500 g de carne picada de cordero o ternera','1 cebolla, 2 dientes de ajo','400 g de tomate triturado','1 cucharadita de canela','Aceite de oliva','Bechamel: 60 g mantequilla, 60 g harina, 600 ml leche, nuez moscada, 1 huevo, queso rallado'],"pasos"=>['Salar las láminas de berenjena, dejar reposar 20 minutos, secar y freír o asar hasta dorar.','Sofreír la cebolla y el ajo, añadir la carne y dorar; incorporar el tomate y la canela, cocinar 20 minutos.','Preparar la bechamel derritiendo mantequilla, añadiendo harina y luego leche poco a poco hasta espesar; sazonar y añadir el huevo fuera del fuego.','Montar capas de berenjena y carne en una fuente, terminando con la bechamel y queso rallado.','Hornear a 180 °C 30-35 minutos hasta dorar.'],"consejo"=>'Deja reposar la moussaka al menos 15 minutos fuera del horno antes de cortarla: así las capas no se desmoronan.' ],
  [ "titulo"=>'Pastitsio',"descripcion"=>'Pasta larga en capas con carne picada especiada y bechamel gratinada al horno, la \'lasaña griega\'.',"tiempo"=>'1 h 20 min',"tiempoMin"=>80,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/21/Pastitsio.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Griega','Principal'],"ingredientes"=>['400 g de pasta larga tipo bucatini','500 g de carne picada','1 cebolla','Tomate triturado, canela, clavo molido','Queso rallado','Bechamel: mantequilla, harina, leche, nuez moscada, huevo'],"pasos"=>['Cocer la pasta al dente y reservar.','Sofreír la cebolla, añadir la carne y dorar; incorporar el tomate, la canela y el clavo, cocinar 20 minutos.','Preparar la bechamel como en la moussaka.','Mezclar la mitad de la bechamel con la pasta y colocarla en el fondo de una fuente; añadir la carne encima y cubrir con el resto de bechamel y queso.','Hornear a 180 °C 30 minutos hasta dorar.'],"consejo"=>'Mezclar parte de la bechamel con la pasta ayuda a que las capas se mantengan unidas al cortar.' ],
  [ "titulo"=>'Gyros de pollo',"descripcion"=>'Pollo marinado y asado en finas tiras, servido en pan de pita con tomate, cebolla, patatas y tzatziki.',"tiempo"=>'40 min + marinado',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/c/c7/Pita_giros.JPG',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Griega','Principal'],"ingredientes"=>['600 g de contramuslos de pollo en tiras','Aceite de oliva, zumo de limón','Orégano, pimentón, ajo','Pan de pita, tomate, cebolla roja','Patatas fritas, tzatziki'],"pasos"=>['Marinar el pollo con aceite, limón, orégano, pimentón y ajo al menos 1 hora.','Saltear o asar el pollo a fuego fuerte hasta que esté bien dorado y hecho por dentro.','Templar los panes de pita.','Rellenar cada pita con pollo, tomate, cebolla, patatas fritas y tzatziki, y enrollar.'],"consejo"=>'Corta el pollo en tiras finas antes de marinarlo: se cocina más rápido y de forma más uniforme.' ],
  [ "titulo"=>'Stifado',"descripcion"=>'Guiso de ternera con muchas cebollitas pequeñas enteras, canela y vino tinto, de cocción larga.',"tiempo"=>'2 h',"tiempoMin"=>120,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/b/b7/Pikilia.JPG',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Griega','Principal'],"ingredientes"=>['800 g de ternera para guisar','500 g de cebollitas pequeñas peladas','2 dientes de ajo','400 g de tomate triturado','100 ml de vinagre de vino tinto','1 rama de canela, 2 hojas de laurel, clavo','Aceite de oliva, sal'],"pasos"=>['Dorar la ternera en aceite por tandas.','Añadir el ajo y el vinagre, dejar reducir.','Incorporar el tomate, la canela, el laurel y el clavo; cubrir con agua y cocinar tapado a fuego lento 1 hora.','Añadir las cebollitas enteras y seguir cocinando 45-60 minutos más hasta que todo esté tierno.'],"consejo"=>'No cortes las cebollitas: cocinadas enteras conservan su forma y aportan un dulzor que equilibra la acidez.' ],
  [ "titulo"=>'Kleftiko',"descripcion"=>'Cordero marinado con limón, ajo y orégano, cocinado muy lentamente en un paquete sellado hasta quedar tiernísimo.',"tiempo"=>'3 h',"tiempoMin"=>180,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/49/Kleftiko.JPG',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Griega','Principal'],"ingredientes"=>['1,2 kg de paletilla de cordero','Zumo de limón, aceite de oliva','Ajo, orégano, romero','Sal, pimienta','Patatas'],"pasos"=>['Marinar el cordero con limón, aceite, ajo machacado, orégano y romero varias horas o toda la noche.','Colocar la carne con las patatas troceadas sobre papel de horno y envolver formando un paquete hermético.','Hornear a 160 °C entre 2 horas y media y 3 horas, hasta que la carne se deshaga.','Abrir el paquete los últimos 15-20 minutos para dorar la superficie.'],"consejo"=>'Sella bien el paquete de cocción: el vapor atrapado es lo que deja la carne tan tierna sin líquido añadido.' ],
  // Ensaladas y guisos
  [ "titulo"=>'Horiatiki (ensalada griega)',"descripcion"=>'La ensalada griega auténtica, con tomate, pepino, cebolla, aceitunas y un bloque entero de queso feta, sin lechuga.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/88/GreekSalad.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Griega','Entrante'],"ingredientes"=>['4 tomates maduros','1 pepino','1 cebolla roja','Un puñado de aceitunas kalamata','200 g de queso feta en un bloque','Orégano seco, aceite de oliva virgen extra, sal'],"pasos"=>['Cortar los tomates en gajos gruesos, el pepino en rodajas y la cebolla en aros finos.','Mezclar en una fuente junto con las aceitunas.','Colocar el bloque entero de feta encima, sin desmenuzar.','Aliñar con abundante aceite de oliva y espolvorear con orégano y sal.'],"consejo"=>'Sirve el feta siempre en un bloque entero: es la forma tradicional de presentar esta ensalada.' ],
  [ "titulo"=>'Gemista (verduras rellenas)',"descripcion"=>'Tomates y pimientos rellenos de arroz y hierbas, horneados hasta quedar tiernos y jugosos.',"tiempo"=>'1 h 20 min',"tiempoMin"=>80,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/ee/Gemista.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Griega','Entrante'],"ingredientes"=>['4 tomates grandes','4 pimientos','200 g de arroz','1 cebolla','Perejil y menta fresca','Aceite de oliva','Patatas (para acompañar en la bandeja)'],"pasos"=>['Vaciar los tomates y pimientos, reservando la pulpa del tomate.','Sofreír la cebolla en aceite, añadir el arroz y remover 2 minutos.','Incorporar la pulpa de tomate triturada y las hierbas, cocinar 5 minutos.','Rellenar las verduras sin apretar demasiado.','Colocar en una bandeja junto con patatas troceadas, regar con aceite y hornear a 180 °C 50-60 minutos.'],"consejo"=>'No llenes las verduras hasta el borde: el arroz aumenta de volumen al cocinarse.' ],
  [ "titulo"=>'Fasolada',"descripcion"=>'Sopa espesa de alubias blancas con verduras y aceite de oliva, considerada el plato nacional griego de cuchara.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/9/91/Fasolada.JPG',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Griega','Entrante'],"ingredientes"=>['400 g de alubias blancas (en remojo la noche anterior)','2 zanahorias, 2 ramas de apio, 1 cebolla','400 g de tomate triturado','Aceite de oliva virgen extra','Sal, perejil'],"pasos"=>['Escurrir las alubias remojadas, cubrir con agua fresca, hervir 10 minutos y escurrir de nuevo.','Cubrir otra vez con agua fresca, añadir la zanahoria, el apio y la cebolla en trozos, y cocinar 45-60 minutos.','Añadir el tomate triturado y un buen chorro de aceite, cocinar 15 minutos más.','Salar al final y servir con perejil y más aceite crudo por encima.'],"consejo"=>'Añade siempre la sal al final: si se sala el agua desde el principio, las alubias tardan mucho más en ablandarse.' ],
  // Postres
  [ "titulo"=>'Baklava',"descripcion"=>'Pasteles de capas de pasta filo, mantequilla y nueces picadas, bañados en un almíbar de miel y limón.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>8,"plato"=>'postre',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/c/c7/Baklava%281%29.png',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Griega','Postre'],"ingredientes"=>['500 g de pasta filo','300 g de nueces y almendras picadas','1 cucharadita de canela','200 g de mantequilla derretida','Almíbar: 250 g miel, 200 g azúcar, 200 ml agua, piel de limón'],"pasos"=>['Mezclar los frutos secos picados con la canela.','Forrar una bandeja con láminas de filo, pintando cada una con mantequilla derretida.','Añadir una capa fina de frutos secos cada 3-4 láminas, repitiendo hasta agotar los ingredientes.','Cortar en rombos antes de hornear a 160 °C 45-50 minutos.','Hervir la miel, el azúcar, el agua y la piel de limón 10 minutos, y verter el almíbar templado sobre el baklava recién horneado.'],"consejo"=>'El contraste de temperaturas es clave: vierte el almíbar frío sobre el baklava caliente, o al revés.' ],
  [ "titulo"=>'Loukoumades',"descripcion"=>'Pequeños buñuelos esponjosos, fritos hasta dorar y bañados en miel con canela y nueces, el dulce callejero griego.',"tiempo"=>'1 h (con fermentado)',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Griega',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/f/f9/Turkish_Lokma.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Griega','Postre'],"ingredientes"=>['300 g de harina','1 sobre de levadura seca','1 cucharadita de azúcar','Agua tibia, sal','Aceite para freír','Miel, canela molida y nueces picadas (para servir)'],"pasos"=>['Disolver la levadura y el azúcar en agua tibia y dejar activar 10 minutos.','Mezclar con la harina y la sal hasta formar una masa muy húmeda.','Dejar fermentar tapada 1 hora hasta que doble su volumen.','Formar pequeñas bolas con las manos húmedas y freír en aceite bien caliente hasta dorar de forma uniforme.','Escurrir, bañar en miel templada y espolvorear con canela y nueces.'],"consejo"=>'La masa debe quedar muy húmeda, casi imposible de amasar: esa hidratación da el interior esponjoso.' ],

  // ═══ CHINA ═══
  // Aperitivos y sopas
  [ "titulo"=>'Rollitos de primavera',"descripcion"=>'Rollitos crujientes rellenos de col, zanahoria y brotes de soja, fritos hasta dorar.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/0/09/Spring_rolls_on_sale.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['China','Entrante'],"ingredientes"=>['16 láminas de pasta para rollitos','200 g de col china en juliana','1 zanahoria rallada','100 g de brotes de soja','2 setas shiitake picadas','Salsa de soja, aceite de sésamo','Aceite para freír'],"pasos"=>['Saltear la col, la zanahoria, las setas y los brotes de soja en un wok con un poco de aceite hasta que estén tiernos pero crujientes.','Sazonar con salsa de soja y aceite de sésamo, y dejar enfriar.','Colocar una cucharada de relleno en cada lámina y enrollar bien prieto, sellando el borde con agua o harina disuelta en agua.','Freír en aceite caliente hasta que estén dorados y crujientes por todos lados.','Escurrir sobre papel absorbente antes de servir.'],"consejo"=>'Escurre bien el relleno salteado antes de enrollar: el exceso de humedad reblandece la pasta y puede romperla al freír.' ],
  [ "titulo"=>'Wonton en sopa',"descripcion"=>'Pequeñas empanadillas de cerdo y gambas servidas en un caldo claro con cebolleta, plato reconfortante muy popular.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/3/39/Pork_Steamed_Wontons.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['China','Entrante'],"ingredientes"=>['24 obleas de wonton','150 g de carne picada de cerdo','100 g de gambas picadas','Jengibre y cebolleta picados','Salsa de soja, aceite de sésamo','1 litro de caldo de pollo','Cebolleta y cilantro para servir'],"pasos"=>['Mezclar la carne, las gambas, el jengibre, la cebolleta, la soja y el aceite de sésamo hasta integrar.','Colocar una cucharadita de relleno en cada oblea, humedecer los bordes y cerrar en forma de saquito.','Cocer los wontons en agua hirviendo hasta que floten, unos 4-5 minutos.','Calentar el caldo de pollo y sazonarlo con un poco de soja.','Repartir los wontons en boles y cubrir con el caldo caliente, decorando con cebolleta y cilantro.'],"consejo"=>'Sella muy bien los bordes de cada wonton con agua: si quedan abiertos, se abren durante la cocción.' ],
  [ "titulo"=>'Arroz frito con huevo',"descripcion"=>'Arroz salteado a fuego fuerte con huevo, cebolleta y salsa de soja, la forma clásica de aprovechar el arroz sobrante.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'China',"photoUrl"=>'https://live.staticflickr.com/3097/3207760269_95c2a4b59d.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['China','Entrante'],"ingredientes"=>['500 g de arroz cocido y frío (idealmente del día anterior)','3 huevos','2 cebolletas picadas','2 cucharadas de salsa de soja','1 cucharadita de aceite de sésamo','Aceite vegetal, guisantes (opcional)'],"pasos"=>['Batir los huevos y cuajarlos en el wok en trozos grandes, retirar y reservar.','Calentar más aceite en el wok y saltear la parte blanca de la cebolleta.','Añadir el arroz frío, desmenuzando los grumos, y saltear a fuego fuerte 3-4 minutos.','Incorporar el huevo cuajado, la soja y el aceite de sésamo, mezclando bien.','Terminar con la parte verde de la cebolleta.'],"consejo"=>'Usa siempre arroz frío del día anterior: el arroz recién hecho tiene demasiada humedad y queda apelmazado al saltearlo.' ],
  // Platos principales
  [ "titulo"=>'Pollo Kung Pao',"descripcion"=>'Pollo salteado con cacahuetes, chiles secos y una salsa agridulce y ligeramente picante, plato icónico de la cocina de Sichuan.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/c/c2/Kung-pao-shanghai.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['China','Principal'],"ingredientes"=>['500 g de pechuga de pollo en dados','80 g de cacahuetes tostados','4-6 chiles secos','2 dientes de ajo, jengibre','2 cebolletas en trozos','Salsa de soja, vinagre de arroz, azúcar, maicena, aceite'],"pasos"=>['Marinar el pollo con un poco de soja y maicena durante 15 minutos.','Saltear el pollo en el wok a fuego fuerte hasta dorar, retirar y reservar.','En el mismo wok, saltear los chiles secos, el ajo y el jengibre unos segundos.','Mezclar soja, vinagre y azúcar, añadir al wok junto con el pollo y las cebolletas, saltear hasta que la salsa espese ligeramente.','Añadir los cacahuetes al final y mezclar bien.'],"consejo"=>'Saltea siempre a fuego muy fuerte y en movimiento constante: es lo que da al plato su textura y sabor característicos del wok.' ],
  [ "titulo"=>'Ternera con brócoli',"descripcion"=>'Tiras de ternera salteadas con brócoli en una salsa brillante de soja y ostras, clásico rápido de la cocina cantonesa.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/58/Beef_and_broccoli_stir_fry.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['China','Principal'],"ingredientes"=>['400 g de ternera en tiras finas','300 g de brócoli en ramilletes','2 dientes de ajo, jengibre','Salsa de soja, salsa de ostras, maicena, azúcar','Aceite vegetal'],"pasos"=>['Marinar la ternera con soja y un poco de maicena 15 minutos.','Escaldar el brócoli en agua hirviendo 2 minutos y escurrir.','Saltear la ternera en el wok a fuego fuerte hasta dorar, retirar.','Saltear el ajo y el jengibre, añadir el brócoli y la ternera de nuevo.','Incorporar la salsa de ostras, soja y azúcar disueltos con un poco de agua y maicena, y saltear hasta que espese.'],"consejo"=>'Corta la ternera en contra de la fibra: así queda mucho más tierna al saltearla a fuego fuerte.' ],
  [ "titulo"=>'Cerdo agridulce',"descripcion"=>'Trozos de cerdo rebozados y fritos, bañados en una salsa brillante agridulce con piña y pimiento.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/81/Sweet-and-sour_pork.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['China','Principal'],"ingredientes"=>['500 g de panceta o lomo de cerdo en dados','Harina, maicena, huevo','1 pimiento rojo, 1 pimiento verde','150 g de piña en trozos','Vinagre, kétchup, azúcar, salsa de soja','Aceite para freír'],"pasos"=>['Rebozar el cerdo en huevo y una mezcla de harina y maicena.','Freír en aceite caliente hasta dorar y quedar crujiente, escurrir.','Saltear los pimientos y la piña en un wok con un poco de aceite.','Mezclar vinagre, kétchup, azúcar y soja, añadir al wok y dejar espesar ligeramente.','Incorporar el cerdo frito a la salsa justo antes de servir para que no pierda el crujiente.'],"consejo"=>'Añade el cerdo a la salsa solo en el último momento: si se cocina demasiado tiempo en ella, pierde el crujiente del rebozado.' ],
  [ "titulo"=>'Mapo tofu',"descripcion"=>'Tofu suave en una salsa picante de pasta de judía fermentada y carne picada, plato picante emblemático de Sichuan.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://live.staticflickr.com/2106/2268560276_ef078caa43_b.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['China','Principal'],"ingredientes"=>['400 g de tofu sedoso en dados','150 g de carne picada de cerdo','2 cucharadas de pasta de judía fermentada (doubanjiang)','1 diente de ajo, jengibre','Salsa de soja, caldo, maicena, aceite','Cebolleta, pimienta de Sichuan molida'],"pasos"=>['Dorar la carne picada en un wok con aceite hasta que quede suelta.','Añadir el ajo, el jengibre y la pasta de judía fermentada, sofreír hasta que suelte aroma y color.','Incorporar el caldo y llevar a ebullición suave.','Añadir el tofu con cuidado para no romperlo y cocinar 5 minutos.','Espesar con un poco de maicena disuelta en agua y terminar con cebolleta y pimienta de Sichuan.'],"consejo"=>'Añade el tofu con movimientos suaves, empujando el wok en vez de remover con fuerza: se rompe con mucha facilidad.' ],
  [ "titulo"=>'Pato laqueado (estilo Pekín)',"descripcion"=>'Pato asado hasta que la piel queda crujiente y brillante, servido en finas tortitas con pepino, cebolleta y salsa hoisin.',"tiempo"=>'3 h',"tiempoMin"=>180,"dificultad"=>'Alta',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/81/Peking_Duck%2C_2014_%2802%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['China','Principal'],"ingredientes"=>['1 pato entero','Miel, salsa de soja, vinagre de arroz (para el glaseado)','Tortitas de trigo finas','Pepino y cebolleta en bastones','Salsa hoisin'],"pasos"=>['Escaldar el pato en agua hirviendo unos segundos y secarlo muy bien por dentro y por fuera.','Mezclar miel, soja y vinagre, y pintar el pato con esta mezcla; dejar secar colgado o sobre una rejilla en la nevera varias horas o toda la noche.','Asar el pato en el horno a temperatura media, pintando de vez en cuando con el glaseado, hasta que la piel esté crujiente y dorada, entre 1 y 2 horas.','Trinchar en láminas finas, procurando incluir piel y algo de carne en cada una.','Servir con las tortitas templadas, el pepino, la cebolleta y la salsa hoisin para que cada comensal se prepare su rollito.'],"consejo"=>'Secar muy bien la piel del pato antes de asarlo es el paso más importante: la humedad es el principal enemigo de una piel crujiente.' ],
  [ "titulo"=>'Chow mein',"descripcion"=>'Fideos de trigo salteados a fuego fuerte con verduras y proteína al gusto, plato rápido muy extendido en toda China.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/2a/Chicken_chow_mein_by_roland_in_Vancouver.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['China','Principal'],"ingredientes"=>['400 g de fideos de huevo cocidos','200 g de pollo o gambas','Col, zanahoria y brotes de soja','Salsa de soja, salsa de ostras','Ajo, jengibre, aceite vegetal'],"pasos"=>['Saltear el pollo o las gambas en el wok hasta dorar, reservar.','Saltear el ajo y el jengibre, añadir las verduras y saltear a fuego fuerte hasta que estén tiernas pero crujientes.','Incorporar los fideos cocidos y saltear todo junto.','Añadir la proteína reservada, la soja y la salsa de ostras, y saltear un par de minutos más para integrar.'],"consejo"=>'Cocina los fideos justo hasta el punto y enfríalos ligeramente antes de saltearlos: así no se apelmazan en el wok.' ],
  [ "titulo"=>'Costillas agridulces',"descripcion"=>'Costillas de cerdo cocinadas a fuego lento y glaseadas en una salsa brillante agridulce.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://live.staticflickr.com/3214/2596872969_663b15eb3b_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['China','Principal'],"ingredientes"=>['1 kg de costillas de cerdo troceadas','Salsa de soja, vinagre de arroz, azúcar moreno','Jengibre, ajo','Aceite, sésamo tostado'],"pasos"=>['Dorar las costillas en una olla con un poco de aceite hasta sellar por todos lados.','Añadir el jengibre y el ajo, sofreír un minuto.','Incorporar la soja, el vinagre y el azúcar disueltos con un poco de agua.','Cocinar tapado a fuego lento 40-45 minutos hasta que la carne esté tierna, destapando al final para que la salsa reduzca y glasee las costillas.','Espolvorear con sésamo tostado antes de servir.'],"consejo"=>'Destapa la olla en los últimos minutos: es el paso que permite que la salsa reduzca y se pegue bien a la carne.' ],
  [ "titulo"=>'Sopa agripicante',"descripcion"=>'Sopa espesa y aromática que combina el picante del chile con la acidez del vinagre, con tofu, setas y huevo hilado.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/3/34/AmericanChineseHotsourSoup.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['China','Principal'],"ingredientes"=>['1 litro de caldo de pollo o verduras','150 g de tofu firme en tiras','Setas shiitake en láminas','Brotes de bambú','Vinagre de arroz, salsa de soja, pimienta blanca','1 huevo batido','Maicena, aceite de sésamo, cebolleta'],"pasos"=>['Calentar el caldo con las setas y los brotes de bambú y cocinar 5 minutos.','Añadir el tofu, el vinagre, la soja y la pimienta blanca al gusto.','Espesar ligeramente con maicena disuelta en agua.','Verter el huevo batido en un hilo fino, removiendo suavemente para que se formen hebras.','Terminar con unas gotas de aceite de sésamo y cebolleta picada.'],"consejo"=>'Vierte el huevo muy despacio y en un hilo fino mientras remueves con suavidad: así se forman las hebras características en vez de grumos.' ],
  [ "titulo"=>'Berenjena a la Szechuan',"descripcion"=>'Berenjena frita en una salsa agridulce y ligeramente picante con ajo, jengibre y cebolleta, plato vegetariano muy popular de Sichuan.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://live.staticflickr.com/3216/2965910624_20e91408c8_b.jpg',"dietas"=>['Vegana','Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['China','Principal'],"ingredientes"=>['2 berenjenas grandes en bastones','2 dientes de ajo, jengibre','1 cucharada de pasta de judía fermentada (doubanjiang)','Salsa de soja, vinagre de arroz, azúcar','Maicena, aceite, cebolleta'],"pasos"=>['Salar las berenjenas y dejar reposar 10 minutos para que suelten el amargor, secar bien.','Freír las berenjenas en aceite caliente hasta que estén doradas y tiernas, escurrir.','Sofreír el ajo, el jengibre y la pasta de judía fermentada en el mismo wok.','Añadir soja, vinagre y azúcar disueltos con un poco de agua y maicena, dejar espesar.','Incorporar las berenjenas fritas a la salsa y saltear un minuto, terminando con cebolleta.'],"consejo"=>'Seca bien las berenjenas después de salarlas: si conservan mucha agua, absorben demasiado aceite al freírlas.' ],
  [ "titulo"=>'Huevo con tomate',"descripcion"=>'Huevo revuelto suave con tomate salteado, plato casero muy sencillo que se prepara a diario en los hogares chinos.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/a/a4/Huevosalplato.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['China','Principal'],"ingredientes"=>['4 huevos','3 tomates maduros','1 cucharadita de azúcar','Sal, aceite vegetal','Cebolleta picada'],"pasos"=>['Batir los huevos con una pizca de sal.','Cuajarlos en el wok con un poco de aceite, en trozos grandes y jugosos, retirar y reservar.','Saltear el tomate troceado en el mismo wok con un poco más de aceite y el azúcar, hasta que suelte su jugo y espese ligeramente.','Devolver el huevo al wok y mezclar con el tomate con cuidado.','Terminar con cebolleta picada por encima.'],"consejo"=>'No cuajes el huevo del todo la primera vez: debe quedar jugoso, porque se termina de cocinar al mezclarlo con el tomate.' ],
  // Dim sum y postres
  [ "titulo"=>'Bao de cerdo (char siu bao)',"descripcion"=>'Bollitos esponjosos al vapor rellenos de cerdo asado en salsa char siu, clásico del dim sum cantonés.',"tiempo"=>'1 h 30 min (con reposo)',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/6/6c/Char_siu_bao.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['China','Postre'],"ingredientes"=>['400 g de harina','1 sobre de levadura seca','1 cucharada de azúcar','Agua tibia','300 g de cerdo asado (char siu) troceado','Salsa hoisin, salsa de soja, azúcar (para el relleno)'],"pasos"=>['Disolver la levadura y el azúcar en agua tibia, dejar activar 10 minutos.','Amasar con la harina hasta obtener una masa suave; dejar fermentar 1 hora hasta doblar su volumen.','Mezclar el cerdo troceado con hoisin, soja y azúcar para el relleno.','Dividir la masa en porciones, aplanar, rellenar y cerrar en forma de bollito.','Cocinar al vapor 12-15 minutos hasta que estén hinchados y esponjosos.'],"consejo"=>'No abras la vaporera durante la cocción: el cambio brusco de temperatura puede hacer que los bao se deshinchen.' ],
  [ "titulo"=>'Bolas de sésamo',"descripcion"=>'Bolitas de masa de arroz glutinoso rellenas de pasta dulce de judía, rebozadas en sésamo y fritas hasta quedar crujientes por fuera.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'China',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/80/HK_KTD_%E8%A7%80%E5%A1%98%E9%81%93_414_Kwun_Tong_Road_One_Pacific_Centre_shop_%E6%B5%B7%E6%B8%AF%E9%85%92%E5%AE%B6_Victoria_Harbour_Restaurant_food_dim_sum_%E7%85%8E%E5%A0%86_sesame_ball_%E9%A3%B2%E8%8C%B6_morning_tea_April_2023_Px3_02.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['China','Postre'],"ingredientes"=>['250 g de harina de arroz glutinoso','50 g de azúcar','Agua tibia','200 g de pasta de judía dulce (anko)','Semillas de sésamo','Aceite para freír'],"pasos"=>['Mezclar la harina de arroz glutinoso con el azúcar y el agua tibia hasta formar una masa suave y elástica.','Dividir en porciones, aplanar y rellenar con una bolita de pasta de judía dulce, cerrando bien.','Humedecer cada bola y rebozarla en semillas de sésamo, presionando para que se adhieran.','Freír a fuego medio-bajo, moviéndolas con suavidad, hasta que floten y doren de manera uniforme.'],"consejo"=>'Fríe a fuego medio-bajo y con paciencia: el calor hace que se hinchen poco a poco de forma pareja.' ],

  // ═══ ITALIANA ═══
  // Entrantes
  [ "titulo"=>'Bruschetta al pomodoro',"descripcion"=>'Rebanadas de pan tostado frotadas con ajo y cubiertas de tomate fresco picado, albahaca y aceite de oliva.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Italiana',"photoUrl"=>'https://live.staticflickr.com/5037/5849235132_bae6857792_b.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Italiana','Entrante'],"ingredientes"=>['8 rebanadas de pan rústico','4 tomates maduros','2 dientes de ajo','Albahaca fresca','Aceite de oliva virgen extra','Sal'],"pasos"=>['Tostar las rebanadas de pan hasta que estén doradas y crujientes.','Frotar cada rebanada con un diente de ajo cortado por la mitad.','Picar el tomate en dados pequeños, salar y mezclar con albahaca picada y un chorro de aceite.','Repartir el tomate sobre el pan tostado justo antes de servir.'],"consejo"=>'Prepara el tomate justo antes de servir y monta la bruschetta en el último momento: el pan pierde el crujiente si se moja demasiado pronto.' ],
  [ "titulo"=>'Caprese',"descripcion"=>'Rodajas alternas de tomate y mozzarella fresca, con albahaca y aceite de oliva, la ensalada italiana más sencilla y elegante.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Italiana',"photoUrl"=>'https://live.staticflickr.com/3098/2880905477_053dbab4cb_b.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Italiana','Entrante'],"ingredientes"=>['4 tomates maduros','250 g de mozzarella fresca de búfala','Hojas de albahaca fresca','Aceite de oliva virgen extra','Sal, pimienta negra'],"pasos"=>['Cortar el tomate y la mozzarella en rodajas del mismo grosor.','Alternar las rodajas de tomate y mozzarella en un plato.','Intercalar hojas de albahaca fresca entre las rodajas.','Aliñar con aceite de oliva, sal y pimienta recién molida.'],"consejo"=>'Usa el tomate y la mozzarella a temperatura ambiente, nunca fríos de la nevera: así se aprecian mucho mejor los sabores.' ],
  [ "titulo"=>'Arancini',"descripcion"=>'Bolas de risotto rellenas de queso o ragú, rebozadas y fritas hasta quedar crujientes por fuera, especialidad siciliana.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/ee/Arancini_002.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Italiana','Entrante'],"ingredientes"=>['400 g de risotto ya cocido y frío','100 g de mozzarella en dados','Harina, huevo, pan rallado','Aceite para freír','Queso parmesano rallado'],"pasos"=>['Mezclar el risotto frío con el parmesano rallado.','Tomar una porción, hacer un hueco y rellenar con un dado de mozzarella, cerrando bien la bola.','Pasar cada bola por harina, huevo batido y pan rallado.','Freír en aceite caliente hasta que estén doradas y crujientes por fuera.','Escurrir sobre papel absorbente antes de servir.'],"consejo"=>'Usa siempre risotto frío del día anterior: el arroz caliente o recién hecho no se compacta bien para formar las bolas.' ],
  // Pasta y arroz
  [ "titulo"=>'Carbonara',"descripcion"=>'Espaguetis con una crema de huevo, queso pecorino y guanciale crujiente, sin nata, tal y como se hace en Roma.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/0/05/Classic-spaghetti-carbonara.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['400 g de espaguetis','150 g de guanciale (o panceta curada) en dados','4 yemas de huevo y 1 huevo entero','80 g de queso pecorino rallado','Pimienta negra recién molida','Sal'],"pasos"=>['Cocer los espaguetis en agua con sal hasta el punto al dente, reservando un poco del agua de cocción.','Dorar el guanciale en una sartén sin nada de aceite hasta que quede crujiente y suelte su grasa.','Batir las yemas, el huevo entero, el pecorino y abundante pimienta negra.','Escurrir la pasta y mezclarla con el guanciale y su grasa fuera del fuego.','Añadir la mezcla de huevo y queso, removiendo rápido y añadiendo un poco de agua de cocción hasta lograr una crema untuosa sin que el huevo cuaje en trozos.'],"consejo"=>'Mezcla el huevo con la pasta siempre fuera del fuego directo: el calor residual basta para cuajarlo suavemente sin que se convierta en huevo revuelto.' ],
  [ "titulo"=>'Cacio e pepe',"descripcion"=>'Pasta con una crema de queso pecorino y pimienta negra, con solo tres ingredientes, uno de los platos más técnicos de la cocina romana.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/9/99/Cacio_e_pepe.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido','Reconfortante / comfort food'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['400 g de tonnarelli o espaguetis','150 g de queso pecorino romano rallado muy fino','Pimienta negra en grano, recién molida','Sal'],"pasos"=>['Tostar ligeramente la pimienta negra molida en una sartén seca.','Cocer la pasta en agua con poca sal (el pecorino ya aporta mucha sal), reservando bastante agua de cocción.','Mezclar el pecorino rallado con un poco de agua de cocción templada hasta formar una crema sin grumos.','Escurrir la pasta al dente y mezclarla fuera del fuego con la crema de queso y la pimienta tostada, añadiendo agua de cocción poco a poco hasta ligar bien.'],"consejo"=>'Añade el agua de cocción templada, nunca hirviendo, al mezclar el queso: el calor excesivo hace que el pecorino se apelmace en grumos en vez de emulsionar.' ],
  [ "titulo"=>'Lasaña a la boloñesa',"descripcion"=>'Capas de pasta, ragú de carne cocinado a fuego lento y bechamel, gratinadas al horno con queso parmesano.',"tiempo"=>'2 h',"tiempoMin"=>120,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/b/ba/Lasagne_-_stonesoup.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['12 láminas de pasta para lasaña','500 g de carne picada de ternera y cerdo','1 cebolla, 1 zanahoria, 1 rama de apio','400 g de tomate triturado','Vino tinto','Bechamel: mantequilla, harina, leche','Queso parmesano rallado'],"pasos"=>['Sofreír la cebolla, la zanahoria y el apio picados finos hasta que estén tiernos.','Añadir la carne picada y dorar bien, luego un chorro de vino tinto y dejar reducir.','Incorporar el tomate triturado y cocinar a fuego muy lento al menos 1 hora, removiendo de vez en cuando.','Preparar la bechamel derritiendo mantequilla, añadiendo harina y luego leche poco a poco hasta espesar.','Montar capas de pasta, ragú y bechamel en una fuente, terminando con bechamel y parmesano; hornear a 180 °C 30-35 minutos.'],"consejo"=>'Cuanto más lenta sea la cocción del ragú, más profundo será su sabor: no tengas prisa en este paso.' ],
  [ "titulo"=>'Risotto alla milanese',"descripcion"=>'Risotto cremoso teñido de amarillo con azafrán, especialidad de Milán que suele acompañar al ossobuco.',"tiempo"=>'35 min',"tiempoMin"=>35,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/f/fe/Risotto_saffron_and_pistachio_nuts_%2832645475042%29.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['320 g de arroz arborio o carnaroli','1 cebolla picada muy fina','100 ml de vino blanco','1 litro de caldo de carne caliente','Unas hebras de azafrán','80 g de mantequilla, 60 g de parmesano rallado'],"pasos"=>['Sofreír la cebolla en la mitad de la mantequilla hasta que esté transparente.','Añadir el arroz y tostarlo un minuto removiendo, sin que llegue a dorarse.','Añadir el vino y dejar que se evapore.','Incorporar el caldo caliente poco a poco, cucharón a cucharón, removiendo con frecuencia y sin dejar que se seque, disolviendo el azafrán en uno de los cucharones.','Cuando el arroz esté en su punto (cremoso pero al dente), retirar del fuego y añadir el resto de la mantequilla y el parmesano, removiendo con energía (la \'mantecatura\').'],"consejo"=>'La \'mantecatura\' final —remover con fuerza fuera del fuego al añadir mantequilla y queso— es lo que le da al risotto su textura cremosa característica.' ],
  [ "titulo"=>'Ossobuco',"descripcion"=>'Jarrete de ternera con hueso, cocinado lentamente en vino blanco y verduras, tradicionalmente acompañado de risotto milanés.',"tiempo"=>'2 h',"tiempoMin"=>120,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/24/Osobuco_-_2010-10-20.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['4 rodajas de jarrete de ternera con hueso','Harina','1 cebolla, 1 zanahoria, 1 rama de apio','200 ml de vino blanco','400 g de tomate triturado','Caldo de carne','Ralladura de limón, ajo y perejil (para la gremolata)'],"pasos"=>['Enharinar las rodajas de jarrete y dorarlas bien en aceite por ambos lados; reservar.','Sofreír la cebolla, la zanahoria y el apio en la misma olla.','Añadir el vino blanco y dejar reducir.','Incorporar el tomate, el caldo y devolver la carne a la olla; cocinar tapado a fuego lento 1 hora y media hasta que esté muy tierna.','Preparar la gremolata mezclando ralladura de limón, ajo picado y perejil, y espolvorear sobre el plato justo antes de servir.'],"consejo"=>'No retires el tuétano del hueso: es una de las partes más apreciadas del plato y se puede untar directamente en el pan.' ],
  // Carnes, verduras y pizza
  [ "titulo"=>'Saltimbocca alla romana',"descripcion"=>'Filetes finos de ternera con jamón crudo y salvia, salteados y terminados con una salsa de mantequilla y vino blanco.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://live.staticflickr.com/3362/3336228234_153073b004.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['8 filetes finos de ternera','8 lonchas de jamón crudo (prosciutto)','8 hojas de salvia fresca','Harina, mantequilla','100 ml de vino blanco','Sal, pimienta'],"pasos"=>['Colocar una loncha de jamón y una hoja de salvia sobre cada filete, sujetando con un palillo.','Enharinar ligeramente por el lado de la carne.','Dorar en mantequilla, primero por el lado de la carne y luego por el del jamón, apenas 1-2 minutos por lado.','Retirar la carne, añadir el vino blanco a la sartén y dejar reducir raspando los jugos del fondo.','Verter la salsa resultante sobre la carne al servir.'],"consejo"=>'Cocina los filetes muy poco tiempo: son finos y se secan enseguida si se dejan demasiado en la sartén.' ],
  [ "titulo"=>'Parmigiana di melanzane',"descripcion"=>'Capas de berenjena frita, salsa de tomate y queso, gratinadas al horno, especialidad del sur de Italia.',"tiempo"=>'1 h 15 min',"tiempoMin"=>75,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/72/Parmigiana_di_melanzane.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['3 berenjenas grandes en láminas','800 g de tomate triturado','2 dientes de ajo, albahaca fresca','250 g de mozzarella','100 g de parmesano rallado','Aceite de oliva, sal'],"pasos"=>['Salar las láminas de berenjena y dejar reposar 20 minutos, secar y freír en aceite de oliva hasta dorar.','Preparar una salsa de tomate sencilla sofriendo el ajo y cociendo el tomate con albahaca 20 minutos.','Montar capas de berenjena frita, salsa de tomate, mozzarella y parmesano en una fuente.','Repetir las capas hasta agotar los ingredientes, terminando con queso.','Hornear a 180 °C 30-35 minutos hasta que esté bien gratinado y burbujeante.'],"consejo"=>'Deja reposar la parmigiana unos minutos fuera del horno antes de cortarla: se corta en porciones mucho más limpias.' ],
  [ "titulo"=>'Pizza margherita',"descripcion"=>'La pizza napolitana original, con solo tomate, mozzarella y albahaca, horneada a temperatura muy alta.',"tiempo"=>'2 h (con fermentado)',"tiempoMin"=>120,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/a/a3/Eq_it-na_pizza-margherita_sep2005_sml.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['500 g de harina de fuerza','325 ml de agua','10 g de sal','3 g de levadura seca','400 g de tomate triturado de calidad','250 g de mozzarella fresca escurrida','Albahaca fresca, aceite de oliva'],"pasos"=>['Disolver la levadura en el agua, mezclar con la harina y la sal y amasar 10 minutos hasta obtener una masa lisa y elástica.','Dejar fermentar tapada al menos 1 hora y media, hasta doblar su volumen.','Dividir en bolas y estirar cada una con las manos hasta lograr un disco fino con el borde más grueso.','Cubrir con tomate triturado sazonado, mozzarella escurrida troceada y un chorro de aceite.','Hornear en horno precalentado al máximo, sobre piedra si es posible, hasta que el borde esté dorado y burbujeante, unos 6-8 minutos; añadir la albahaca fresca al sacarla.'],"consejo"=>'Hornea siempre a la temperatura más alta que permita tu horno: el calor intenso y rápido es lo que da a la masa napolitana su borde esponjoso.' ],
  [ "titulo"=>'Minestrone',"descripcion"=>'Sopa espesa de verduras de temporada, alubias y pasta pequeña, cocinada lentamente con aceite de oliva.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/3/32/Minestrone_soup.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['1 cebolla, 2 zanahorias, 2 ramas de apio','1 calabacín, 200 g de judía verde','400 g de tomate triturado','200 g de alubias blancas cocidas','100 g de pasta pequeña','Caldo de verduras, aceite de oliva, parmesano'],"pasos"=>['Sofreír la cebolla, la zanahoria y el apio en aceite de oliva hasta que estén tiernos.','Añadir el calabacín y la judía verde troceados, y el tomate triturado.','Cubrir con caldo de verduras y cocinar a fuego medio 25-30 minutos.','Incorporar las alubias cocidas y la pasta, y cocinar hasta que la pasta esté al dente.','Servir con un chorro de aceite de oliva crudo y parmesano rallado.'],"consejo"=>'Añade la pasta solo en los últimos 10-12 minutos: si se cuece desde el principio, se pasa y la sopa queda espesa en exceso.' ],
  [ "titulo"=>'Vitello tonnato',"descripcion"=>'Finas lonchas de ternera fría cubiertas con una salsa cremosa de atún y alcaparras, entrante clásico del Piamonte.',"tiempo"=>'40 min + enfriado',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/9/99/Vitello_tonnato_%287169906567%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Italiana','Principal'],"ingredientes"=>['600 g de redondo de ternera','1 zanahoria, 1 rama de apio, 1 cebolla (para cocer la carne)','150 g de atún en conserva','2 yemas de huevo cocidas','Alcaparras, aceite de oliva, zumo de limón'],"pasos"=>['Cocer la ternera en agua con la zanahoria, el apio y la cebolla hasta que esté tierna, aproximadamente 1 hora; dejar enfriar en su propio caldo.','Triturar el atún con las yemas de huevo cocidas, un chorro de aceite de oliva, zumo de limón y unas alcaparras hasta obtener una salsa cremosa.','Cortar la ternera fría en lonchas muy finas.','Disponer las lonchas en un plato y cubrir con la salsa de atún.','Decorar con alcaparras enteras antes de servir bien frío.'],"consejo"=>'Cuece la carne el día anterior y déjala enfriar en la nevera: se corta en lonchas mucho más finas y limpias en frío.' ],
  // Postres
  [ "titulo"=>'Tiramisù',"descripcion"=>'Capas de bizcochos de soletilla calados en café, crema de mascarpone y cacao en polvo, sin hornear.',"tiempo"=>'30 min + reposo',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>6,"plato"=>'postre',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/b/b5/Home-made_tiramisu%2C_november_2008.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Italiana','Postre'],"ingredientes"=>['24 bizcochos de soletilla','300 ml de café fuerte ya frío','500 g de mascarpone','4 huevos (separados)','100 g de azúcar','Cacao en polvo sin azúcar'],"pasos"=>['Batir las yemas con el azúcar hasta blanquear y espesar.','Añadir el mascarpone y mezclar hasta obtener una crema lisa.','Montar las claras a punto de nieve e incorporarlas con suavidad a la crema de mascarpone.','Mojar rápidamente los bizcochos en el café y formar una capa en el fondo de una fuente.','Cubrir con la mitad de la crema, repetir con otra capa de bizcochos y terminar con el resto de la crema; refrigerar mínimo 4 horas y espolvorear con cacao antes de servir.'],"consejo"=>'Moja los bizcochos muy rápido, casi un segundo por cada lado: si se empapan demasiado, el tiramisù queda aguado.' ],
  [ "titulo"=>'Panna cotta',"descripcion"=>'Postre de nata cocida cuajada con gelatina, suave y ligeramente dulce, servido con un coulis de frutos rojos.',"tiempo"=>'20 min + reposo',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Italiana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/0/01/Panna_cotta_with_chocolate_mousse.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Italiana','Postre'],"ingredientes"=>['500 ml de nata para montar','80 g de azúcar','1 vaina de vainilla','3 hojas de gelatina','Frutos rojos y un poco de azúcar (para el coulis)'],"pasos"=>['Poner las hojas de gelatina en remojo en agua fría.','Calentar la nata con el azúcar y las semillas de la vainilla, sin dejar que hierva.','Escurrir la gelatina e incorporarla a la nata caliente, removiendo hasta que se disuelva por completo.','Repartir en moldes individuales y refrigerar al menos 4 horas hasta que cuaje.','Preparar un coulis triturando frutos rojos con un poco de azúcar, y servir junto a la panna cotta desmoldada.'],"consejo"=>'No dejes que la nata hierva con fuerza: si se calienta demasiado, la textura final queda menos sedosa.' ],

  // ═══ MEXICANA ═══
  // Salsas y aperitivos
  [ "titulo"=>'Guacamole',"descripcion"=>'Puré de aguacate machacado con lima, cilantro, cebolla y chile, la salsa mexicana más conocida en el mundo.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/7a/Lindo_Mexico_II_-_November_3_2023_-_Sarah_Stierch_02.jpg',"dietas"=>['Vegana','Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido','Reconfortante / comfort food','Ligero para la noche'],"etiquetas"=>['Mexicana','Entrante'],"ingredientes"=>['3 aguacates maduros','1/2 cebolla picada muy fina','1 tomate picado','1 chile serrano picado','Cilantro fresco picado','Zumo de 2 limas','Sal'],"pasos"=>['Machacar la pulpa de aguacate con un tenedor dejando algo de textura, no un puré fino.','Añadir la cebolla, el tomate, el chile y el cilantro.','Incorporar el zumo de lima y sal al gusto, mezclando con suavidad.','Servir de inmediato, o cubrir a piel con film para que no oxide.'],"consejo"=>'El zumo de lima no solo da sabor: su acidez retrasa la oxidación del aguacate y mantiene el guacamole verde más tiempo.' ],
  [ "titulo"=>'Pico de gallo',"descripcion"=>'Salsa fresca cruda de tomate, cebolla y chile picados en dados, sin cocinar, para acompañar cualquier plato.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/b/be/Salsa_mexicana.jpg',"dietas"=>['Vegana','Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Mexicana','Entrante'],"ingredientes"=>['4 tomates maduros picados en dados','1/2 cebolla picada fina','1-2 chiles jalapeños picados','Cilantro fresco picado','Zumo de 1 lima','Sal'],"pasos"=>['Picar el tomate, la cebolla y el chile en dados pequeños y uniformes.','Mezclar todo en un bol junto con el cilantro picado.','Añadir el zumo de lima y sal al gusto, y remover bien.','Dejar reposar 10 minutos antes de servir para que se integren los sabores.'],"consejo"=>'Retira las semillas del tomate antes de picarlo si quieres una salsa menos aguada.' ],
  [ "titulo"=>'Elote a la mexicana',"descripcion"=>'Mazorca de maíz asada, untada con mayonesa, queso rallado, chile en polvo y lima, snack callejero muy popular.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/f/f5/CookedCornOnTheCob.JPG',"dietas"=>['Vegetariana','Amante del queso','Amante del picante'],"objetivos"=>['Ligero para la noche'],"etiquetas"=>['Mexicana','Entrante'],"ingredientes"=>['4 mazorcas de maíz','Mayonesa','Queso cotija o parmesano rallado','Chile en polvo','Lima','Cilantro fresco (opcional)'],"pasos"=>['Asar las mazorcas a la parrilla o plancha, girándolas, hasta que estén doradas por todos lados.','Untar cada mazorca con una capa generosa de mayonesa.','Rebozar en queso rallado, presionando para que se adhiera.','Espolvorear con chile en polvo y un chorro de lima antes de servir.'],"consejo"=>'Asa el maíz directamente sobre la llama o brasas si es posible: el toque ligeramente tostado es parte esencial del sabor del elote.' ],
  // Platos principales
  [ "titulo"=>'Tacos al pastor',"descripcion"=>'Cerdo marinado en achiote y chiles, asado en trompo (o a la plancha) y servido en tortilla de maíz con piña y cilantro.',"tiempo"=>'1 h + marinado',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/d/d1/%28El_Flaco%29_Al_Pastor_Tacos.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['800 g de lomo de cerdo en filetes finos','Chiles guajillo y ancho, achiote','Piña, cebolla, cilantro fresco','Ajo, comino, vinagre','Tortillas de maíz'],"pasos"=>['Hidratar los chiles secos en agua caliente y triturarlos con el achiote, el ajo, el comino y el vinagre hasta obtener una pasta.','Marinar el cerdo con esta pasta al menos 2 horas, mejor toda la noche.','Asar el cerdo en una plancha muy caliente hasta que esté bien dorado y hecho, y cortar en trozos pequeños.','Asar también unas rodajas de piña hasta que se caramelicen.','Servir en tortillas de maíz calientes con el cerdo, un trozo de piña asada, cebolla y cilantro picados.'],"consejo"=>'Deja marinar el cerdo toda la noche si es posible: los chiles y el achiote necesitan tiempo para penetrar bien en la carne.' ],
  [ "titulo"=>'Enchiladas verdes',"descripcion"=>'Tortillas rellenas de pollo desmenuzado, bañadas en una salsa verde de tomatillo y gratinadas con queso y crema.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://live.staticflickr.com/3231/2740018526_ddda7f2e4a_b.jpg',"dietas"=>['Para carnívoros','Amante del queso','Amante del picante'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['12 tortillas de maíz','400 g de pechuga de pollo cocida y desmenuzada','500 g de tomatillos','2 chiles serranos','1 diente de ajo, cilantro fresco','Queso fresco rallado, crema mexicana o nata agria'],"pasos"=>['Hervir los tomatillos y los chiles hasta que estén tiernos, y triturar junto con el ajo y el cilantro hasta obtener una salsa verde.','Calentar la salsa en una sartén unos minutos.','Pasar cada tortilla brevemente por la salsa caliente para ablandarla, rellenar con pollo desmenuzado y enrollar.','Colocar las enchiladas en una fuente, cubrir con más salsa verde, queso rallado y un poco de crema.','Gratinar unos minutos en el horno antes de servir.'],"consejo"=>'Pasa las tortillas por la salsa caliente antes de rellenarlas: así se ablandan y no se rompen al enrollarlas.' ],
  [ "titulo"=>'Chiles rellenos',"descripcion"=>'Chiles poblanos asados, pelados y rellenos de queso, rebozados en huevo y fritos, bañados en salsa de tomate.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Alta',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/53/Chile_Rellenos.jpg',"dietas"=>['Vegetariana','Amante del queso','Amante del picante'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['4 chiles poblanos grandes','300 g de queso Oaxaca o similar','Harina, huevos (separados)','400 g de tomate triturado','Cebolla, ajo','Aceite para freír'],"pasos"=>['Asar los chiles directamente sobre la llama hasta que la piel se ampolle, envolver en un paño para sudar y pelar con cuidado.','Hacer un corte lateral en cada chile y retirar las semillas, dejando el tallo intacto; rellenar con el queso.','Montar las claras a punto de nieve y añadir las yemas con suavidad para hacer el rebozado.','Enharinar los chiles rellenos, pasarlos por el huevo montado y freír en aceite caliente hasta dorar por todos lados.','Preparar una salsa sencilla sofriendo cebolla y ajo con el tomate triturado, y servir los chiles bañados en ella.'],"consejo"=>'Deja los chiles asados \'sudando\' dentro de un paño o bolsa cerrada unos minutos: así se despega la piel con mucha más facilidad.' ],
  [ "titulo"=>'Mole poblano',"descripcion"=>'Salsa compleja de chiles secos, especias, frutos secos y chocolate, cocinada lentamente, tradicionalmente sobre pavo o pollo.',"tiempo"=>'2 h',"tiempoMin"=>120,"dificultad"=>'Alta',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/e7/Mole_in_Puebla.JPG',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['Piezas de pollo o pavo','Chiles mulato, ancho y pasilla','Almendras, cacahuetes, pasas','Tomate, cebolla, ajo','Canela, clavo, pimienta','Chocolate mexicano o de mesa'],"pasos"=>['Tostar los chiles secos en una sartén sin aceite, hidratarlos en agua caliente y triturarlos con el tomate, la cebolla y el ajo.','Tostar por separado las almendras, los cacahuetes y las pasas, y triturarlos con las especias.','Cocinar el pollo o el pavo hasta que esté hecho, reservando el caldo.','Sofreír la pasta de chile en una olla con un poco de aceite, añadir la pasta de frutos secos y especias, e incorporar el caldo de cocción del pollo poco a poco.','Cocinar a fuego muy lento removiendo con frecuencia durante al menos 40-50 minutos, y añadir el chocolate al final, removiendo hasta que se funda; servir sobre el pollo.'],"consejo"=>'Remueve el mole con frecuencia mientras cocina a fuego lento: al llevar frutos secos y chocolate, tiende a pegarse en el fondo de la olla.' ],
  [ "titulo"=>'Pozole rojo',"descripcion"=>'Sopa espesa de maíz cacahuazintle y cerdo en un caldo rojo de chiles secos, servida con lechuga, rábano y orégano.',"tiempo"=>'2 h',"tiempoMin"=>120,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://live.staticflickr.com/47/394809762_6a0a29d893.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['800 g de maíz cacahuazintle cocido (pozole)','800 g de carne de cerdo (aguja o costilla)','Chiles guajillo y ancho','Ajo, cebolla','Lechuga, rábano, cebolla y orégano (para servir)'],"pasos"=>['Cocer la carne de cerdo en agua con ajo y cebolla hasta que esté muy tierna, reservando el caldo.','Hidratar los chiles secos en agua caliente y triturarlos con un poco de ajo hasta obtener una salsa.','Colar la salsa de chile e incorporarla al caldo de cerdo.','Añadir el maíz cocido y la carne desmenuzada, y cocinar todo junto a fuego suave 30-40 minutos.','Servir muy caliente, acompañado de lechuga en juliana, rábano en rodajas, cebolla picada y orégano seco para que cada comensal se sirva a su gusto.'],"consejo"=>'Cuela bien la salsa de chile antes de añadirla al caldo: así el pozole queda con una textura fina, sin trozos de piel de chile.' ],
  [ "titulo"=>'Cochinita pibil',"descripcion"=>'Cerdo marinado en achiote y zumo de naranja agria, cocinado muy lentamente envuelto en hoja de plátano hasta deshacerse.',"tiempo"=>'3 h + marinado',"tiempoMin"=>180,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/84/Cochinita_pibil_2.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['1,5 kg de paleta de cerdo','100 g de pasta de achiote','Zumo de naranja agria (o naranja y lima mezcladas)','Ajo, comino, orégano','Hojas de plátano','Cebolla morada encurtida (para servir)'],"pasos"=>['Disolver la pasta de achiote en el zumo de naranja agria junto con el ajo, el comino y el orégano.','Marinar el cerdo con esta mezcla al menos 4 horas, mejor toda la noche.','Envolver el cerdo marinado en hojas de plátano ligeramente pasadas por el fuego para ablandarlas.','Cocinar en el horno a baja temperatura, 150 °C, durante 3 horas, hasta que la carne se deshaga con facilidad.','Desmenuzar la carne y servirla en tacos con cebolla morada encurtida.'],"consejo"=>'Pasa las hojas de plátano brevemente por una llama o sartén caliente antes de envolver la carne: se vuelven flexibles y no se rompen.' ],
  [ "titulo"=>'Tamales de pollo',"descripcion"=>'Masa de maíz rellena de pollo en salsa, envuelta en hoja de maíz y cocida al vapor, plato festivo en toda Mesoamérica.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Alta',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://live.staticflickr.com/7174/6789380415_ed55da2fc9_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['500 g de masa de maíz (masa harina)','250 g de manteca de cerdo','Caldo de pollo, sal, levadura en polvo','400 g de pollo cocido y desmenuzado','Salsa roja o verde','Hojas de maíz secas remojadas'],"pasos"=>['Remojar las hojas de maíz en agua caliente hasta que estén flexibles.','Batir la manteca hasta que esté esponjosa, añadir la masa, el caldo, la sal y la levadura poco a poco hasta lograr una masa suave y aireada.','Mezclar el pollo desmenuzado con la salsa roja o verde.','Extender una capa de masa sobre cada hoja de maíz, añadir una cucharada de relleno de pollo y doblar cerrando bien el tamal.','Cocer al vapor de pie, en posición vertical, durante 1 hora aproximadamente, hasta que la masa se despegue con facilidad de la hoja.'],"consejo"=>'Bate bien la manteca antes de mezclarla con la masa: cuanto más aire incorpores en este paso, más ligeros quedarán los tamales.' ],
  [ "titulo"=>'Chilaquiles verdes',"descripcion"=>'Totopos de maíz bañados en salsa verde, con crema, queso fresco y a menudo un huevo o pollo desmenuzado por encima.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://live.staticflickr.com/95/253919676_148488fa1c_b.jpg',"dietas"=>['Para carnívoros','Amante del queso','Amante del picante'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['300 g de totopos de maíz (o tortillas fritas troceadas)','500 g de tomatillos','2 chiles serranos','Ajo, cilantro','Crema mexicana, queso fresco, cebolla','Pollo desmenuzado o huevos fritos (opcional)'],"pasos"=>['Hervir los tomatillos y los chiles hasta que estén tiernos, triturar con ajo y cilantro para obtener una salsa verde.','Calentar la salsa en una sartén amplia.','Añadir los totopos y mezclar con cuidado para que se impregnen bien de salsa sin deshacerse del todo.','Servir de inmediato con crema, queso fresco desmenuzado, cebolla picada y, si se desea, pollo desmenuzado o un huevo frito por encima.'],"consejo"=>'Sirve los chilaquiles inmediatamente después de mezclar los totopos con la salsa caliente: si esperas demasiado, pierden el punto crujiente.' ],
  [ "titulo"=>'Sopa de tortilla',"descripcion"=>'Caldo de tomate y chile con tiras de tortilla frita, aguacate y queso, plato de cuchara muy popular en México.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/9/9a/Tortilla_Soup.jpg',"dietas"=>['Para carnívoros','Amante del queso','Amante del picante'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['6 tortillas de maíz en tiras','1 litro de caldo de pollo','4 tomates','1 chile ancho, 1 diente de ajo, 1/2 cebolla','Aguacate, queso fresco, crema, aceite para freír'],"pasos"=>['Freír las tiras de tortilla en aceite hasta que estén doradas y crujientes; escurrir.','Asar el tomate, el ajo y la cebolla, y triturarlos junto con el chile ancho hidratado.','Sofreír esta salsa en una olla, añadir el caldo de pollo y cocinar 15-20 minutos.','Servir el caldo caliente en boles con las tiras de tortilla, aguacate en dados, queso fresco y un poco de crema por encima.'],"consejo"=>'Añade las tortillas fritas justo antes de servir, no dentro del caldo hirviendo: así conservan parte de su textura crujiente.' ],
  [ "titulo"=>'Carnitas',"descripcion"=>'Cerdo cocinado lentamente en su propia grasa hasta quedar tierno por dentro y dorado por fuera, base de innumerables tacos.',"tiempo"=>'3 h',"tiempoMin"=>180,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/e6/Carnitas_in_Mexico.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Mexicana','Principal'],"ingredientes"=>['1,5 kg de paleta de cerdo en trozos grandes','Manteca de cerdo o aceite','Naranja, ajo, hoja de laurel','Sal, comino','Tortillas de maíz para servir'],"pasos"=>['Colocar el cerdo en una olla amplia con manteca, el zumo y la piel de naranja, el ajo, el laurel, la sal y el comino.','Cubrir apenas con agua y cocinar a fuego lento y constante durante 2 horas, hasta que la carne esté muy tierna.','Subir el fuego los últimos 20-30 minutos, sin tapar, dejando que el agua se evapore y la carne se dore en su propia grasa.','Desmenuzar la carne con dos tenedores, dejando algunos trozos crujientes.','Servir en tacos calientes con cebolla, cilantro y una salsa al gusto.'],"consejo"=>'No tengas prisa en la fase final de dorado: es el paso que da a las carnitas su contraste entre lo tierno de dentro y lo crujiente de fuera.' ],
  // Postres
  [ "titulo"=>'Flan mexicano',"descripcion"=>'Postre cremoso de huevo y leche condensada bañado en caramelo, versión mexicana del flan clásico.',"tiempo"=>'1 h + refrigeración',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'postre',"cocina"=>'Mexicana',"photoUrl"=>'https://live.staticflickr.com/1261/4603207498_98229a1879_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Mexicana','Postre'],"ingredientes"=>['150 g de azúcar (para el caramelo)','4 huevos','1 lata de leche condensada','1 lata de leche evaporada','1 cucharadita de esencia de vainilla'],"pasos"=>['Derretir el azúcar en un molde a fuego medio hasta obtener un caramelo dorado, y repartirlo por el fondo del molde.','Batir los huevos con la leche condensada, la leche evaporada y la vainilla hasta integrar bien, sin batir en exceso para no generar demasiada espuma.','Verter la mezcla sobre el caramelo en el molde.','Cocinar al baño maría en el horno a 160 °C durante 50-60 minutos, hasta que esté cuajado pero aún tiemble ligeramente en el centro.','Dejar enfriar por completo y refrigerar varias horas antes de desmoldar.'],"consejo"=>'Cocina siempre al baño maría: el calor directo del horno hace que el flan se llene de agujeros en vez de quedar liso y cremoso.' ],
  [ "titulo"=>'Churros con chocolate',"descripcion"=>'Masa frita en forma de tira acanalada, rebozada en azúcar y canela, servida con chocolate caliente espeso para mojar.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Mexicana',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/47/Chocolate_con_churros_de_lazo.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Mexicana','Postre'],"ingredientes"=>['250 ml de agua','50 g de mantequilla','1 cucharadita de sal','150 g de harina','Aceite para freír','Azúcar y canela molida (para rebozar)','200 g de chocolate negro, 300 ml de leche (para el chocolate caliente)'],"pasos"=>['Hervir el agua con la mantequilla y la sal; retirar del fuego y añadir la harina de golpe, removiendo enérgicamente hasta formar una masa lisa que se despegue de las paredes.','Dejar templar unos minutos e introducir la masa en una manga pastelera con boquilla en forma de estrella.','Freír tiras de masa directamente en aceite caliente, cortándolas con unas tijeras, hasta que estén doradas y crujientes.','Escurrir y rebozar en una mezcla de azúcar y canela mientras aún están calientes.','Calentar la leche con el chocolate troceado, removiendo hasta obtener un chocolate espeso, y servir junto a los churros.'],"consejo"=>'La masa debe estar templada, ni caliente ni fría, al meterla en la manga: si está demasiado caliente puede deformarse al freír.' ],

  // ═══ TAILANDESA ═══
  // Sopas y ensaladas
  [ "titulo"=>'Tom yum goong',"descripcion"=>'Sopa picante y ácida de gambas con hierba limón, galanga y hojas de lima kaffir, la sopa tailandesa más conocida.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/25/Tomyumgoongguys.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Tailandesa','Entrante'],"ingredientes"=>['500 g de gambas con cáscara','1 litro de caldo de pescado o agua','2 tallos de hierba limón','4 hojas de lima kaffir','Galanga en rodajas','2-3 chiles tailandeses','Zumo de lima, salsa de pescado','Setas de paja o champiñones'],"pasos"=>['Pelar las gambas y reservar las cáscaras para dar sabor al caldo.','Llevar el caldo a ebullición con las cáscaras de gamba, la hierba limón golpeada, la galanga y las hojas de lima kaffir; cocinar 10 minutos y colar si se desea un caldo más limpio.','Añadir las setas y cocinar 3-4 minutos.','Incorporar las gambas peladas y cocinar hasta que cambien de color, apenas 2-3 minutos.','Retirar del fuego y sazonar con salsa de pescado, zumo de lima y chile picado al gusto.'],"consejo"=>'Añade el zumo de lima siempre al final, fuera del fuego: si hierve, pierde su frescor ácido característico.' ],
  [ "titulo"=>'Tom kha gai',"descripcion"=>'Sopa cremosa de pollo con leche de coco, galanga y hierba limón, más suave que el tom yum.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Tailandesa',"photoUrl"=>'https://live.staticflickr.com/4064/4531486182_a8b00866bd_b.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Tailandesa','Entrante'],"ingredientes"=>['400 g de pechuga de pollo en tiras','400 ml de leche de coco','500 ml de caldo de pollo','Galanga, hierba limón, hojas de lima kaffir','Setas, salsa de pescado, zumo de lima','Chile fresco, cilantro'],"pasos"=>['Calentar el caldo de pollo con la galanga en rodajas, la hierba limón golpeada y las hojas de lima kaffir, 10 minutos a fuego suave.','Añadir la leche de coco y llevar a un hervor suave, sin que hierva con fuerza.','Incorporar el pollo y las setas, cocinar hasta que el pollo esté hecho, unos 8-10 minutos.','Sazonar con salsa de pescado y zumo de lima al final.','Servir decorado con chile fresco en rodajas y cilantro.'],"consejo"=>'Cocina la leche de coco siempre a fuego suave: un hervor demasiado fuerte puede hacer que se corte.' ],
  [ "titulo"=>'Som tam (ensalada de papaya verde)',"descripcion"=>'Ensalada picante y ácida de papaya verde rallada, tomate, judía larga y cacahuetes, machacada en mortero.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/1/1c/%E0%B8%95%E0%B8%B3%E0%B9%84%E0%B8%97%E0%B8%A2%E0%B9%84%E0%B8%82%E0%B9%88%E0%B9%80%E0%B8%84%E0%B9%87%E0%B8%A1_%E0%B8%AA%E0%B9%89%E0%B8%A1%E0%B8%95%E0%B8%B3_%E0%B8%95%E0%B8%B3%E0%B8%96%E0%B8%B2%E0%B8%94_Tumtaad_%E0%B8%81%E0%B8%A3%E0%B8%B0%E0%B8%9A%E0%B8%B5%E0%B9%88_01.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Ligero para la noche'],"etiquetas"=>['Tailandesa','Entrante'],"ingredientes"=>['1 papaya verde rallada en tiras finas','2 tomates cherry por comensal','Judía larga en trozos','2-3 chiles tailandeses','2 dientes de ajo','Cacahuetes tostados','Zumo de lima, salsa de pescado, azúcar de palma'],"pasos"=>['Machacar el ajo y el chile en un mortero grande.','Añadir los tomates cherry y la judía larga, y machacar suavemente para que suelten su jugo sin deshacerse del todo.','Incorporar la papaya rallada y seguir machacando y mezclando con el mortero para que se impregne de los sabores.','Sazonar con salsa de pescado, azúcar de palma y zumo de lima.','Servir espolvoreado con cacahuetes tostados.'],"consejo"=>'Machaca con movimientos suaves de golpeo, no de trituración: el objetivo es que los ingredientes suelten su jugo sin convertirse en puré.' ],
  // Curries y platos principales
  [ "titulo"=>'Pad thai',"descripcion"=>'Fideos de arroz salteados con gambas, huevo, cacahuetes y tamarindo, el plato de fideos más internacional de Tailandia.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/3/39/Phat_Thai_kung_Chang_Khien_street_stall.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['300 g de fideos de arroz planos','300 g de gambas peladas','2 huevos','100 g de brotes de soja','Cacahuetes tostados picados','Pasta de tamarindo, salsa de pescado, azúcar de palma','Cebolleta, lima, cilantro'],"pasos"=>['Remojar los fideos de arroz en agua templada hasta que estén flexibles pero firmes, y escurrir.','Saltear las gambas en un wok con un poco de aceite hasta que cambien de color, retirar y reservar.','En el mismo wok, cuajar el huevo en trozos grandes.','Añadir los fideos, la pasta de tamarindo, la salsa de pescado y el azúcar de palma, saltear a fuego fuerte mezclando bien.','Incorporar las gambas, los brotes de soja y la mitad de los cacahuetes; servir con más cacahuetes, cebolleta, lima y cilantro.'],"consejo"=>'No remojes los fideos hasta que estén blandos del todo: terminan de cocinarse en el wok y si ya están muy blandos se rompen al saltear.' ],
  [ "titulo"=>'Curry verde de pollo',"descripcion"=>'Pollo cocinado en una salsa cremosa de leche de coco y pasta de curry verde, con berenjenas tailandesas y albahaca.',"tiempo"=>'35 min',"tiempoMin"=>35,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/e5/Thai_green_chicken_curry_and_roti.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['500 g de pechuga de pollo en tiras','3 cucharadas de pasta de curry verde','400 ml de leche de coco','Berenjenas tailandesas o normales en trozos','Hojas de lima kaffir','Salsa de pescado, azúcar de palma','Albahaca tailandesa'],"pasos"=>['Calentar la parte más espesa de la leche de coco en un wok hasta que suelte su aceite.','Añadir la pasta de curry verde y sofreír 2-3 minutos hasta que suelte aroma.','Incorporar el pollo y saltear hasta que cambie de color por fuera.','Añadir el resto de la leche de coco, la berenjena y las hojas de lima kaffir, cocinar a fuego medio 15 minutos.','Sazonar con salsa de pescado y azúcar de palma, y terminar con albahaca fresca.'],"consejo"=>'Sofríe siempre la pasta de curry en la parte grasa de la leche de coco antes de añadir el líquido: así se libera todo su aroma.' ],
  [ "titulo"=>'Curry rojo de ternera',"descripcion"=>'Ternera guisada en una salsa densa de curry rojo y leche de coco, con un punto picante más intenso que el curry verde.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'https://live.staticflickr.com/2505/4007987203_b5bcf87596_b.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['600 g de ternera para guisar','3 cucharadas de pasta de curry rojo','400 ml de leche de coco','Pimiento rojo en tiras','Hojas de lima kaffir','Salsa de pescado, azúcar de palma','Albahaca tailandesa'],"pasos"=>['Calentar la parte espesa de la leche de coco y sofreír la pasta de curry rojo hasta que suelte aroma.','Añadir la ternera y dorarla por todos lados.','Incorporar el resto de la leche de coco y las hojas de lima kaffir, cubrir y cocinar a fuego lento 40-45 minutos hasta que la carne esté tierna.','Añadir el pimiento los últimos 10 minutos.','Sazonar con salsa de pescado y azúcar de palma, y terminar con hojas de albahaca.'],"consejo"=>'Cocina la ternera a fuego lento y tapada: es lo que permite que se ablande sin que la salsa de coco se corte.' ],
  [ "titulo"=>'Pad see ew',"descripcion"=>'Fideos de arroz anchos salteados con col china y huevo en una salsa oscura de soja dulce, plato callejero muy popular.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'https://live.staticflickr.com/5076/5822460141_7d22a9b6bb_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['400 g de fideos de arroz anchos frescos','300 g de ternera o pollo en tiras finas','Col china en hojas','2 huevos','Salsa de soja oscura dulce, salsa de soja normal','Ajo, aceite'],"pasos"=>['Saltear la carne en el wok con ajo hasta dorar, retirar y reservar.','Cuajar el huevo en el mismo wok en trozos grandes.','Añadir los fideos y la col china, saltear a fuego fuerte con cuidado de no romper los fideos.','Incorporar la salsa de soja oscura dulce y la salsa de soja normal.','Devolver la carne al wok y mezclar todo bien antes de servir.'],"consejo"=>'Usa fuego muy alto y mueve el wok en vez de remover en exceso con la espátula: así los fideos anchos no se rompen.' ],
  [ "titulo"=>'Larb de pollo',"descripcion"=>'Ensalada picante de carne de pollo picada con hierbas frescas, lima y arroz tostado molido, típica del noreste de Tailandia.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/4a/LaoFood_LarbNeua.JPG',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['500 g de pollo picado','2 cucharadas de arroz glutinoso crudo (para tostar y moler)','Chile en polvo, salsa de pescado','Zumo de lima','Chalota, cebolleta, menta y cilantro frescos'],"pasos"=>['Tostar el arroz crudo en una sartén seca hasta que esté dorado, y molerlo hasta obtener un polvo grueso.','Cocinar el pollo picado en una sartén con un poco de agua, removiendo hasta que esté hecho y suelto.','Retirar del fuego y añadir la salsa de pescado, el zumo de lima y el chile en polvo.','Incorporar la chalota, la cebolleta y las hierbas frescas picadas.','Terminar con el arroz tostado molido justo antes de servir.'],"consejo"=>'Añade el arroz tostado molido solo al final: si se cocina con el pollo, pierde su textura crujiente característica.' ],
  [ "titulo"=>'Satay de pollo con salsa de cacahuete',"descripcion"=>'Brochetas de pollo marinadas en especias y leche de coco, asadas y servidas con una salsa cremosa de cacahuete.',"tiempo"=>'30 min + marinado',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/24/Sate_Udang.JPG',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['600 g de pechuga de pollo en tiras','Leche de coco, curry en polvo, cúrcuma','Salsa de cacahuete: cacahuetes molidos, leche de coco, pasta de curry rojo, salsa de pescado, azúcar'],"pasos"=>['Marinar el pollo con leche de coco, curry en polvo y cúrcuma durante al menos 1 hora.','Ensartar las tiras de pollo en brochetas de madera previamente remojadas en agua.','Asar a la parrilla o plancha hasta que estén doradas y hechas por dentro.','Preparar la salsa calentando leche de coco con la pasta de curry rojo, añadiendo los cacahuetes molidos, la salsa de pescado y el azúcar hasta espesar.','Servir las brochetas calientes con la salsa de cacahuete para mojar.'],"consejo"=>'Remoja las brochetas de madera en agua al menos 20 minutos antes de usarlas: así no se queman al asar el pollo.' ],
  [ "titulo"=>'Massaman curry de cordero',"descripcion"=>'Curry suave y aromático de influencia persa, con cordero, patata y cacahuetes, más dulce y menos picante que otros curries tailandeses.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/b/b5/Kaeng_matsaman_kai.JPG',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['600 g de cordero para guisar','3 cucharadas de pasta de curry massaman','400 ml de leche de coco','Patatas en trozos','Cacahuetes tostados','Canela, anís estrellado','Salsa de pescado, azúcar de palma, tamarindo'],"pasos"=>['Sofreír la pasta de curry massaman en la parte espesa de la leche de coco hasta que suelte aroma.','Añadir el cordero y dorarlo por todos lados.','Incorporar el resto de la leche de coco, la canela y el anís estrellado, cubrir y cocinar a fuego lento 1 hora.','Añadir las patatas y los cacahuetes, y cocinar 20-30 minutos más hasta que todo esté tierno.','Sazonar con salsa de pescado, azúcar de palma y un poco de tamarindo al gusto.'],"consejo"=>'La cocción larga y lenta es clave: el massaman gana profundidad de sabor cuanto más tiempo se cocina a fuego suave.' ],
  [ "titulo"=>'Khao pad (arroz frito tailandés)',"descripcion"=>'Arroz salteado con huevo, cebolla y proteína al gusto, sazonado con salsa de pescado y servido con lima.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/50/Thaifriedrice.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['500 g de arroz jazmín cocido y frío','200 g de pollo o gambas','2 huevos','1 cebolla, ajo','Salsa de pescado, salsa de soja','Lima, cebolleta, cilantro'],"pasos"=>['Saltear el ajo y la cebolla en un wok caliente.','Añadir el pollo o las gambas y saltear hasta que estén hechos, retirar y reservar.','Cuajar el huevo en el mismo wok en trozos grandes.','Añadir el arroz frío desmenuzando los grumos, saltear a fuego fuerte, e incorporar la proteína reservada.','Sazonar con salsa de pescado y soja, y servir con lima, cebolleta y cilantro.'],"consejo"=>'Usa siempre arroz frío del día anterior: el arroz recién hecho queda apelmazado al saltearlo en el wok.' ],
  [ "titulo"=>'Pla rad prik',"descripcion"=>'Pescado entero frito hasta quedar crujiente, bañado en una salsa dulce, ácida y picante de chile y tamarindo.',"tiempo"=>'35 min',"tiempoMin"=>35,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['1 pescado entero (dorada o similar), limpio','Harina o maicena para rebozar','Aceite para freír','Chiles rojos, ajo','Salsa de pescado, azúcar de palma, tamarindo','Cilantro fresco'],"pasos"=>['Hacer unos cortes diagonales en el pescado, secarlo bien y rebozarlo ligeramente en maicena.','Freír en aceite bien caliente hasta que quede dorado y crujiente por ambos lados; escurrir.','Triturar o picar muy fino el chile y el ajo, y sofreír brevemente en un poco de aceite.','Añadir salsa de pescado, azúcar de palma y tamarindo, cocinar hasta obtener una salsa espesa y brillante.','Bañar el pescado frito con la salsa caliente y decorar con cilantro fresco.'],"consejo"=>'Seca muy bien el pescado antes de freírlo: la humedad hace que salpique y que la piel no quede crujiente.' ],
  [ "titulo"=>'Tod mun pla (pastelitos de pescado)',"descripcion"=>'Pastelitos fritos de pasta de pescado con pasta de curry rojo y judía larga picada, crujientes por fuera y elásticos por dentro.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/f/fc/Thanin_market_banana_flowers_and_leaves.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Tailandesa','Principal'],"ingredientes"=>['500 g de filete de pescado blanco','2 cucharadas de pasta de curry rojo','1 huevo','Judía larga picada fina','Hojas de lima kaffir picadas','Salsa de pescado, aceite para freír'],"pasos"=>['Triturar el pescado con la pasta de curry rojo, el huevo y la salsa de pescado hasta obtener una pasta elástica y pegajosa.','Incorporar la judía larga y las hojas de lima kaffir picadas, mezclando bien a mano.','Formar pequeñas hamburguesitas planas con las manos húmedas.','Freír en aceite medio-caliente 3-4 minutos por lado hasta que estén doradas y bien cocinadas por dentro.','Escurrir sobre papel absorbente y servir con salsa dulce de pepino.'],"consejo"=>'Trabaja la pasta de pescado con energía, casi golpeándola contra el bol: ese amasado es lo que le da la textura elástica característica.' ],
  // Postres
  [ "titulo"=>'Mango sticky rice',"descripcion"=>'Arroz glutinoso cocido al vapor y bañado en leche de coco dulce, servido con láminas de mango fresco maduro.',"tiempo"=>'1 h (con remojo)',"tiempoMin"=>60,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Tailandesa',"photoUrl"=>'https://live.staticflickr.com/4094/4887701660_9f5c750a21_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Tailandesa','Postre'],"ingredientes"=>['300 g de arroz glutinoso','400 ml de leche de coco','80 g de azúcar','Una pizca de sal','2 mangos maduros','Semillas de sésamo tostado (opcional)'],"pasos"=>['Remojar el arroz glutinoso en agua al menos 4 horas o toda la noche.','Escurrir y cocinar al vapor sobre un paño durante 20-25 minutos hasta que esté tierno y translúcido.','Calentar la leche de coco con el azúcar y la sal, sin dejar que hierva, hasta que se disuelvan.','Mezclar la mayor parte de esta leche de coco con el arroz caliente y dejar reposar 10 minutos para que la absorba.','Servir el arroz con láminas de mango fresco al lado y el resto de la leche de coco por encima.'],"consejo"=>'Remoja el arroz glutinoso el tiempo necesario: si no se hidrata lo suficiente, queda duro por dentro aunque parezca cocido por fuera.' ],
  [ "titulo"=>'Khanom krok (buñuelos de coco)',"descripcion"=>'Pequeños buñuelos de coco cocinados en una sartén especial con moldes redondos, crujientes por fuera y cremosos por dentro.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Tailandesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/55/Khanom_Krok.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Tailandesa','Postre'],"ingredientes"=>['200 g de harina de arroz','400 ml de leche de coco','80 g de azúcar','Una pizca de sal','Coco rallado fresco','Cebolleta picada (opcional, para la versión salada)'],"pasos"=>['Mezclar la harina de arroz con la mitad de la leche de coco, el azúcar y la sal hasta obtener una masa fluida sin grumos.','Preparar por separado una crema más espesa con el resto de la leche de coco y un poco de harina de arroz, para la cobertura.','Calentar una sartén de moldes redondos (o una sartén antiadherente pequeña) y engrasar ligeramente cada hueco.','Verter la masa base hasta la mitad de cada molde, cocinar a fuego medio-bajo unos minutos hasta que se forme una base firme.','Cubrir con la crema espesa de coco y terminar de cocinar tapado hasta que cuaje; desmoldar con cuidado y servir templados.'],"consejo"=>'Cocina a fuego medio-bajo y con paciencia: el fuego fuerte quema la base antes de que el centro llegue a cuajar.' ],

  // ═══ MARROQUÍ ═══
  // Sopas y aperitivos
  [ "titulo"=>'Harira',"descripcion"=>'Sopa espesa de lentejas, garbanzos y tomate, especiada con cilantro y canela, tradicional para romper el ayuno del Ramadán.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/c/ce/Harira.png',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Marroquí','Entrante'],"ingredientes"=>['150 g de lentejas','150 g de garbanzos cocidos','400 g de tomate triturado','1 cebolla','Apio, cilantro y perejil fresco','Canela, jengibre, cúrcuma','Harina (para espesar), zumo de limón'],"pasos"=>['Sofreír la cebolla y el apio picados con las especias hasta que suelten aroma.','Añadir el tomate triturado y cocinar 10 minutos.','Incorporar las lentejas, los garbanzos y agua o caldo, cocinar a fuego medio 30-40 minutos hasta que las lentejas estén tiernas.','Disolver un poco de harina en agua fría y añadirla a la sopa removiendo, para espesarla ligeramente.','Terminar con cilantro y perejil frescos picados y un chorro de limón.'],"consejo"=>'Añade la harina disuelta poco a poco y removiendo sin parar: de golpe forma grumos en vez de espesar de manera uniforme.' ],
  [ "titulo"=>'Zaalouk',"descripcion"=>'Ensalada cocida de berenjena y tomate especiada con comino y pimentón, se sirve fría o templada como aperitivo.',"tiempo"=>'35 min',"tiempoMin"=>35,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Marroquí',"photoUrl"=>'https://live.staticflickr.com/65535/52604703761_0611d6a09c_b.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Marroquí','Entrante'],"ingredientes"=>['2 berenjenas','3 tomates maduros','2 dientes de ajo','Comino, pimentón, aceite de oliva','Cilantro fresco, sal'],"pasos"=>['Asar o cocer al vapor las berenjenas hasta que estén muy tiernas, y triturar la pulpa.','Pelar y triturar los tomates.','Sofreír el ajo en aceite de oliva, añadir el tomate y las especias, cocinar 10 minutos.','Incorporar la berenjena triturada y cocinar a fuego suave 15 minutos, removiendo, hasta que espese.','Terminar con cilantro fresco picado y servir templado o frío.'],"consejo"=>'Cocina a fuego lento y remueve con frecuencia: el zaalouk debe quedar con una textura de puré espeso, sin restos de líquido.' ],
  [ "titulo"=>'Briouats de queso',"descripcion"=>'Pequeños triángulos de pasta warqa rellenos de queso, fritos hasta quedar crujientes, aperitivo habitual en las mesas marroquíes.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/72/Moroccan_food-02.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Marroquí','Entrante'],"ingredientes"=>['16 láminas de pasta warqa o filo','300 g de queso fresco tipo feta o similar','1 huevo','Perejil picado','Aceite para freír'],"pasos"=>['Mezclar el queso desmenuzado con el huevo y el perejil picado.','Cortar las láminas de pasta en tiras largas.','Colocar una cucharadita de relleno en un extremo y doblar en forma de triángulo, como una bandera, hasta llegar al final de la tira.','Sellar el borde con un poco de agua o huevo batido.','Freír en aceite caliente hasta que estén dorados y crujientes por todos lados.'],"consejo"=>'Trabaja con la pasta cubierta con un paño húmedo mientras rellenas los briouats: se seca y agrieta con mucha facilidad al aire.' ],
  // Tagines y platos principales
  [ "titulo"=>'Cordero tagine con ciruelas',"descripcion"=>'Cordero guisado lentamente con ciruelas pasas, almendras y especias dulces, un clásico agridulce de la cocina marroquí.',"tiempo"=>'2 h',"tiempoMin"=>120,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/3/3a/Tajine-marocain-un-plat-varie-et-sain_%28cropped%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Marroquí','Principal'],"ingredientes"=>['800 g de cordero para guisar','1 cebolla','Jengibre, canela, cúrcuma','200 g de ciruelas pasas','Almendras tostadas','Miel, aceite de oliva'],"pasos"=>['Dorar el cordero en aceite de oliva junto con la cebolla picada.','Añadir las especias y cubrir con agua, cocinar tapado a fuego lento 1 hora y media hasta que la carne esté tierna.','Incorporar las ciruelas pasas y un poco de miel, y cocinar 20-30 minutos más hasta que la salsa espese.','Servir decorado con almendras tostadas por encima.'],"consejo"=>'Deja que la salsa reduzca sin tapa en los últimos minutos: es lo que concentra el dulzor de las ciruelas y la miel.' ],
  [ "titulo"=>'Pollo tagine con limón confitado y aceitunas',"descripcion"=>'Pollo guisado con limón confitado, aceitunas y especias, uno de los tagines más representativos de Marruecos.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/3/3a/Tajine-marocain-un-plat-varie-et-sain_%28cropped%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Marroquí','Principal'],"ingredientes"=>['1 pollo troceado','1 cebolla','Jengibre, cúrcuma, comino','2 limones confitados','Aceitunas verdes o violeta','Cilantro fresco, aceite de oliva'],"pasos"=>['Dorar el pollo en aceite de oliva junto con la cebolla picada y las especias.','Cubrir con agua o caldo y cocinar tapado a fuego medio 30-35 minutos.','Añadir el limón confitado troceado y las aceitunas, cocinar 15 minutos más.','Terminar con cilantro fresco picado antes de servir.'],"consejo"=>'Enjuaga ligeramente el limón confitado antes de añadirlo si prefieres un sabor menos intenso, ya que puede ser muy salado.' ],
  [ "titulo"=>'Kefta tagine (albóndigas en salsa de tomate)',"descripcion"=>'Albóndigas de carne especiada cocinadas en una salsa de tomate especiada, con huevos escalfados encima al final.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Marroquí',"photoUrl"=>'https://live.staticflickr.com/3597/3697198543_7be1180b72_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Marroquí','Principal'],"ingredientes"=>['500 g de carne picada de ternera o cordero','Cebolla, perejil y cilantro picados','Comino, pimentón','400 g de tomate triturado','4 huevos','Aceite de oliva'],"pasos"=>['Mezclar la carne picada con cebolla rallada, perejil, cilantro, comino y pimentón, y formar pequeñas albóndigas.','Preparar una salsa sofriendo cebolla y añadiendo el tomate triturado con especias, cocinar 15 minutos.','Añadir las albóndigas a la salsa y cocinar a fuego medio 15-20 minutos, moviendo la cazuela con suavidad para que no se rompan.','Cascar los huevos directamente sobre la salsa los últimos minutos y dejar que cuajen tapado.'],"consejo"=>'No remuevas las albóndigas con cuchara una vez en la salsa: mueve la cazuela con la mano para que no se deshagan.' ],
  [ "titulo"=>'Cuscús con siete verduras',"descripcion"=>'Sémola de trigo cocida al vapor, acompañada de un guiso de siete verduras y garbanzos, plato festivo del viernes en Marruecos.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/0/0c/Moroccan_cuscus%2C_from_Casablanca%2C_September_2018.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Marroquí','Principal'],"ingredientes"=>['500 g de sémola de cuscús','Zanahoria, calabacín, nabo, calabaza, col, patata','200 g de garbanzos cocidos','Cebolla, jengibre, cúrcuma, canela','Aceite de oliva, caldo o agua'],"pasos"=>['Sofreír la cebolla con las especias en una olla ancha.','Añadir las verduras más duras (zanahoria, nabo) y cubrir con agua o caldo, cocinar 20 minutos.','Incorporar el resto de verduras y los garbanzos, y seguir cocinando hasta que todas estén tiernas.','Hidratar la sémola de cuscús con un poco de agua y aceite, y cocinarla al vapor sobre el guiso o siguiendo las instrucciones del paquete, esponjándola con un tenedor.','Servir la sémola con las verduras y el caldo del guiso por encima.'],"consejo"=>'Esponja la sémola con un tenedor varias veces durante el proceso: es lo que evita que quede apelmazada en bloques.' ],
  [ "titulo"=>'Mechoui (cordero asado)',"descripcion"=>'Cordero asado muy lentamente hasta que la carne se separa del hueso con solo tocarla, condimentado con especias sencillas.',"tiempo"=>'3 h 30 min',"tiempoMin"=>210,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/9/96/Mechoui.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Marroquí','Principal'],"ingredientes"=>['1 pierna o paletilla de cordero grande','Mantequilla, aceite de oliva','Comino, sal, pimentón','Ajo'],"pasos"=>['Frotar el cordero con una mezcla de mantequilla derretida, aceite, ajo machacado, comino, pimentón y sal.','Colocar en una bandeja de horno y cubrir con papel de aluminio.','Asar a temperatura baja, 150 °C, durante al menos 3 horas, regando de vez en cuando con sus propios jugos.','Destapar los últimos 20-30 minutos para dorar bien la superficie.','Servir espolvoreado con más comino y sal, para que cada comensal moje la carne al gusto.'],"consejo"=>'La clave del mechoui es la temperatura baja y el tiempo largo: no tengas prisa, es lo que hace que la carne se separe del hueso sin necesidad de cuchillo.' ],
  [ "titulo"=>'Rfissa',"descripcion"=>'Plato reconfortante de pollo y lentejas con especias, servido sobre trozos de pan plano o msemen deshilachado.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Marroquí',"photoUrl"=>'https://live.staticflickr.com/454/20110756839_c68705420d_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Marroquí','Principal'],"ingredientes"=>['1 pollo troceado','150 g de lentejas','1 cebolla','Jengibre, cúrcuma, ras el hanout','Pan msemen o pan plano troceado','Cilantro fresco'],"pasos"=>['Dorar el pollo con la cebolla y las especias en una olla con un poco de aceite.','Cubrir con agua y cocinar 30 minutos.','Añadir las lentejas y seguir cocinando 30-40 minutos más hasta que estén tiernas y el caldo haya espesado.','Trocear el pan y colocarlo en el fondo de una fuente honda.','Verter el pollo, las lentejas y el caldo caliente sobre el pan, dejando que lo absorba antes de servir.'],"consejo"=>'Deja reposar el pan en el caldo unos minutos antes de servir: necesita tiempo para absorberlo sin deshacerse del todo.' ],
  [ "titulo"=>'Batbout (pan marroquí)',"descripcion"=>'Pan plano cocido en sartén, sin horno, que se hincha formando una bolsa hueca ideal para rellenar.',"tiempo"=>'1 h 30 min (con reposo)',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/45/Pains_matlou_dans_une_boulangerie_de_la_rue_d%27Aligre%2C_%C3%A0_Paris.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Marroquí','Principal'],"ingredientes"=>['300 g de harina de trigo','150 g de sémola fina','1 cucharadita de levadura seca','Agua tibia, sal','Sémola extra para espolvorear'],"pasos"=>['Disolver la levadura en agua tibia y dejar activar 10 minutos.','Mezclar con la harina, la sémola y la sal, amasando hasta obtener una masa suave y elástica.','Dejar fermentar tapada 1 hora hasta que doble su volumen.','Dividir en bolas, aplanar en discos no muy finos y dejar reposar 15 minutos más.','Cocinar en una sartén o plancha seca a fuego medio, dándoles la vuelta varias veces, hasta que se hinchen y doren por ambos lados.'],"consejo"=>'Cocina a fuego medio, ni muy fuerte ni muy suave: el calor moderado es lo que permite que el pan se hinche formando la bolsa interior.' ],
  [ "titulo"=>'Ensalada marroquí de tomate y pimiento asado',"descripcion"=>'Ensalada cocida de tomate y pimiento asados, especiada con comino y pimentón, servida fría como acompañamiento.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Marroquí',"photoUrl"=>'https://live.staticflickr.com/3515/3697196377_2f36655ee8_b.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Marroquí','Principal'],"ingredientes"=>['4 tomates maduros','2 pimientos rojos','2 dientes de ajo','Comino, pimentón','Aceite de oliva, zumo de limón','Cilantro o perejil fresco'],"pasos"=>['Asar los pimientos hasta que la piel se ampolle, pelarlos y cortarlos en tiras.','Pelar los tomates escaldándolos en agua hirviendo y triturar la pulpa.','Sofreír el ajo en aceite de oliva, añadir el tomate y las especias y cocinar 15-20 minutos hasta que espese.','Incorporar el pimiento asado en tiras y cocinar 5 minutos más.','Dejar enfriar, aliñar con zumo de limón y servir con cilantro o perejil fresco.'],"consejo"=>'Deja que la salsa de tomate reduzca bien antes de añadir el pimiento: si queda demasiado líquida, la ensalada pierde consistencia.' ],
  [ "titulo"=>'Pastela de pollo',"descripcion"=>'Empanada dulce y salada de pasta warqa rellena de pollo especiado, almendra y canela, espolvoreada con azúcar glas.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Alta',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/ed/Bisteeya.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Marroquí','Principal'],"ingredientes"=>['1 pollo troceado','1 cebolla, jengibre, cúrcuma, canela','3 huevos','150 g de almendra frita y picada','Azúcar, canela molida (para decorar)','Láminas de pasta warqa o filo','Mantequilla derretida'],"pasos"=>['Cocinar el pollo con la cebolla y las especias hasta que esté muy tierno; desmenuzarlo y reservar el caldo.','Reducir el caldo y ligarlo con los huevos batidos, removiendo a fuego suave hasta obtener una especie de revuelto cremoso.','Mezclar el pollo desmenuzado con este revuelto y dejar enfriar.','Forrar un molde con láminas de pasta warqa pintadas de mantequilla, rellenar con el pollo y la almendra picada, y cerrar con más láminas por encima.','Hornear a 180 °C hasta dorar y espolvorear con azúcar glas y canela formando un dibujo en rombos antes de servir.'],"consejo"=>'No te asustes por la mezcla de dulce y salado: es la seña de identidad de la pastela, y el contraste es lo que la hace única.' ],
  // Dulces y té
  [ "titulo"=>'Chebakia',"descripcion"=>'Pasteles fritos en forma de flor, bañados en miel y espolvoreados con sésamo, típicos del Ramadán.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Alta',"raciones_base"=>8,"plato"=>'postre',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/44/Shebbaqu%C3%ADas.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Marroquí','Postre'],"ingredientes"=>['500 g de harina','Canela, anís, sésamo tostado','Levadura, mantequilla, vinagre','Agua de azahar','Aceite para freír','Miel para bañar'],"pasos"=>['Mezclar la harina con las especias, el sésamo tostado molido, la mantequilla y el vinagre.','Amasar añadiendo agua de azahar poco a poco hasta obtener una masa elástica; dejar reposar 30 minutos.','Estirar la masa fina y cortar en tiras, formando trenzas o flores dando forma con los dedos.','Freír en aceite caliente hasta que estén doradas.','Sumergir inmediatamente en miel templada y espolvorear con sésamo tostado.'],"consejo"=>'Sumerge los pasteles en miel justo al salir del aceite, todavía calientes: así absorben mejor la miel y quedan brillantes.' ],
  [ "titulo"=>'Cuernos de gacela (kaab el ghazal)',"descripcion"=>'Pastelitos en forma de media luna rellenos de pasta de almendra aromatizada con agua de azahar y canela.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>8,"plato"=>'postre',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/6/61/%D9%83%D8%B9%D8%A8_%D8%A7%D9%84%D8%BA%D8%B2%D8%A7%D9%84.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Marroquí','Postre'],"ingredientes"=>['300 g de almendra molida','150 g de azúcar glas','Agua de azahar, canela','250 g de harina, mantequilla','Huevo (para pintar)'],"pasos"=>['Mezclar la almendra molida con el azúcar glas, la canela y agua de azahar hasta formar una pasta moldeable.','Formar pequeños cilindros finos con la pasta de almendra.','Preparar una masa de harina y mantequilla, estirarla fina y envolver cada cilindro de almendra, dando forma de media luna.','Pinchar ligeramente la superficie con un tenedor y pintar con huevo batido.','Hornear a 180 °C 15-18 minutos hasta que estén dorados pero no oscuros.'],"consejo"=>'No hornees en exceso: estos pastelitos deben quedar pálidos y tiernos, no dorados y crujientes.' ],
  [ "titulo"=>'Té a la menta marroquí',"descripcion"=>'Té verde con abundante menta fresca y azúcar, servido desde muy alto para formar espuma, símbolo de hospitalidad en Marruecos.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Marroquí',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/41/Tunisian_Tea_with_pine_nuts.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food','Quitar el hambre rápido'],"etiquetas"=>['Marroquí','Postre'],"ingredientes"=>['2 cucharadas de té verde gunpowder','Un manojo grande de menta fresca','Azúcar al gusto','Agua'],"pasos"=>['Escaldar el té verde con un poco de agua caliente y desechar esa primera agua para suavizar el amargor.','Añadir agua hirviendo de nuevo junto con la menta fresca y el azúcar.','Dejar infusionar 5 minutos a fuego muy suave, sin que hierva con fuerza.','Servir vertiendo el té desde bastante altura sobre el vaso, para que se forme una ligera espuma en la superficie.'],"consejo"=>'Desechar la primera agua de infusión del té es un paso tradicional que suaviza el amargor sin perder aroma.' ],

  // ═══ FRANCESA ═══
  // Entrantes
  [ "titulo"=>'Soupe à l\'oignon gratinée',"descripcion"=>'Sopa de cebolla caramelizada muy lentamente, cubierta con pan tostado y queso gratinado, clásico de los bistrós parisinos.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/5a/Soupe_%C3%A0_l%27oignon.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Francesa','Entrante'],"ingredientes"=>['6 cebollas grandes en juliana','50 g de mantequilla','1 litro de caldo de carne','100 ml de vino blanco','Pan tostado (baguette)','Queso gruyère rallado'],"pasos"=>['Pochar las cebollas en mantequilla a fuego muy lento durante al menos 45 minutos, removiendo de vez en cuando, hasta que estén muy doradas y caramelizadas.','Añadir el vino blanco y dejar reducir.','Incorporar el caldo de carne y cocinar a fuego suave 20 minutos.','Repartir la sopa en cazuelitas individuales, cubrir con una rebanada de pan tostado y una generosa capa de queso rallado.','Gratinar en el horno hasta que el queso esté fundido y dorado.'],"consejo"=>'No aceleres la caramelización de la cebolla: cuanto más lenta y larga sea esta fase, más profundo será el sabor final de la sopa.' ],
  [ "titulo"=>'Ratatouille',"descripcion"=>'Guiso de verduras de verano de la Provenza —berenjena, calabacín, pimiento y tomate— cocinadas lentamente con hierbas provenzales.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/8a/Ratatouille02.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Francesa','Entrante'],"ingredientes"=>['1 berenjena','2 calabacines','1 pimiento rojo','4 tomates maduros','1 cebolla, 2 dientes de ajo','Tomillo y romero frescos','Aceite de oliva'],"pasos"=>['Cortar todas las verduras en dados de tamaño similar.','Sofreír la cebolla y el ajo en aceite de oliva.','Añadir el pimiento y cocinar 5 minutos; incorporar la berenjena y el calabacín, cocinar otros 10 minutos.','Añadir el tomate troceado y las hierbas frescas.','Cocinar a fuego lento, tapado, removiendo de vez en cuando, durante 30-40 minutos hasta que todas las verduras estén muy tiernas.'],"consejo"=>'Corta las verduras en trozos parecidos y cocínalas por etapas según su dureza: así todas quedan en su punto a la vez.' ],
  [ "titulo"=>'Quiche lorraine',"descripcion"=>'Tarta salada de masa quebrada rellena de una crema de huevo, nata y panceta, especialidad de la región de Lorena.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Fácil',"raciones_base"=>6,"plato"=>'entrante',"cocina"=>'Francesa',"photoUrl"=>'https://live.staticflickr.com/7454/16345559297_d5c8702610_b.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Francesa','Entrante'],"ingredientes"=>['1 base de masa quebrada','200 g de panceta o beicon en tiras','4 huevos','300 ml de nata líquida','Nuez moscada, sal, pimienta','Queso gruyère rallado (opcional)'],"pasos"=>['Forrar un molde con la masa quebrada y pinchar el fondo con un tenedor.','Dorar la panceta en una sartén sin nada de grasa añadida, y repartirla sobre la base de masa.','Batir los huevos con la nata, la nuez moscada, sal y pimienta.','Verter esta mezcla sobre la panceta y espolvorear con queso rallado si se desea.','Hornear a 180 °C 30-35 minutos hasta que esté cuajada y dorada por encima.'],"consejo"=>'Hornea la base de masa sola unos minutos antes de rellenarla (horneado en blanco): evita que quede cruda por debajo.' ],
  // Platos principales
  [ "titulo"=>'Coq au vin',"descripcion"=>'Pollo guisado lentamente en vino tinto con champiñones, cebollitas y panceta, plato clásico de la Borgoña.',"tiempo"=>'1 h 30 min',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/75/Coq_au_Vin_6of7_%288735164745%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Francesa','Principal'],"ingredientes"=>['1 pollo troceado','150 g de panceta en dados','200 g de champiñones','200 g de cebollitas pequeñas','500 ml de vino tinto','1 cucharada de harina','Tomillo, laurel'],"pasos"=>['Dorar la panceta en una olla y reservar; en la misma grasa, dorar el pollo por todos lados y reservar.','Sofreír las cebollitas y los champiñones en la misma olla.','Espolvorear con harina y remover; añadir el vino tinto poco a poco, raspando el fondo de la olla.','Devolver el pollo y la panceta a la olla, añadir tomillo y laurel, y cocinar tapado a fuego lento 1 hora hasta que el pollo esté muy tierno.','Destapar los últimos 10 minutos para que la salsa reduzca y espese ligeramente.'],"consejo"=>'Usa un vino tinto de calidad razonable para cocinar: su sabor se concentra mucho durante la cocción, así que uno malo se notará en el plato.' ],
  [ "titulo"=>'Boeuf bourguignon',"descripcion"=>'Guiso de ternera cocinada muy lentamente en vino tinto de Borgoña con champiñones y cebollitas, uno de los grandes clásicos franceses.',"tiempo"=>'2 h 30 min',"tiempoMin"=>150,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/53/Boeuf_bourguignon_servi_avec_des_p%C3%A2tes.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Francesa','Principal'],"ingredientes"=>['1 kg de ternera para guisar','150 g de panceta en dados','1 cebolla, 2 zanahorias','750 ml de vino tinto','200 g de champiñones','200 g de cebollitas pequeñas','Tomillo, laurel, harina'],"pasos"=>['Dorar la panceta y reservar; dorar la ternera por tandas en la misma grasa y reservar.','Sofreír la cebolla y la zanahoria, espolvorear con harina y remover.','Añadir el vino tinto poco a poco, raspando el fondo, y devolver la carne y la panceta a la olla junto con tomillo y laurel.','Cocinar tapado a fuego muy lento 2 horas, hasta que la carne esté muy tierna.','Añadir los champiñones y las cebollitas salteadas aparte los últimos 20-30 minutos.'],"consejo"=>'Cuanto más lenta y larga sea la cocción, más se deshace la carne: no tengas prisa con este guiso, gana de un día para otro.' ],
  [ "titulo"=>'Cassoulet',"descripcion"=>'Guiso denso de alubias blancas con confit de pato, salchicha y panceta, cocinado muy lentamente en cazuela de barro, del suroeste de Francia.',"tiempo"=>'2 h 30 min',"tiempoMin"=>150,"dificultad"=>'Alta',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/a/a5/Bowl_of_cassoulet.JPG',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Francesa','Principal'],"ingredientes"=>['500 g de alubias blancas (en remojo)','4 muslos de confit de pato','200 g de salchicha de Toulouse o similar','150 g de panceta','1 cebolla, 2 dientes de ajo','Tomate triturado, pan rallado'],"pasos"=>['Cocer las alubias remojadas con la cebolla y el ajo hasta que estén tiernas, reservando el caldo.','Dorar la panceta y la salchicha en una cazuela de barro.','Añadir el confit de pato desmenuzado y un poco de tomate triturado.','Incorporar las alubias cocidas y su caldo, mezclar con cuidado.','Cubrir con pan rallado y hornear a 160 °C al menos 1 hora, rompiendo la costra que se forma en la superficie un par de veces y dejando que se vuelva a formar.'],"consejo"=>'Romper y dejar que se reforme la costra dorada de pan varias veces durante el horneado es el paso tradicional que da al cassoulet su textura característica.' ],
  [ "titulo"=>'Confit de pato',"descripcion"=>'Muslos de pato cocinados muy lentamente sumergidos en su propia grasa hasta quedar tiernísimos, y después dorados hasta la piel crujiente.',"tiempo"=>'3 h + reposo',"tiempoMin"=>180,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/6/60/Confitdecanard.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Francesa','Principal'],"ingredientes"=>['4 muslos de pato','Sal gruesa, tomillo, laurel','Grasa de pato (suficiente para cubrir)','Ajo'],"pasos"=>['Frotar los muslos de pato con sal gruesa, tomillo, laurel y ajo, y dejar macerar en la nevera al menos 12 horas.','Enjuagar el exceso de sal y secar bien.','Sumergir los muslos en grasa de pato derretida en una cazuela, y cocinar a fuego muy bajo, casi sin burbujear, durante 2-3 horas hasta que estén muy tiernos.','Dejar enfriar los muslos dentro de la grasa (pueden conservarse así varios días).','Para servir, dorar los muslos en una sartén caliente, con la piel hacia abajo, hasta que quede crujiente.'],"consejo"=>'La grasa debe cocinar el pato a fuego muy bajo, sin apenas burbujear: un hervor fuerte reseca la carne en vez de dejarla tierna.' ],
  [ "titulo"=>'Bouillabaisse',"descripcion"=>'Guiso marinero de varios pescados y mariscos con azafrán, típico de Marsella, servido con una salsa rouille y pan tostado.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Alta',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/24/Bullabessa.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Francesa','Principal'],"ingredientes"=>['1,5 kg de pescados variados de roca','300 g de mejillones o gambas','1 cebolla, 1 puerro, 2 tomates','Hinojo, azafrán, piel de naranja','Aceite de oliva, ajo','Pan tostado y salsa rouille (mayonesa con ajo y azafrán)'],"pasos"=>['Sofreír la cebolla, el puerro y el hinojo en aceite de oliva.','Añadir el tomate, el azafrán y la piel de naranja, cocinar unos minutos.','Cubrir con agua o caldo de pescado y cocinar 20 minutos para hacer un caldo con mucho sabor.','Colar si se desea un caldo más limpio, y devolver al fuego; añadir los pescados y mariscos en tandas según el tiempo de cocción de cada uno.','Servir el caldo y el pescado por separado, acompañados de pan tostado untado con salsa rouille.'],"consejo"=>'Añade los distintos pescados y mariscos por tandas, empezando por los que necesitan más cocción: así ninguno queda pasado ni crudo.' ],
  [ "titulo"=>'Steak frites con salsa bearnesa',"descripcion"=>'Entrecot a la plancha acompañado de patatas fritas finas y una salsa bearnesa cremosa de mantequilla, huevo y estragón.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/9/9a/Reel_and_Brand_-_September_2021_-_Sarah_Stierch_05.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Francesa','Principal'],"ingredientes"=>['4 entrecots','Patatas para freír','3 yemas de huevo','150 g de mantequilla clarificada','Vinagre de estragón, chalota, estragón fresco'],"pasos"=>['Cortar las patatas en bastones finos y freírlas en dos tandas (primero a menor temperatura, después a fuego fuerte para dorar) hasta que estén crujientes.','Reducir el vinagre con la chalota picada y el estragón hasta casi evaporarse.','Batir las yemas al baño maría con esta reducción hasta que espesen, e ir incorporando la mantequilla clarificada poco a poco hasta emulsionar.','Asar los entrecots a la plancha al punto deseado y dejar reposar unos minutos.','Servir la carne con las patatas fritas y la salsa bearnesa aparte.'],"consejo"=>'Bate la salsa bearnesa siempre al baño maría y sin prisa: el calor directo hace que las yemas cuajen en vez de emulsionar.' ],
  [ "titulo"=>'Salade niçoise',"descripcion"=>'Ensalada fría de atún, huevo cocido, judía verde, tomate y aceitunas negras, especialidad de Niza.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/7f/Salade_ni%C3%A7oise.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Francesa','Principal'],"ingredientes"=>['200 g de atún en conserva de calidad','4 huevos cocidos','200 g de judía verde','4 tomates','Aceitunas negras de Niza','Anchoas, aceite de oliva, vinagre'],"pasos"=>['Cocer las judías verdes hasta que estén tiernas pero firmes, y enfriar en agua con hielo.','Cocer los huevos y cortarlos en cuartos.','Disponer en una fuente el tomate en gajos, las judías verdes, el atún desmigado, los huevos y las aceitunas.','Añadir unas anchoas por encima.','Aliñar con aceite de oliva y un poco de vinagre justo antes de servir.'],"consejo"=>'No mezcles los ingredientes: la salade niçoise tradicional se presenta en montoncitos separados sobre la fuente, no revuelta.' ],
  [ "titulo"=>'Croque monsieur',"descripcion"=>'Sándwich de pan de molde con jamón y queso gruyère, cubierto con bechamel y gratinado al horno.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/3/3e/Croque_monsieur.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Francesa','Principal'],"ingredientes"=>['8 rebanadas de pan de molde','4 lonchas de jamón cocido','150 g de queso gruyère rallado','20 g de mantequilla, 20 g de harina, 250 ml de leche (bechamel)','Mostaza (opcional)'],"pasos"=>['Preparar una bechamel espesa derritiendo la mantequilla, añadiendo la harina y luego la leche poco a poco hasta espesar.','Untar las rebanadas de pan con un poco de mostaza si se desea, y montar los sándwiches con el jamón y parte del queso.','Cubrir la superficie de cada sándwich con bechamel y espolvorear con el resto del queso.','Gratinar en el horno hasta que el queso esté fundido y dorado.'],"consejo"=>'Usa una bechamel bien espesa: si queda demasiado líquida, se escurre del sándwich al gratinar en vez de formar una costra dorada.' ],
  // Postres
  [ "titulo"=>'Crêpes suzette',"descripcion"=>'Crepes finas flambeadas en una salsa de mantequilla, azúcar y zumo de naranja, clásico de la repostería francesa de sala.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Francesa',"photoUrl"=>'https://live.staticflickr.com/2317/2220655887_dc1f2dd752_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Francesa','Postre'],"ingredientes"=>['200 g de harina','3 huevos','500 ml de leche','Mantequilla','2 naranjas','100 g de azúcar','Licor de naranja (opcional)'],"pasos"=>['Batir la harina, los huevos y la leche hasta obtener una masa fina y sin grumos; dejar reposar 20 minutos.','Cocinar crepes finas en una sartén ligeramente engrasada, doradas por ambos lados.','Derretir mantequilla con azúcar en una sartén amplia hasta que empiece a caramelizar.','Añadir el zumo de naranja y dejar reducir a una salsa brillante.','Sumergir las crepes dobladas en la salsa, calentar bien y, si se desea, flambear con un chorro de licor de naranja.'],"consejo"=>'Deja reposar la masa de crepes antes de cocinarla: el gluten se relaja y las crepes quedan más finas y elásticas.' ],
  [ "titulo"=>'Tarte tatin',"descripcion"=>'Tarta de manzana invertida, caramelizada primero en la sartén y cubierta después con masa quebrada antes de hornear.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'postre',"cocina"=>'Francesa',"photoUrl"=>'https://live.staticflickr.com/7274/7553092598_509ce63fe0_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Francesa','Postre'],"ingredientes"=>['6-8 manzanas ácidas (tipo reineta)','150 g de azúcar','80 g de mantequilla','1 base de masa quebrada'],"pasos"=>['Pelar y cortar las manzanas en cuartos u octavos.','Derretir el azúcar en una sartén apta para horno hasta obtener un caramelo dorado, añadir la mantequilla y remover.','Colocar las manzanas apretadas sobre el caramelo, con el lado curvo hacia abajo.','Cocinar a fuego medio unos minutos hasta que las manzanas empiecen a ablandarse.','Cubrir con la masa quebrada, remetiendo los bordes hacia dentro, y hornear a 200 °C 25-30 minutos; desmoldar volteando sobre un plato mientras aún está caliente.'],"consejo"=>'Desmolda la tarta mientras aún está caliente, volteándola de golpe sobre el plato: si se enfría, el caramelo se solidifica y se pega al molde.' ],
  [ "titulo"=>'Crème brûlée',"descripcion"=>'Crema de vainilla horneada al baño maría, con una fina costra de azúcar caramelizada que se rompe con la cuchara.',"tiempo"=>'50 min + refrigeración',"tiempoMin"=>50,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/d/dc/Cr%C3%A8me_br%C3%BBl%C3%A9e_%284554822506%29.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Francesa','Postre'],"ingredientes"=>['500 ml de nata para montar','1 vaina de vainilla','5 yemas de huevo','80 g de azúcar','Azúcar extra para caramelizar'],"pasos"=>['Calentar la nata con las semillas de la vaina de vainilla, sin dejar que hierva.','Batir las yemas con el azúcar hasta blanquear ligeramente.','Verter la nata caliente sobre las yemas poco a poco, removiendo sin parar para que no cuajen de golpe.','Repartir en moldes individuales y cocinar al baño maría en el horno a 150 °C durante 30-35 minutos, hasta que estén cuajadas pero aún tiemblen ligeramente en el centro.','Refrigerar varias horas y, justo antes de servir, espolvorear con azúcar y caramelizar con un soplete de cocina.'],"consejo"=>'Caramelizar el azúcar justo antes de servir, nunca con antelación: si se hace demasiado pronto, la costra se reblandece con la humedad de la crema.' ],
  [ "titulo"=>'Macarons',"descripcion"=>'Pequeños dulces de almendra molida y merengue, crujientes por fuera y tiernos por dentro, rellenos de ganache o mermelada.',"tiempo"=>'1 h + reposo',"tiempoMin"=>60,"dificultad"=>'Alta',"raciones_base"=>6,"plato"=>'postre',"cocina"=>'Francesa',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/d/d1/Macarons_Marcolini_04.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Francesa','Postre'],"ingredientes"=>['150 g de almendra molida fina','150 g de azúcar glas','3 claras de huevo','150 g de azúcar','Colorante alimentario (opcional)','Ganache de chocolate o mermelada (para el relleno)'],"pasos"=>['Tamizar la almendra molida con el azúcar glas.','Montar las claras a punto de nieve, añadiendo el azúcar poco a poco hasta obtener un merengue firme y brillante.','Incorporar la mezcla de almendra al merengue con movimientos envolventes, hasta lograr una textura que caiga en forma de cinta (el \'macaronage\').','Formar pequeños discos con manga pastelera sobre papel de horno, golpear la bandeja para eliminar burbujas de aire y dejar reposar 30-40 minutos hasta que se forme una fina costra al tacto.','Hornear a 150 °C 12-14 minutos; dejar enfriar por completo y rellenar de dos en dos con ganache o mermelada.'],"consejo"=>'No te saltes el reposo antes de hornear: la costra que se forma en la superficie es lo que permite que los macarons desarrollen su característico \'pie\' al cocerse.' ],

  // ═══ MEDITERRÁNEA ═══
  // Mojos y aperitivos fríos
  [ "titulo"=>'Hummus casero',"descripcion"=>'Puré cremoso de garbanzos, tahini, limón y ajo, el mojo levantino más extendido del Mediterráneo.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://live.staticflickr.com/7178/6815671096_63735fe071_b.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Reconfortante / comfort food','Ligero para la noche'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['400 g de garbanzos cocidos','3 cucharadas de tahini','1 diente de ajo','Zumo de 1 limón','Aceite de oliva virgen extra','Comino, sal, pimentón para decorar'],"pasos"=>['Triturar los garbanzos con el tahini, el ajo, el zumo de limón y un poco de agua fría hasta obtener una textura muy fina.','Añadir sal y comino al gusto, y seguir triturando hasta que quede completamente cremoso.','Ajustar la textura con más agua fría si queda demasiado espeso.','Servir en un plato hondo, con un chorro de aceite de oliva y una pizca de pimentón por encima.'],"consejo"=>'Tritura los garbanzos varios minutos más de lo que parece necesario: cuanto más tiempo, más fino y sedoso queda el hummus.' ],
  [ "titulo"=>'Baba ganoush',"descripcion"=>'Puré de berenjena asada con tahini, ajo y limón, con un característico aroma ahumado.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://live.staticflickr.com/3806/13117795964_f0b75bfc89_b.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['2 berenjenas grandes','2 cucharadas de tahini','1 diente de ajo','Zumo de limón','Aceite de oliva virgen extra','Perejil, sal'],"pasos"=>['Asar las berenjenas enteras directamente sobre la llama o en el horno muy caliente hasta que la piel esté completamente quemada y la pulpa muy tierna.','Dejar templar y retirar toda la piel quemada, escurriendo el exceso de líquido de la pulpa.','Triturar o machacar la pulpa junto con el tahini, el ajo y el zumo de limón.','Sazonar con sal, servir con un chorro de aceite de oliva y perejil picado por encima.'],"consejo"=>'Asar la berenjena directamente sobre la llama, aunque se ensucie por fuera, es lo que da al baba ganoush su aroma ahumado característico.' ],
  [ "titulo"=>'Muhammara',"descripcion"=>'Paté de pimientos asados, nueces y melaza de granada, con un punto picante, típico de la cocina siria.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/4c/Tanoreen_muhammara.jpg',"dietas"=>['Vegana','Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['3 pimientos rojos asados','100 g de nueces','1 diente de ajo','1 cucharada de melaza de granada','Pan rallado o migas de pan','Comino, chile en polvo, aceite de oliva'],"pasos"=>['Asar los pimientos hasta que la piel esté ampollada, pelarlos y retirar las semillas.','Triturar los pimientos con las nueces, el ajo, la melaza de granada y las especias hasta obtener una pasta con textura.','Añadir un poco de pan rallado si queda demasiado líquido, para espesar.','Ajustar de sal y aceite de oliva, y servir a temperatura ambiente.'],"consejo"=>'Tuesta ligeramente las nueces antes de triturarlas: potencia mucho su sabor frente a usarlas crudas.' ],
  [ "titulo"=>'Tapenade de aceitunas negras',"descripcion"=>'Pasta untable de aceitunas negras, alcaparras y anchoas, típica de la Provenza francesa y muy extendida en toda la costa mediterránea.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/6/61/Cuillere_de_tapenade.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['250 g de aceitunas negras deshuesadas','2 filetes de anchoa','1 cucharada de alcaparras','1 diente de ajo','Aceite de oliva virgen extra','Zumo de limón'],"pasos"=>['Triturar las aceitunas, las anchoas, las alcaparras y el ajo hasta obtener una pasta con algo de textura.','Añadir aceite de oliva poco a poco mientras se tritura, hasta lograr la consistencia deseada.','Terminar con un chorro de zumo de limón.','Servir sobre pan tostado o como acompañamiento de verduras crudas.'],"consejo"=>'No añadas sal sin probar antes: las aceitunas, las anchoas y las alcaparras ya aportan mucha por sí solas.' ],
  [ "titulo"=>'Labneh con aceite de oliva y za\'atar',"descripcion"=>'Yogur colado hasta obtener una textura de queso cremoso, servido con aceite de oliva y la mezcla de especias za\'atar.',"tiempo"=>'15 min + colado',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/2c/Labneh01.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['500 g de yogur natural griego','Sal','Aceite de oliva virgen extra','Za\'atar (mezcla de tomillo, sésamo y zumaque)','Pan de pita para acompañar'],"pasos"=>['Mezclar el yogur con una pizca de sal.','Verter en un paño limpio o gasa fina colocado sobre un colador, y dejar escurrir en la nevera al menos 12-24 horas, hasta que quede muy espeso.','Formar una bola o extender en un plato hondo formando un hueco en el centro.','Rociar generosamente con aceite de oliva y espolvorear con za\'atar.','Servir con pan de pita templado.'],"consejo"=>'Cuanto más tiempo cueles el yogur, más firme quedará el labneh: para una textura casi de queso, deja colar hasta 48 horas.' ],
  [ "titulo"=>'Falafel',"descripcion"=>'Bolitas fritas de garbanzo crudo triturado con hierbas y especias, crujientes por fuera y verdes por dentro.',"tiempo"=>'40 min + remojo',"tiempoMin"=>40,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/5b/Falafel_beim_Isarinselfest_M%C3%BCnchen_2.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['300 g de garbanzos secos, en remojo 12 horas (no cocidos)','1 cebolla, 2 dientes de ajo','Perejil y cilantro frescos','Comino, cilantro molido','Bicarbonato, sal','Aceite para freír'],"pasos"=>['Escurrir bien los garbanzos remojados (deben usarse crudos, nunca cocidos).','Triturar los garbanzos con la cebolla, el ajo, las hierbas y las especias hasta obtener una masa con textura granulada, no un puré fino.','Añadir una pizca de bicarbonato y dejar reposar la masa 30 minutos en la nevera.','Formar pequeñas bolas u óvalos con las manos.','Freír en aceite bien caliente hasta que estén doradas y crujientes por fuera.'],"consejo"=>'Usa siempre garbanzos crudos en remojo, nunca cocidos: los garbanzos cocidos tienen demasiada agua y el falafel se deshace al freír.' ],
  // Ensaladas y platos fríos
  [ "titulo"=>'Tabulé (tabbouleh)',"descripcion"=>'Ensalada libanesa de perejil picado muy fino, bulgur, tomate y menta, aliñada con limón y aceite de oliva.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://live.staticflickr.com/7055/6916828023_c78839510e_b.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['50 g de bulgur fino','2 manojos grandes de perejil fresco picado muy fino','Menta fresca picada','2 tomates en dados pequeños','1 cebolleta','Zumo de limón, aceite de oliva virgen extra'],"pasos"=>['Remojar el bulgur en agua fría o templada 15-20 minutos hasta que esté tierno, y escurrir bien.','Picar el perejil muy fino, a cuchillo, junto con la menta y la cebolleta.','Mezclar las hierbas picadas con el tomate en dados y el bulgur escurrido.','Aliñar generosamente con zumo de limón, aceite de oliva y sal justo antes de servir.'],"consejo"=>'En el tabulé auténtico el perejil es el protagonista y el bulgur es secundario: usa mucha más hierba que grano.' ],
  [ "titulo"=>'Fattoush',"descripcion"=>'Ensalada libanesa de verduras frescas y pan de pita tostado, aliñada con melaza de granada y sumac.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/9/93/Fattoush_mixed-salad.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Ligero para la noche'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['2 panes de pita','2 tomates, 1 pepino','1 pimiento verde, rábanos','Lechuga, cebolleta, menta fresca','Zumo de limón, melaza de granada, sumac, aceite de oliva'],"pasos"=>['Tostar los panes de pita en el horno o en una sartén hasta que estén crujientes, y trocearlos en pedazos irregulares.','Cortar todas las verduras en trozos de tamaño similar y mezclar en una fuente grande.','Preparar el aliño mezclando zumo de limón, melaza de granada, sumac y aceite de oliva.','Añadir el pan tostado y el aliño justo antes de servir, mezclando bien.'],"consejo"=>'Añade el pan tostado en el último momento: si se mezcla con antelación, absorbe el aliño y pierde el punto crujiente.' ],
  [ "titulo"=>'Ensalada de garbanzos con feta',"descripcion"=>'Ensalada fresca de garbanzos, pepino, tomate y queso feta, aliñada con aceite de oliva y orégano.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://live.staticflickr.com/7620/17102801921_e892f20d4c_b.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['400 g de garbanzos cocidos','1 pepino, 2 tomates','150 g de queso feta en dados','Aceitunas negras','Orégano seco, aceite de oliva virgen extra, zumo de limón'],"pasos"=>['Escurrir bien los garbanzos cocidos.','Cortar el pepino y el tomate en dados y mezclar con los garbanzos.','Añadir el feta en dados y las aceitunas.','Aliñar con aceite de oliva, zumo de limón y orégano al gusto justo antes de servir.'],"consejo"=>'Añade el feta al final y con cuidado: se desmorona con facilidad si se mezcla con demasiada fuerza.' ],
  [ "titulo"=>'Boquerones en vinagre',"descripcion"=>'Filetes de boquerón fresco marinados en vinagre y aceite de oliva con ajo y perejil, tapa fría típica de toda la costa mediterránea española.',"tiempo"=>'20 min + 24 h de marinado',"tiempoMin"=>1460,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/50/Boquerones_en_vinagre-Madrid.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['500 g de boquerones frescos, limpios en filetes','Vinagre de vino blanco','Agua','Sal','Ajo picado, perejil fresco picado','Aceite de oliva virgen extra'],"pasos"=>['Congelar los boquerones limpios al menos 48 horas antes de prepararlos, por seguridad frente al anisakis, y descongelar en la nevera.','Colocar los filetes en un recipiente y cubrir con una mezcla a partes iguales de vinagre y agua con un poco de sal.','Dejar marinar en la nevera entre 6 y 12 horas, hasta que la carne esté blanca por completo.','Escurrir bien el líquido de marinado, colocar en una fuente con ajo y perejil picados, y cubrir con aceite de oliva.','Dejar reposar al menos un par de horas en la nevera antes de servir.'],"consejo"=>'Congela siempre el pescado antes de marinarlo en crudo: es una medida de seguridad alimentaria imprescindible, no un paso opcional.' ],
  [ "titulo"=>'Berenjenas fritas con miel de caña',"descripcion"=>'Bastones de berenjena rebozados y fritos hasta quedar crujientes, servidos con un chorro de miel de caña, tapa típica de Andalucía.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Berenjenas%20rebozadas%20con%20salmorejo.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['2 berenjenas','200 ml de leche','Harina','Aceite de oliva para freír','Miel de caña'],"pasos"=>['Cortar las berenjenas en bastones y dejarlas en remojo con leche 20 minutos, para suavizar su amargor.','Escurrir y pasar por harina, sacudiendo el exceso.','Freír en aceite bien caliente hasta que estén doradas y crujientes.','Escurrir sobre papel absorbente y servir de inmediato con un buen chorro de miel de caña por encima.'],"consejo"=>'Sirve las berenjenas nada más freírlas: pierden el crujiente muy rápido si se dejan reposar demasiado.' ],
  [ "titulo"=>'Pan con tomate catalán',"descripcion"=>'Pan de pueblo tostado, frotado con tomate maduro y ajo, y aliñado con aceite de oliva y sal, la base de cualquier desayuno catalán.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/8/8a/Pa_amb_tomaquet.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Mediterránea','Entrante'],"ingredientes"=>['4 rebanadas de pan rústico','2 tomates muy maduros','1 diente de ajo','Aceite de oliva virgen extra','Sal'],"pasos"=>['Tostar el pan hasta que esté crujiente por fuera.','Frotar cada rebanada con el diente de ajo cortado por la mitad.','Cortar el tomate por la mitad y frotarlo con fuerza sobre el pan, dejando que la pulpa se impregne bien y desechando la piel.','Rociar con aceite de oliva y una pizca de sal.'],"consejo"=>'Usa siempre tomates muy maduros, casi pasados: cuanto más blandos, más fácil es frotarlos y más sabor sueltan en el pan.' ],
  // Platos principales
  [ "titulo"=>'Shakshuka',"descripcion"=>'Huevos escalfados sobre una salsa especiada de tomate y pimiento, plato de desayuno o cena muy extendido por todo el Mediterráneo oriental.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/26/Shakshuka1.jpg',"dietas"=>['Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['6 huevos','800 g de tomate triturado','1 cebolla, 1 pimiento rojo','2 dientes de ajo','Comino, pimentón dulce y picante','Aceite de oliva, cilantro o perejil fresco'],"pasos"=>['Sofreír la cebolla y el pimiento en aceite de oliva hasta que estén tiernos.','Añadir el ajo y las especias, sofreír un minuto más.','Incorporar el tomate triturado y cocinar a fuego medio 15-20 minutos hasta que espese.','Hacer pequeños huecos en la salsa y cascar los huevos directamente sobre ella.','Tapar y cocinar a fuego suave hasta que las claras cuajen y las yemas queden jugosas; terminar con cilantro o perejil fresco.'],"consejo"=>'Cocina los huevos siempre tapados y a fuego suave: así cuajan por vapor de forma uniforme sin necesidad de darles la vuelta.' ],
  [ "titulo"=>'Kibbeh',"descripcion"=>'Croquetas alargadas de bulgur y carne picada especiada, rellenas de más carne, fritas hasta quedar crujientes.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Alta',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/5c/%C4%B0%C3%A7li_k%C3%B6fte.png',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['200 g de bulgur fino','300 g de carne picada de cordero (para la masa exterior)','200 g de carne picada (para el relleno)','1 cebolla','Piñones, canela, pimienta de Jamaica','Aceite para freír'],"pasos"=>['Remojar el bulgur en agua fría 20 minutos y escurrir muy bien, apretando con las manos.','Triturar el bulgur con la carne picada para la masa exterior, la cebolla y las especias, hasta obtener una pasta homogénea.','Para el relleno, sofreír la otra carne picada con cebolla, piñones y especias hasta dorar.','Formar una bola con la masa exterior, hacer un hueco con el dedo, rellenar con la mezcla de carne y cerrar dando forma alargada.','Freír en aceite caliente hasta que estén doradas y crujientes por fuera.'],"consejo"=>'Moja las manos con agua fría al trabajar la masa de bulgur: se vuelve pegajosa y es mucho más fácil de moldear así.' ],
  [ "titulo"=>'Halloumi a la plancha',"descripcion"=>'Queso chipriota de textura firme, marcado a la plancha hasta dorar, con un chorro de limón y hierbas.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://live.staticflickr.com/7397/9507158023_a840c32fd8_b.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['250 g de queso halloumi en lonchas gruesas','Aceite de oliva','Zumo de limón','Orégano seco o menta fresca'],"pasos"=>['Calentar una plancha o sartén sin nada de aceite, o con solo un hilo.','Colocar las lonchas de halloumi y dorarlas 1-2 minutos por cada lado, hasta que se marquen bien.','Retirar y rociar de inmediato con zumo de limón y un chorro de aceite de oliva.','Espolvorear con orégano o menta fresca antes de servir.'],"consejo"=>'Sirve el halloumi inmediatamente después de la plancha: al enfriarse pierde parte de su textura característica y se vuelve gomoso.' ],
  [ "titulo"=>'Kofta a la parrilla',"descripcion"=>'Brochetas alargadas de carne picada especiada con comino, pimentón y hierbas frescas, asadas a la parrilla.',"tiempo"=>'30 min + reposo',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/5d/K%C3%B6fte_kebabs.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['600 g de carne picada de cordero o ternera','1 cebolla rallada y bien escurrida','Perejil y cilantro picados','Comino, pimentón, canela','Sal, pimienta'],"pasos"=>['Mezclar la carne picada con la cebolla escurrida, las hierbas y las especias, amasando bien con las manos hasta integrar todo.','Dejar reposar la mezcla en la nevera 20-30 minutos para que se compacte.','Formar cilindros alargados alrededor de brochetas metálicas o de madera remojada.','Asar a la parrilla, girando con cuidado, hasta que estén doradas por fuera y hechas por dentro.'],"consejo"=>'Escurre muy bien la cebolla rallada antes de mezclarla con la carne: el exceso de agua hace que las brochetas se deshagan en la parrilla.' ],
  [ "titulo"=>'Imam bayildi (berenjenas rellenas turcas)',"descripcion"=>'Berenjenas enteras rellenas de cebolla, tomate y ajo, cocinadas lentamente en aceite de oliva hasta quedar melosas.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/7b/%C4%B0mam_bay%C4%B1ld%C4%B1_AvL.JPG',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['4 berenjenas pequeñas','2 cebollas','3 tomates','3 dientes de ajo','Perejil fresco','Aceite de oliva virgen extra abundante'],"pasos"=>['Hacer un corte longitudinal en cada berenjena sin llegar a separarla del todo, y freírlas ligeramente en aceite de oliva hasta que empiecen a ablandarse.','Sofreír la cebolla, el ajo y el tomate troceado en aceite de oliva hasta obtener un relleno espeso.','Rellenar cada berenjena por el corte con esta mezcla.','Colocar en una cazuela baja, regar con abundante aceite de oliva y un poco de agua.','Cocinar tapado a fuego muy lento 30-40 minutos hasta que las berenjenas estén muy tiernas; servir templado o frío, con perejil fresco.'],"consejo"=>'No escatimes en el aceite de oliva: este plato se cocina prácticamente confitado, y es lo que le da su textura melosa característica.' ],
  [ "titulo"=>'Dolma (hojas de parra rellenas, estilo levantino)',"descripcion"=>'Hojas de parra rellenas de arroz, tomate y hierbas frescas, versión vegetariana levantina servida con yogur.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/75/Sarma.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['25 hojas de parra en salmuera','200 g de arroz de grano redondo','2 tomates picados','Perejil y menta frescos','Zumo de limón, aceite de oliva','Yogur para acompañar'],"pasos"=>['Escaldar las hojas de parra en agua hirviendo 2 minutos y escurrir.','Mezclar el arroz crudo con el tomate picado, las hierbas frescas, el zumo de limón y el aceite de oliva.','Colocar una cucharada de relleno en cada hoja y enrollar bien prieto.','Colocar los rollitos muy juntos en una cazuela, cubrir con agua y un chorro de aceite y limón.','Cocinar tapados a fuego suave 40-45 minutos hasta que el arroz esté tierno; servir templado con yogur.'],"consejo"=>'No aprietes demasiado al rellenar: el arroz crudo necesita espacio para hincharse durante la cocción.' ],
  // Pescados y arroces
  [ "titulo"=>'Paella valenciana',"descripcion"=>'Arroz cocinado en paellera con pollo, conejo y verduras, sazonado con azafrán, el plato de arroz más emblemático de España.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Media',"raciones_base"=>6,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/ed/01_Paella_Valenciana_original.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['500 g de arroz','1 pollo troceado','1 conejo troceado','200 g de judía verde plana','200 g de garrofón (o judía blanca)','Tomate rallado, azafrán, pimentón','Aceite de oliva, caldo o agua'],"pasos"=>['Dorar el pollo y el conejo en la paellera con aceite de oliva hasta que estén bien sellados.','Añadir la judía verde y el garrofón, y sofreír unos minutos.','Incorporar el tomate rallado y el pimentón, sofreír brevemente sin que se queme.','Añadir el agua o caldo caliente con el azafrán disuelto, y cocinar a fuego fuerte 10 minutos y luego medio 8-10 minutos más.','Esparcir el arroz de manera uniforme y cocinar sin remover, a fuego medio-fuerte, unos 18-20 minutos hasta que el líquido se absorba; dejar reposar unos minutos antes de servir.'],"consejo"=>'No remuevas el arroz una vez repartido en la paellera: dejarlo quieto es lo que permite que se forme el socarrat en el fondo.' ],
  [ "titulo"=>'Fideuà',"descripcion"=>'La versión con fideos finos de la paella, cocinada con pescado y marisco, típica de la costa de Alicante y Castellón.',"tiempo"=>'50 min',"tiempoMin"=>50,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/a/a4/Fideua_-_xurde.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['400 g de fideos finos (número 0 o 1)','300 g de gambas','300 g de rape o similar','1 cebolla, 1 tomate rallado','Pimentón, azafrán','Caldo de pescado','Alioli para acompañar'],"pasos"=>['Dorar las gambas y el pescado en una paellera con aceite de oliva, retirar y reservar.','Sofreír la cebolla, añadir el tomate rallado y el pimentón, sofreír brevemente.','Añadir los fideos y tostarlos un par de minutos en el sofrito.','Cubrir con caldo de pescado caliente con el azafrán disuelto, y cocinar a fuego medio-fuerte sin remover, unos 10-12 minutos.','Devolver el pescado y las gambas los últimos minutos de cocción, y servir con alioli aparte.'],"consejo"=>'Tostar los fideos en el sofrito antes de añadir el caldo es el paso clave: les da un sabor y un color mucho más profundos.' ],
  [ "titulo"=>'Arroz negro con calamares',"descripcion"=>'Arroz cocinado con tinta de calamar, que le da su característico color negro intenso, servido con alioli.',"tiempo"=>'50 min',"tiempoMin"=>50,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/1/15/14-08-04-barcelona-RalfR-41.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['400 g de arroz','400 g de calamares limpios y troceados, con sus bolsas de tinta','1 cebolla, 1 pimiento verde','Tomate rallado','Caldo de pescado','Alioli para acompañar'],"pasos"=>['Saltear los calamares en una paellera o cazuela ancha con aceite de oliva hasta dorar.','Añadir la cebolla y el pimiento picados, sofreír hasta que estén tiernos.','Incorporar el tomate rallado y cocinar unos minutos.','Disolver la tinta de calamar en un poco de caldo y añadirla junto con el resto del caldo caliente.','Esparcir el arroz y cocinar sin remover a fuego medio 18-20 minutos hasta que absorba el líquido; servir con alioli.'],"consejo"=>'Disuelve siempre la tinta en un poco de líquido antes de añadirla al conjunto: así se reparte de manera uniforme por todo el arroz.' ],
  [ "titulo"=>'Dorada a la sal',"descripcion"=>'Pescado entero cubierto con una costra de sal gruesa y horneado, técnica que mantiene toda la jugosidad del pescado.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://live.staticflickr.com/3243/3017843692_537583fe76_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['1 dorada grande entera, sin escamar','2 kg de sal gruesa','2 claras de huevo (opcional, para compactar la sal)','Aceite de oliva virgen extra, limón'],"pasos"=>['Mezclar la sal gruesa con las claras de huevo si se desea una costra más compacta.','Cubrir la base de una bandeja de horno con una capa de sal, colocar el pescado entero encima y cubrirlo completamente con el resto de la sal, presionando bien.','Hornear a 200 °C unos 30-35 minutos, calculando aproximadamente 12-15 minutos por cada kilo de pescado.','Romper la costra de sal en la mesa, retirar con cuidado y limpiar los restos antes de servir.','Aliñar con un buen aceite de oliva virgen extra y unas gotas de limón.'],"consejo"=>'No escames el pescado antes de cocinarlo: la piel y las escamas protegen la carne del exceso de sal durante el horneado.' ],
  [ "titulo"=>'Lubina al horno con hierbas provenzales',"descripcion"=>'Lubina entera horneada con tomate, hierbas provenzales y un buen chorro de aceite de oliva.',"tiempo"=>'35 min',"tiempoMin"=>35,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://live.staticflickr.com/2144/1526986088_9ec878fb14_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['1 lubina grande entera, limpia','2 tomates en rodajas','1 limón','Tomillo, romero, orégano','Aceite de oliva virgen extra, sal'],"pasos"=>['Hacer unos cortes diagonales en los lomos de la lubina y salarla por dentro y por fuera.','Colocar en una bandeja de horno sobre una cama de rodajas de tomate y unas rodajas de limón.','Rellenar la cavidad del pescado con ramas de hierbas frescas.','Rociar generosamente con aceite de oliva y espolvorear con más hierbas por encima.','Hornear a 200 °C 20-25 minutos, hasta que la carne se separe con facilidad de la espina.'],"consejo"=>'Cocina la lubina sobre una cama de verdura y hierbas: además de aromatizar el pescado, evita que se pegue a la bandeja.' ],
  [ "titulo"=>'Sardinas rellenas al horno',"descripcion"=>'Sardinas abiertas en libro y rellenas de pan rallado, piñones y hierbas, horneadas hasta quedar doradas.',"tiempo"=>'35 min',"tiempoMin"=>35,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Mediterránea',"photoUrl"=>'https://live.staticflickr.com/2607/4228116293_61bf2426e2_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Principal'],"ingredientes"=>['16 sardinas frescas, limpias y abiertas en libro','Pan rallado, piñones tostados','Ajo y perejil picados','Aceite de oliva, limón'],"pasos"=>['Mezclar el pan rallado con los piñones tostados, el ajo y el perejil picados, y un chorro de aceite de oliva.','Extender esta mezcla sobre el interior de cada sardina abierta y cerrarla de nuevo.','Colocar las sardinas en una bandeja de horno ligeramente aceitada.','Rociar con más aceite de oliva y hornear a 200 °C 12-15 minutos hasta que estén doradas.','Servir con un chorro de limón por encima.'],"consejo"=>'Pide en la pescadería que te abran las sardinas \'en libro\', sin separar los dos lomos: así se rellenan y cierran con mucha más facilidad.' ],
  // Sopas, panes y postres
  [ "titulo"=>'Gazpacho andaluz',"descripcion"=>'Sopa fría de tomate, pepino, pimiento y ajo triturados con aceite de oliva, el refresco vegetal por excelencia del verano andaluz.',"tiempo"=>'15 min + frío',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/c/c0/Gazpacho_Cazuela_Barro.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food','Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Postre'],"ingredientes"=>['1 kg de tomates muy maduros','1 pepino','1 pimiento verde','1 diente de ajo','50 g de pan duro (opcional)','Aceite de oliva virgen extra, vinagre de jerez, sal'],"pasos"=>['Trocear el tomate, el pepino, el pimiento y el ajo.','Triturar todos los ingredientes juntos, con el pan si se usa, hasta obtener una crema muy fina.','Añadir el aceite de oliva en un hilo mientras se sigue triturando, para que emulsione.','Sazonar con vinagre de jerez y sal al gusto, y colar si se desea una textura más fina.','Refrigerar al menos 2 horas antes de servir bien frío.'],"consejo"=>'Usa siempre tomates muy maduros y de temporada: son la base del sabor del gazpacho y no hay truco que compense un tomate mediocre.' ],
  [ "titulo"=>'Salmorejo cordobés',"descripcion"=>'Crema fría y espesa de tomate y pan, más densa que el gazpacho, servida con huevo duro y jamón picados por encima.',"tiempo"=>'20 min + frío',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/eb/Salmorejo_cordobes.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Mediterránea','Postre'],"ingredientes"=>['1 kg de tomates muy maduros','200 g de pan duro','1 diente de ajo','150 ml de aceite de oliva virgen extra','Sal, vinagre','Huevo duro y jamón serrano picados (para servir)'],"pasos"=>['Trocear el tomate y triturarlo con el ajo.','Añadir el pan duro troceado y dejar que se hidrate unos minutos en el propio tomate triturado.','Triturar de nuevo hasta que quede muy fino, incorporando el aceite de oliva poco a poco para que emulsione.','Sazonar con sal y un poco de vinagre, y refrigerar al menos 2 horas.','Servir bien frío, con huevo duro picado y jamón serrano por encima.'],"consejo"=>'La proporción de pan es lo que diferencia el salmorejo del gazpacho: debe quedar mucho más denso, casi para untar.' ],
  [ "titulo"=>'Pisto manchego',"descripcion"=>'Fritada de verduras de La Mancha —calabacín, pimiento, cebolla y tomate— cocinada lentamente hasta quedar melosa.',"tiempo"=>'1 h',"tiempoMin"=>60,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/9/93/Pisto.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Mediterránea','Postre'],"ingredientes"=>['2 calabacines','1 pimiento verde, 1 pimiento rojo','1 cebolla','4 tomates maduros','Aceite de oliva virgen extra, sal, azúcar (una pizca)'],"pasos"=>['Cortar todas las verduras en dados pequeños y uniformes.','Sofreír la cebolla y los pimientos en aceite de oliva a fuego medio-bajo hasta que estén tiernos.','Añadir el calabacín y cocinar 10 minutos más.','Incorporar el tomate troceado o rallado, sazonar y cocinar a fuego lento, tapado, removiendo de vez en cuando, 30-40 minutos hasta que quede meloso y sin exceso de líquido.','Servir templado, solo o con un huevo frito por encima.'],"consejo"=>'Cocina el pisto a fuego lento y con paciencia: cuanto más tiempo, mejor se integran los sabores de las verduras.' ],
  [ "titulo"=>'Pan de pita casero',"descripcion"=>'Pan plano que se hincha en el horno formando una bolsa hueca, base de innumerables platos del Mediterráneo oriental.',"tiempo"=>'1 h 30 min (con reposo)',"tiempoMin"=>90,"dificultad"=>'Media',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/3/32/Pita_Bread.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Mediterránea','Postre'],"ingredientes"=>['500 g de harina de fuerza','1 sobre de levadura seca','1 cucharadita de azúcar','300 ml de agua tibia','Sal, aceite de oliva'],"pasos"=>['Disolver la levadura y el azúcar en el agua tibia, dejar activar 10 minutos.','Mezclar con la harina, la sal y un chorro de aceite de oliva, amasando 8-10 minutos hasta obtener una masa elástica.','Dejar fermentar tapada 1 hora hasta que doble su volumen.','Dividir en bolas y estirar cada una en discos no muy finos; dejar reposar 15 minutos más.','Hornear en horno muy caliente (250 °C), sobre bandeja o piedra precalentada, 3-4 minutos hasta que se hinchen formando la bolsa característica.'],"consejo"=>'Precalienta bien la bandeja o piedra de horno antes de meter los panes: el choque de calor inicial es lo que hace que se hinchen.' ],
  [ "titulo"=>'Pilaf de bulgur con verduras',"descripcion"=>'Bulgur salteado con verduras y especias suaves, guarnición habitual en toda la cocina del Mediterráneo oriental.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Mediterránea',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/a/a3/Bulgur.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Mediterránea','Postre'],"ingredientes"=>['250 g de bulgur grueso','1 cebolla, 1 pimiento rojo','1 zanahoria','400 ml de caldo de verduras','Comino, pimentón, aceite de oliva','Perejil fresco'],"pasos"=>['Sofreír la cebolla, el pimiento y la zanahoria en aceite de oliva hasta que estén tiernos.','Añadir el bulgur y tostarlo un par de minutos removiendo.','Incorporar las especias y el caldo caliente.','Cocinar tapado a fuego bajo 15-18 minutos hasta que el bulgur haya absorbido el líquido y esté tierno.','Dejar reposar 5 minutos, esponjar con un tenedor y terminar con perejil fresco picado.'],"consejo"=>'Tuesta siempre el bulgur en el sofrito antes de añadir el líquido: potencia mucho su sabor frente a cocerlo directamente en el caldo.' ],
  [ "titulo"=>'Yogur griego con miel y nueces',"descripcion"=>'El postre mediterráneo más sencillo: yogur griego espeso con un buen chorro de miel y nueces troceadas.',"tiempo"=>'5 min',"tiempoMin"=>5,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Mediterránea',"photoUrl"=>'https://live.staticflickr.com/46/139065591_d335d465a3.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food','Quitar el hambre rápido'],"etiquetas"=>['Mediterránea','Postre'],"ingredientes"=>['500 g de yogur griego espeso','4 cucharadas de miel','Un puñado de nueces troceadas','Canela molida (opcional)'],"pasos"=>['Repartir el yogur griego en cuencos individuales.','Rociar generosamente con miel.','Espolvorear con nueces troceadas.','Añadir una pizca de canela molida si se desea, y servir de inmediato.'],"consejo"=>'Elige un yogur griego bien espeso y con cuerpo: es lo que sostiene el peso de la miel y las nueces sin quedar aguado.' ],

  // ═══ FÁCIL Y CASERA ═══
  // Desayunos y meriendas
  [ "titulo"=>'Tostadas con aguacate y huevo',"descripcion"=>'Pan tostado con aguacate machacado y un huevo por encima, desayuno rápido y muy socorrido.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>2,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/5b/Avocado_toast_at_Voyager_Espresso_%2833134505776%29.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['2 rebanadas de pan','1 aguacate maduro','2 huevos','Sal, pimienta','Aceite de oliva','Zumo de limón (opcional)'],"pasos"=>['Tostar el pan hasta que esté crujiente.','Machacar el aguacate con un tenedor, salpimentar y añadir un poco de zumo de limón.','Cocinar los huevos al gusto (fritos, escalfados o pochados).','Untar el pan con el aguacate y colocar el huevo encima.','Terminar con un chorro de aceite de oliva y un poco más de pimienta.'],"consejo"=>'Añade el limón al aguacate nada más machacarlo: evita que se oxide y se ponga oscuro mientras preparas el resto.' ],
  [ "titulo"=>'Tortitas americanas (pancakes)',"descripcion"=>'Tortitas esponjosas de sartén, el desayuno dulce más clásico, con solo cuatro ingredientes básicos.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/40/Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Ligero para la noche'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['200 g de harina','2 huevos','250 ml de leche','1 cucharada de azúcar','1 cucharadita de levadura','Una pizca de sal','Mantequilla para la sartén','Sirope o miel para servir'],"pasos"=>['Mezclar la harina, la levadura, el azúcar y la sal en un bol.','Batir los huevos con la leche y añadirlos a los ingredientes secos, mezclando hasta que no queden grumos grandes.','Calentar una sartén antiadherente con un poco de mantequilla a fuego medio.','Verter un cucharón de masa por cada tortita y cocinar hasta que salgan burbujas en la superficie, dar la vuelta y dorar el otro lado.','Servir apiladas con sirope o miel.'],"consejo"=>'No remuevas la masa en exceso: un poco de grumo está bien, batir de más hace que las tortitas queden duras.' ],
  [ "titulo"=>'Bizcocho de yogur',"descripcion"=>'El bizcocho casero más sencillo de España, medido con el propio vaso de yogur, esponjoso y jugoso.',"tiempo"=>'50 min',"tiempoMin"=>50,"dificultad"=>'Fácil',"raciones_base"=>8,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/5296/5419458342_30f479160b_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['1 yogur natural','3 huevos','2 medidas (del vaso de yogur) de azúcar','1 medida de aceite de girasol','3 medidas de harina','1 sobre de levadura química','Ralladura de limón (opcional)'],"pasos"=>['Precalentar el horno a 180 °C y engrasar un molde.','Mezclar en un bol el yogur, el azúcar, el aceite y los huevos hasta integrar bien.','Añadir la harina tamizada con la levadura, mezclando con movimientos suaves hasta que no queden grumos.','Verter en el molde y hornear 35-40 minutos, hasta que al pinchar con un palillo salga limpio.','Dejar enfriar antes de desmoldar.'],"consejo"=>'Usa el mismo vaso del yogur para medir todos los ingredientes: es la gracia de esta receta y evita tener que sacar la báscula.' ],
  [ "titulo"=>'Batido de plátano y avena',"descripcion"=>'Batido cremoso y nutritivo con solo tres ingredientes, listo en un minuto con la batidora.',"tiempo"=>'5 min',"tiempoMin"=>5,"dificultad"=>'Fácil',"raciones_base"=>2,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://commons.wikimedia.org/wiki/Special:FilePath/Batido%20de%20pl%C3%A1tano%20y%20manzana%20con%20almendras%20-%20Banana%20and%20apple%20smothie%20(4723976402).jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['2 plátanos maduros','300 ml de leche (o bebida vegetal)','3 cucharadas de copos de avena','Miel al gusto (opcional)','Canela (opcional)'],"pasos"=>['Trocear los plátanos.','Poner todos los ingredientes en el vaso de la batidora.','Triturar hasta que quede una mezcla lisa y cremosa.','Servir frío, recién hecho.'],"consejo"=>'Usa plátanos bien maduros, con manchas: son más dulces y hacen que el batido quede más cremoso sin necesidad de añadir azúcar.' ],
  [ "titulo"=>'Tostada francesa rápida',"descripcion"=>'Rebanadas de pan empapadas en huevo y leche, doradas en la sartén, la forma más sencilla de aprovechar el pan del día anterior.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/4/42/FrenchToast.JPG',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['8 rebanadas de pan del día anterior','2 huevos','200 ml de leche','1 cucharada de azúcar','Canela molida','Mantequilla para la sartén'],"pasos"=>['Batir los huevos con la leche, el azúcar y una pizca de canela.','Remojar cada rebanada de pan en la mezcla por ambos lados, sin que se deshaga.','Calentar mantequilla en una sartén a fuego medio.','Dorar las rebanadas 2-3 minutos por cada lado, hasta que estén doradas.','Servir espolvoreadas con azúcar y canela, o con sirope.'],"consejo"=>'Usa pan del día anterior, algo duro: absorbe mejor la mezcla de huevo y leche sin deshacerse.' ],
  // Huevos y tortillas
  [ "titulo"=>'Huevos revueltos con jamón',"descripcion"=>'Huevos revueltos cremosos con taquitos de jamón, listos en cinco minutos.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>2,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/3721/11380609084_33366b3c53_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['4 huevos','80 g de jamón cocido o serrano en taquitos','Mantequilla o aceite','Sal, pimienta'],"pasos"=>['Batir los huevos con una pizca de sal y pimienta.','Calentar un poco de mantequilla en una sartén a fuego bajo.','Añadir el jamón y saltear un minuto.','Verter los huevos batidos y remover constantemente con una espátula a fuego bajo hasta que cuajen de forma cremosa.','Retirar del fuego un poco antes de que estén del todo hechos: siguen cuajando fuera del fuego.'],"consejo"=>'Cocina siempre a fuego bajo y sin prisa: es lo que hace que los huevos revueltos queden cremosos en vez de secos y gomosos.' ],
  [ "titulo"=>'Tortilla francesa',"descripcion"=>'La tortilla más simple de todas, con solo huevo y sal, doblada en dos o enrollada.',"tiempo"=>'5 min',"tiempoMin"=>5,"dificultad"=>'Fácil',"raciones_base"=>1,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/d/d7/Omelette_with_butter_and_tomatoes.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['2-3 huevos','Sal','Aceite de oliva o mantequilla'],"pasos"=>['Batir los huevos con una pizca de sal.','Calentar una sartén pequeña con un poco de aceite a fuego medio-alto.','Verter el huevo batido y dejar que cuaje por los bordes, moviendo la sartén.','Cuando esté cuajado pero aún jugoso en el centro, doblar por la mitad o enrollar.','Servir de inmediato.'],"consejo"=>'No la dejes en la sartén más de lo necesario: la tortilla francesa está en su punto cuando aún queda algo jugosa por dentro.' ],
  [ "titulo"=>'Huevos al plato con tomate',"descripcion"=>'Huevos cuajados al horno sobre una base de tomate frito, plato reconfortante y muy fácil de preparar.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/2278/2175095780_b2619e1f7b_b.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['4 huevos','400 g de tomate frito (casero o de bote)','Queso rallado (opcional)','Perejil fresco','Sal, pimienta','Pan para acompañar'],"pasos"=>['Precalentar el horno a 200 °C.','Repartir el tomate frito en cazuelitas individuales o una fuente para horno.','Cascar un huevo sobre cada base de tomate.','Espolvorear con queso rallado si se desea.','Hornear 10-12 minutos hasta que la clara esté cuajada y la yema aún jugosa; terminar con perejil fresco.'],"consejo"=>'Vigila el horno los últimos minutos: el punto de la yema cambia muy rápido y es fácil pasarse de cocción.' ],
  [ "titulo"=>'Huevos rellenos',"descripcion"=>'Huevos cocidos rellenos de su propia yema mezclada con mayonesa y atún, aperitivo clásico de cualquier celebración.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/b/bc/Deviled_Eggs_-_3-23-08.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['6 huevos','100 g de atún en conserva','3 cucharadas de mayonesa','Pimentón dulce','Perejil o aceitunas para decorar'],"pasos"=>['Cocer los huevos 10-11 minutos, enfriar en agua fría y pelar.','Cortar por la mitad a lo largo y retirar las yemas con cuidado.','Machacar las yemas con el atún escurrido y la mayonesa hasta obtener una pasta homogénea.','Rellenar cada mitad de clara con esta mezcla, con una cuchara o manga pastelera.','Espolvorear con pimentón y decorar con perejil o una aceituna.'],"consejo"=>'Enfría los huevos en agua con hielo justo después de cocerlos: se pelan mucho más fácil y limpio.' ],
  [ "titulo"=>'Tortilla de calabacín',"descripcion"=>'Tortilla ligera de calabacín y cebolla, una alternativa rápida a la tortilla de patatas.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/3115/3103616016_9c77464cf7_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['2 calabacines','1 cebolla','6 huevos','Aceite de oliva, sal'],"pasos"=>['Cortar el calabacín y la cebolla en dados pequeños.','Pochar ambos en una sartén con aceite de oliva hasta que estén tiernos.','Batir los huevos con sal y mezclar con las verduras pochadas y escurridas.','Cuajar la tortilla en la misma sartén con un poco más de aceite, dando la vuelta con ayuda de un plato.','Dejar reposar unos minutos antes de cortar.'],"consejo"=>'Escurre bien el calabacín pochado antes de mezclarlo con el huevo: si lleva demasiada agua, la tortilla no cuaja bien.' ],
  // Ensaladas sencillas
  [ "titulo"=>'Ensalada de lechuga, tomate y maíz',"descripcion"=>'La ensalada más básica de cualquier casa, lista en cinco minutos con solo cuatro ingredientes.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/2771/4242964162_90b4006387_b.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Quitar el hambre rápido','Ligero para la noche'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['1 lechuga','2 tomates','1 lata de maíz dulce','1 cebolla pequeña (opcional)','Aceite de oliva, vinagre, sal'],"pasos"=>['Lavar y trocear la lechuga.','Cortar el tomate en dados o gajos.','Escurrir el maíz y añadirlo junto con la cebolla en juliana fina, si se usa.','Aliñar con aceite, vinagre y sal justo antes de servir.'],"consejo"=>'Seca bien la lechuga después de lavarla: si queda agua, el aliño se diluye y la ensalada pierde sabor.' ],
  [ "titulo"=>'Ensalada de pasta fría',"descripcion"=>'Pasta cocida y enfriada, mezclada con verduras frescas y atún, ideal para llevar o para el verano.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/e/e1/Pasta_salad_closeup.JPG',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['300 g de pasta corta (macarrones o similar)','1 lata de atún','1 tomate, 1/2 pimiento','Aceitunas','Maíz dulce','Aceite de oliva, vinagre, sal'],"pasos"=>['Cocer la pasta según las instrucciones del paquete, escurrir y enfriar bajo el grifo.','Cortar el tomate y el pimiento en dados pequeños.','Mezclar la pasta con el atún escurrido, las verduras, las aceitunas y el maíz.','Aliñar con aceite, vinagre y sal, y remover bien.','Refrigerar al menos 30 minutos antes de servir.'],"consejo"=>'Enfría la pasta bajo el grifo justo después de escurrirla: corta la cocción y evita que se pase de blanda.' ],
  [ "titulo"=>'Ensalada de patata',"descripcion"=>'Patata cocida en dados con mayonesa, huevo duro y un toque de mostaza, guarnición o plato único muy socorrido.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/5e/Kartoffelsalat.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['800 g de patatas','2 huevos','3 cucharadas de mayonesa','1 cucharadita de mostaza','Cebolleta picada','Sal, pimienta'],"pasos"=>['Cocer las patatas con piel en agua con sal hasta que estén tiernas, escurrir, dejar templar y pelar.','Cocer los huevos, pelar y trocear.','Cortar las patatas en dados.','Mezclar la mayonesa con la mostaza y aliñar la patata y el huevo con esta mezcla.','Añadir cebolleta picada, salpimentar y refrigerar antes de servir.'],"consejo"=>'Cuece las patatas con piel: absorben menos agua y quedan con mejor textura para cortar en dados después.' ],
  [ "titulo"=>'Ensalada de arroz',"descripcion"=>'Arroz blanco frío mezclado con verduras crujientes, maíz y jamón cocido, plato fresco y muy versátil.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/4111/4987664909_8cef36541e_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['300 g de arroz','1 zanahoria, 1/2 pimiento rojo','1 lata de maíz','100 g de jamón cocido en taquitos','Aceite de oliva, vinagre, sal'],"pasos"=>['Cocer el arroz según las instrucciones del paquete, escurrir y enfriar.','Cortar la zanahoria y el pimiento en dados muy pequeños.','Mezclar el arroz frío con las verduras, el maíz escurrido y el jamón.','Aliñar con aceite, vinagre y sal, y remover bien antes de servir.'],"consejo"=>'Corta las verduras en dados pequeños y del mismo tamaño que los granos de arroz: la ensalada queda mucho más agradable de comer.' ],
  [ "titulo"=>'Ensalada César sencilla',"descripcion"=>'Versión casera y rápida de la clásica ensalada César, con pollo a la plancha, picatostes y una salsa cremosa fácil.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/2/23/Caesar_salad_%282%29.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['1 lechuga romana','2 pechugas de pollo','2 rebanadas de pan (para picatostes)','Queso parmesano rallado','3 cucharadas de mayonesa','1 diente de ajo, zumo de limón, mostaza'],"pasos"=>['Cocinar las pechugas de pollo a la plancha con sal y pimienta, y cortarlas en tiras.','Tostar el pan en dados en una sartén con un poco de aceite hasta que estén crujientes (picatostes).','Preparar la salsa mezclando mayonesa, ajo picado muy fino, zumo de limón y una pizca de mostaza.','Trocear la lechuga romana y mezclar con la salsa.','Añadir el pollo, los picatostes y el parmesano rallado por encima.'],"consejo"=>'Corta el pollo justo antes de servir, no con antelación: se enfría rápido y pierde su punto jugoso.' ],
  // Sopas y cremas
  [ "titulo"=>'Sopa de fideos casera',"descripcion"=>'Sopa clara de caldo casero con fideos finos, el remedio de toda la vida para los días fríos.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/5e/Nabeyaku_ramen_%28cropped%29.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['1,5 litros de caldo de pollo o de verduras','150 g de fideos finos','1 zanahoria (opcional)','Sal','Perejil fresco'],"pasos"=>['Llevar el caldo a ebullición.','Añadir la zanahoria en rodajas finas si se usa, y cocinar 5 minutos.','Incorporar los fideos y cocinar el tiempo indicado en el paquete, normalmente 3-4 minutos.','Rectificar de sal y servir bien caliente con perejil picado.'],"consejo"=>'Añade los fideos solo al final: si se cuecen demasiado tiempo, se pasan y la sopa queda espesa en exceso.' ],
  [ "titulo"=>'Crema de calabacín',"descripcion"=>'Crema suave y ligera de calabacín, lista en veinte minutos con muy pocos ingredientes.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/5133/5571107308_53788f38fd_b.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['4 calabacines','1 patata pequeña','1 cebolla','500 ml de caldo de verduras o agua','Aceite de oliva, sal','Queso en porciones o nata (opcional)'],"pasos"=>['Pochar la cebolla en aceite de oliva hasta que esté transparente.','Añadir el calabacín y la patata troceados, y rehogar unos minutos.','Cubrir con el caldo y cocinar 15-20 minutos hasta que las verduras estén muy tiernas.','Triturar hasta obtener una crema fina, añadiendo queso en porciones o un poco de nata si se desea más cremosidad.','Rectificar de sal y servir caliente.'],"consejo"=>'No peles el calabacín: la piel aporta color y parte del sabor a la crema.' ],
  [ "titulo"=>'Puré de patata y zanahoria',"descripcion"=>'Puré sencillo y nutritivo, perfecto como plato de cuchara o como guarnición.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/3192/2759721625_937b3a1ffa_m.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['4 patatas','3 zanahorias','1 puerro (opcional)','Caldo o agua','Aceite de oliva o mantequilla, sal'],"pasos"=>['Pelar y trocear las patatas y las zanahorias.','Cocer en agua o caldo con sal hasta que estén muy tiernas, unos 20 minutos.','Escurrir, reservando un poco del líquido de cocción.','Triturar con un poco de aceite de oliva o mantequilla, añadiendo líquido de cocción hasta lograr la textura deseada.'],"consejo"=>'Reserva siempre un poco del agua de cocción antes de escurrir: es la mejor forma de ajustar la textura del puré sin diluir el sabor.' ],
  [ "titulo"=>'Sopa de pollo con arroz',"descripcion"=>'Sopa reconfortante de caldo de pollo con arroz y verduras, clásica para los días de resfriado.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/2256/2500744954_17b7efa345_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['1,5 litros de caldo de pollo','150 g de arroz','150 g de pollo cocido desmenuzado','1 zanahoria','Perejil fresco, sal'],"pasos"=>['Llevar el caldo a ebullición.','Añadir la zanahoria en dados pequeños y cocinar 5 minutos.','Incorporar el arroz y cocinar el tiempo indicado en el paquete.','Añadir el pollo desmenuzado en los últimos minutos para que se caliente sin secarse.','Rectificar de sal y servir con perejil fresco picado.'],"consejo"=>'Añade el pollo ya cocido al final, solo para calentarlo: si se cocina demasiado tiempo en el caldo se queda seco.' ],
  [ "titulo"=>'Crema de calabaza',"descripcion"=>'Crema dulce y aterciopelada de calabaza asada, perfecta para el otoño con muy pocos ingredientes.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'entrante',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/4105/4995482360_563937cde6_b.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Entrante'],"ingredientes"=>['800 g de calabaza','1 cebolla','1 patata pequeña','500 ml de caldo de verduras','Aceite de oliva, sal','Nata o queso crema (opcional)'],"pasos"=>['Pochar la cebolla en aceite de oliva.','Añadir la calabaza y la patata troceadas, y rehogar unos minutos.','Cubrir con el caldo y cocinar 20-25 minutos hasta que estén muy tiernas.','Triturar hasta obtener una crema fina, añadiendo un poco de nata o queso crema si se desea.','Rectificar de sal y servir caliente.'],"consejo"=>'Si tienes tiempo, asa la calabaza en el horno en vez de cocerla: concentra mucho más su dulzor natural.' ],
  // Pasta y arroz fácil
  [ "titulo"=>'Macarrones con tomate y queso',"descripcion"=>'El plato de pasta más sencillo y agradecido de todos, con tomate frito y queso rallado gratinado.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/4135/4820238049_8e830ec494_b.jpg',"dietas"=>['Vegetariana','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['350 g de macarrones','400 g de tomate frito','Queso rallado','Aceite de oliva, sal','Orégano (opcional)'],"pasos"=>['Cocer los macarrones en agua con sal según las instrucciones del paquete.','Escurrir y mezclar con el tomate frito caliente.','Repartir en una fuente y cubrir con queso rallado.','Gratinar en el horno unos minutos hasta que el queso se funda y dore, o servir directamente con el queso recién fundido.'],"consejo"=>'Reserva un poco del agua de cocción de la pasta: un chorrito ayuda a que el tomate se integre mejor con los macarrones.' ],
  [ "titulo"=>'Espaguetis al ajillo',"descripcion"=>'Espaguetis salteados con ajo laminado, aceite de oliva y guindilla, el plato de pasta más rápido que existe.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/6/6f/Aglio_e_olio.jpg',"dietas"=>['Vegana','Vegetariana','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['350 g de espaguetis','4 dientes de ajo','Aceite de oliva virgen extra','Guindilla o pimienta negra','Perejil fresco, sal'],"pasos"=>['Cocer los espaguetis en agua con sal hasta el punto al dente.','Mientras tanto, calentar aceite de oliva a fuego suave y dorar el ajo laminado sin que se queme.','Añadir la guindilla o un poco de pimienta.','Escurrir la pasta y saltearla directamente en la sartén con el ajo y el aceite.','Terminar con perejil fresco picado.'],"consejo"=>'Dora el ajo a fuego muy suave: si se quema, amarga todo el plato y hay que empezar de nuevo.' ],
  [ "titulo"=>'Arroz blanco con tomate frito',"descripcion"=>'Arroz blanco sencillo servido con tomate frito casero, guarnición o plato ligero de toda la vida.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/3241/5697759851_f9f60ef14c_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['300 g de arroz','600 ml de agua','Sal','400 g de tomate frito','Un huevo frito por persona (opcional)'],"pasos"=>['Cocer el arroz en agua con sal, en proporción doble de agua que de arroz, hasta que absorba todo el líquido.','Calentar el tomate frito en un cazo.','Servir el arroz con el tomate por encima.','Añadir un huevo frito si se desea un plato más completo.'],"consejo"=>'No destapes la cazuela mientras se cuece el arroz: el vapor atrapado es lo que asegura una cocción uniforme.' ],
  [ "titulo"=>'Pasta con atún y tomate',"descripcion"=>'Pasta corta con una salsa rápida de atún, tomate y aceitunas, plato de despensa listo en veinte minutos.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/6157/6183287597_5c25ed3377_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['350 g de pasta corta','2 latas de atún','400 g de tomate triturado','1 diente de ajo','Aceitunas negras','Aceite de oliva, orégano, sal'],"pasos"=>['Cocer la pasta en agua con sal según las instrucciones del paquete.','Sofreír el ajo picado en aceite de oliva, añadir el tomate triturado y cocinar 10 minutos.','Incorporar el atún escurrido y las aceitunas, cocinar 3-4 minutos más.','Escurrir la pasta y mezclar con la salsa, espolvoreando con orégano.'],"consejo"=>'Añade el atún al final y sin remover demasiado: se deshace con facilidad y es mejor que queden trozos visibles.' ],
  [ "titulo"=>'Arroz tres delicias sencillo',"descripcion"=>'Versión casera del clásico arroz tres delicias, con huevo, jamón york y guisantes, listo con arroz sobrante.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/2371/1850503411_2414f61e43_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['400 g de arroz cocido y frío','2 huevos','100 g de jamón york en dados','150 g de guisantes cocidos','Salsa de soja, aceite'],"pasos"=>['Batir los huevos y cuajarlos en una sartén en trozos pequeños, retirar y reservar.','Saltear el jamón york en la misma sartén con un poco de aceite.','Añadir el arroz frío, desmenuzando los grumos, y saltear a fuego fuerte.','Incorporar los guisantes y el huevo cuajado, y un chorrito de salsa de soja.','Mezclar bien y servir caliente.'],"consejo"=>'Usa siempre arroz frío, preferiblemente del día anterior: el arroz recién hecho tiene demasiada humedad y queda apelmazado.' ],
  // Pollo y carne fácil
  [ "titulo"=>'Pollo al horno con patatas',"descripcion"=>'El clásico de cualquier domingo: pollo entero o troceado asado junto con patatas, todo en la misma bandeja.',"tiempo"=>'1 h 15 min',"tiempoMin"=>75,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/3953/15341412949_3f28c084be_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['1 pollo troceado (o piezas al gusto)','800 g de patatas','2 dientes de ajo','Aceite de oliva','Sal, pimienta, orégano o romero'],"pasos"=>['Precalentar el horno a 200 °C.','Cortar las patatas en trozos grandes y colocarlas en una bandeja de horno.','Salpimentar el pollo y colocarlo sobre las patatas.','Rociar todo con aceite de oliva y espolvorear con ajo picado y hierbas.','Hornear 50-60 minutos, dando la vuelta a mitad de cocción, hasta que el pollo esté dorado y las patatas tiernas.'],"consejo"=>'Corta las patatas en trozos similares de tamaño: así se hacen todas por igual y no quedan unas crudas y otras pasadas.' ],
  [ "titulo"=>'Filetes de pollo empanados',"descripcion"=>'Filetes de pechuga rebozados en huevo y pan rallado, fritos hasta quedar dorados y crujientes.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/2155/2157401172_6c82371fe6.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['4 filetes de pechuga de pollo','Harina, 2 huevos, pan rallado','Aceite para freír','Sal, pimienta'],"pasos"=>['Salpimentar los filetes de pollo.','Pasarlos por harina, sacudiendo el exceso.','Pasarlos después por huevo batido y por pan rallado, presionando para que se adhiera bien.','Freír en aceite caliente 3-4 minutos por lado, hasta que estén dorados y bien cocinados por dentro.','Escurrir sobre papel absorbente antes de servir.'],"consejo"=>'Aplana un poco los filetes con la mano o un mazo antes de rebozarlos: se cocinan de forma más uniforme.' ],
  [ "titulo"=>'Albóndigas en salsa de tomate',"descripcion"=>'Albóndigas caseras de carne picada guisadas en una salsa de tomate sencilla, plato de siempre para toda la familia.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/4029/4680044035_1852ae72bd_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['500 g de carne picada mixta','1 huevo','Pan rallado, leche','Ajo y perejil picados','400 g de tomate triturado','1 cebolla','Harina, aceite de oliva, sal'],"pasos"=>['Remojar un poco de pan rallado en leche y mezclarlo con la carne picada, el huevo, el ajo y el perejil.','Formar bolitas y pasarlas ligeramente por harina.','Dorarlas en una sartén con aceite y reservar.','Sofreír la cebolla en la misma sartén, añadir el tomate triturado y cocinar 10 minutos.','Incorporar las albóndigas a la salsa y cocinar a fuego suave 15-20 minutos, moviendo la cazuela de vez en cuando.'],"consejo"=>'Remoja el pan rallado en leche antes de mezclarlo con la carne: hace que las albóndigas queden mucho más jugosas.' ],
  [ "titulo"=>'Hamburguesas caseras',"descripcion"=>'Hamburguesas de carne picada sazonada, hechas a la plancha, con pan, lechuga y tomate.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/2607/4228116293_61bf2426e2_b.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['500 g de carne picada de ternera','Sal, pimienta','4 panes de hamburguesa','Lechuga, tomate, cebolla','Queso en lonchas, kétchup y mostaza al gusto'],"pasos"=>['Salpimentar la carne picada y formar cuatro hamburguesas, sin amasar en exceso.','Cocinar en una plancha o sartén bien caliente, 3-4 minutos por lado según el punto deseado.','Añadir una loncha de queso encima en el último minuto para que se funda.','Tostar ligeramente el pan.','Montar la hamburguesa con lechuga, tomate, cebolla y las salsas al gusto.'],"consejo"=>'No presiones la hamburguesa con la espátula mientras se hace: se escurren los jugos y queda más seca.' ],
  [ "titulo"=>'Solomillo de cerdo con mostaza',"descripcion"=>'Solomillo de cerdo dorado y terminado con una salsa cremosa de mostaza, plato elegante pero muy sencillo.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/4152/5090562250_67f43b8aff_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['1 solomillo de cerdo','2 cucharadas de mostaza','150 ml de nata para cocinar','Aceite de oliva, sal, pimienta'],"pasos"=>['Salpimentar el solomillo y dorarlo en una sartén con aceite por todos lados.','Bajar el fuego y seguir cocinando hasta que esté hecho por dentro, unos 12-15 minutos; retirar y dejar reposar.','En la misma sartén, añadir la mostaza y la nata, removiendo para recoger los jugos del fondo.','Cocinar la salsa 2-3 minutos hasta que espese ligeramente.','Cortar el solomillo en medallones y bañar con la salsa.'],"consejo"=>'Deja reposar la carne unos minutos antes de cortarla: así conserva mejor sus jugos en vez de perderlos al cortar en caliente.' ],
  [ "titulo"=>'Pechuga de pollo a la plancha con limón',"descripcion"=>'Pechuga de pollo jugosa a la plancha, con un toque de limón y ajo, lista en menos de veinte minutos.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/143/335163752_6dee79e3be_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['4 pechugas de pollo','2 dientes de ajo','Zumo de 1 limón','Aceite de oliva, sal, pimienta','Perejil fresco'],"pasos"=>['Salpimentar las pechugas de pollo.','Calentar una plancha o sartén con un poco de aceite de oliva.','Cocinar las pechugas 4-5 minutos por cada lado, hasta que estén doradas y hechas por dentro.','En los últimos minutos, añadir el ajo picado y el zumo de limón, dejando que impregne el pollo.','Terminar con perejil fresco picado antes de servir.'],"consejo"=>'No pinches el pollo con el tenedor mientras se hace: se escapan los jugos y queda más seco.' ],
  // Pescado fácil
  [ "titulo"=>'Merluza a la plancha con ajo y perejil',"descripcion"=>'Filetes de merluza dorados en la plancha con un refrito rápido de ajo y perejil, el pescado más agradecido de preparar.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/7678/17207742189_74b0135cfa_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['4 filetes de merluza','Harina','2 dientes de ajo','Perejil fresco','Aceite de oliva, sal','Un chorrito de vinagre (opcional)'],"pasos"=>['Salar los filetes de merluza y pasarlos ligeramente por harina.','Dorarlos en una plancha o sartén con aceite de oliva, 2-3 minutos por lado.','Aparte, calentar un poco de aceite con el ajo laminado hasta dorar.','Añadir el perejil picado y, si se desea, un chorrito de vinagre.','Verter este refrito caliente sobre la merluza justo antes de servir.'],"consejo"=>'No la dejes demasiado tiempo en la plancha: la merluza se hace muy rápido y se seca con facilidad si se pasa de cocción.' ],
  [ "titulo"=>'Salmón al horno con limón',"descripcion"=>'Lomos de salmón horneados con rodajas de limón y hierbas, plato sano y muy rápido de preparar.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/3033/4566209370_6a4af45f65_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['4 lomos de salmón','1 limón','Aceite de oliva','Sal, pimienta','Eneldo o perejil fresco'],"pasos"=>['Precalentar el horno a 200 °C.','Colocar los lomos de salmón en una bandeja de horno.','Salpimentar y rociar con aceite de oliva.','Cubrir con rodajas finas de limón y espolvorear con eneldo o perejil.','Hornear 12-15 minutos, según el grosor, hasta que esté hecho pero jugoso por dentro.'],"consejo"=>'No lo dejes de más en el horno: el salmón sigue cocinándose unos minutos fuera con el calor residual.' ],
  [ "titulo"=>'Palitos de pescado empanados caseros',"descripcion"=>'Tiras de pescado blanco rebozadas y fritas, versión casera de los populares palitos de pescado.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/6/64/Fishfinger_classic_fried_2.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['600 g de filetes de pescado blanco (merluza o similar)','Harina, 2 huevos, pan rallado','Aceite para freír','Sal, limón para servir'],"pasos"=>['Cortar el pescado en tiras regulares y salar ligeramente.','Pasar cada tira por harina, huevo batido y pan rallado.','Freír en aceite caliente hasta que estén dorados y crujientes por fuera, unos 3-4 minutos.','Escurrir sobre papel absorbente y servir con un chorro de limón.'],"consejo"=>'Seca bien el pescado antes de rebozarlo: si está húmedo, el pan rallado no se adhiere bien y se desprende al freír.' ],
  [ "titulo"=>'Atún encebollado',"descripcion"=>'Rodajas de atún guisadas con cebolla pochada muy lentamente, plato sencillo y muy jugoso.',"tiempo"=>'40 min',"tiempoMin"=>40,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/51/12-atun-encebollado1.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['4 rodajas de atún fresco','3 cebollas','1 diente de ajo','Aceite de oliva, sal','Un chorrito de vino blanco (opcional)'],"pasos"=>['Cortar la cebolla en juliana fina y pocharla en aceite de oliva a fuego lento durante 25-30 minutos, hasta que esté muy tierna y dulce.','Añadir el ajo picado los últimos minutos.','Salar el atún y dorarlo brevemente en una sartén aparte, 1 minuto por cada lado.','Añadir el atún a la cebolla pochada, con un chorrito de vino blanco si se desea, y cocinar 3-4 minutos más a fuego suave.'],"consejo"=>'Pocha la cebolla con mucha paciencia y fuego bajo: cuanto más lenta la cocción, más dulce y melosa queda.' ],
  [ "titulo"=>'Gambas al ajillo fácil',"descripcion"=>'Gambas salteadas con ajo laminado y guindilla en aceite de oliva, tapa rápida de cualquier casa española.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/c/c3/Spicy_fried_King_Prawns.jpg',"dietas"=>['Para carnívoros','Amante del picante'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['500 g de gambas peladas','4 dientes de ajo','1 guindilla seca (opcional)','Aceite de oliva virgen extra','Sal, perejil fresco'],"pasos"=>['Calentar el aceite de oliva en una sartén con el ajo laminado y la guindilla a fuego medio.','Cuando el ajo empiece a dorarse, añadir las gambas.','Saltear 2-3 minutos, hasta que las gambas cambien de color.','Salar y espolvorear con perejil fresco picado antes de servir bien caliente.'],"consejo"=>'No dejes las gambas más de 2-3 minutos en el fuego: se vuelven gomosas si se cocinan de más.' ],
  // Verduras y guarniciones
  [ "titulo"=>'Puré de patatas',"descripcion"=>'El puré cremoso de siempre, con mantequilla y leche, la guarnición más socorrida de todas.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/7b/Mash_Potatoes.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['1 kg de patatas','50 g de mantequilla','150 ml de leche caliente','Sal, nuez moscada (opcional)'],"pasos"=>['Pelar y trocear las patatas, y cocerlas en agua con sal hasta que estén muy tiernas.','Escurrir bien.','Machacar con un pasapurés o tenedor hasta que no queden grumos.','Añadir la mantequilla y la leche caliente poco a poco, removiendo hasta lograr una textura cremosa.','Sazonar con sal y, si se desea, un poco de nuez moscada.'],"consejo"=>'Usa siempre la leche caliente, nunca fría: la leche fría enfría de golpe el puré y hace que quede menos suave.' ],
  [ "titulo"=>'Patatas al horno',"descripcion"=>'Patatas asadas al horno con aceite de oliva y romero, doradas y crujientes por fuera, tiernas por dentro.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/6168/6198099382_869c870e9a_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['1 kg de patatas','Aceite de oliva','Sal, romero o tomillo','Ajo (opcional)'],"pasos"=>['Precalentar el horno a 200 °C.','Cortar las patatas en cuartos o gajos, del mismo tamaño.','Colocarlas en una bandeja, rociar con aceite de oliva y espolvorear con sal y romero.','Hornear 35-40 minutos, dando la vuelta a mitad de cocción, hasta que estén doradas y crujientes.'],"consejo"=>'No amontones las patatas en la bandeja: si están muy juntas se cuecen al vapor en vez de dorarse.' ],
  [ "titulo"=>'Judías verdes con jamón',"descripcion"=>'Judías verdes cocidas y salteadas con ajo y taquitos de jamón, guarnición clásica de cualquier casa.',"tiempo"=>'25 min',"tiempoMin"=>25,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/3088/3160540977_4b550a4500_b.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['500 g de judías verdes','80 g de jamón serrano en taquitos','2 dientes de ajo','Aceite de oliva, sal'],"pasos"=>['Limpiar las judías verdes y cocerlas en agua con sal hasta que estén tiernas pero firmes, unos 10-12 minutos.','Escurrir bien.','Saltear el ajo laminado en aceite de oliva hasta dorar ligeramente.','Añadir el jamón y saltear un minuto.','Incorporar las judías verdes escurridas y saltear todo junto 2-3 minutos.'],"consejo"=>'No cuezas las judías de más: deben quedar con un punto firme, no blandas del todo, para que aguanten bien el salteado.' ],
  [ "titulo"=>'Calabacines a la plancha',"descripcion"=>'Rodajas de calabacín doradas en la plancha con aceite de oliva y un toque de ajo, guarnición ligera y rápida.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/1305/1138029939_5fe5ddb4b1.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['3 calabacines','Aceite de oliva','1 diente de ajo','Sal, perejil fresco'],"pasos"=>['Cortar los calabacines en rodajas no muy finas.','Calentar una plancha con un poco de aceite de oliva.','Colocar las rodajas y dorarlas 2-3 minutos por cada lado.','Salpimentar y añadir ajo picado muy fino y perejil los últimos segundos.'],"consejo"=>'No las muevas demasiado en la plancha: dales tiempo para que se doren bien antes de darles la vuelta.' ],
  [ "titulo"=>'Zanahorias glaseadas',"descripcion"=>'Zanahorias cocinadas en mantequilla y un toque de miel hasta quedar brillantes y ligeramente dulces.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/3579/3519300678_15726caf82_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['500 g de zanahorias','30 g de mantequilla','1 cucharada de miel','Sal, perejil fresco'],"pasos"=>['Cortar las zanahorias en rodajas o bastones.','Cocerlas en agua con sal hasta que estén casi tiernas, unos 8 minutos, y escurrir.','Derretir la mantequilla en una sartén, añadir las zanahorias y la miel.','Saltear a fuego medio unos minutos hasta que queden brillantes y ligeramente caramelizadas.','Terminar con perejil fresco picado.'],"consejo"=>'No cuezas las zanahorias del todo antes de saltearlas: terminan de hacerse en la sartén y así no quedan blandas en exceso.' ],
  // Bocadillos y sandwiches
  [ "titulo"=>'Sandwich mixto',"descripcion"=>'Pan de molde con jamón cocido y queso, tostado en sartén o sandwichera hasta que el queso funde.',"tiempo"=>'10 min',"tiempoMin"=>10,"dificultad"=>'Fácil',"raciones_base"=>2,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/5/58/File-Sand._Mixto_-_Extra_queso_%28detalle%29.jpg',"dietas"=>['Para carnívoros','Amante del queso'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['4 rebanadas de pan de molde','2 lonchas de jamón cocido','2 lonchas de queso','Mantequilla'],"pasos"=>['Untar ligeramente el pan con mantequilla por fuera.','Montar el sandwich con el jamón y el queso entre las rebanadas, con la mantequilla hacia fuera.','Tostar en una sandwichera o en una sartén con algo de peso encima, hasta que esté dorado por ambos lados y el queso fundido.','Cortar por la mitad y servir caliente.'],"consejo"=>'Presiona ligeramente el sandwich mientras se tuesta: ayuda a que se dore de manera uniforme y a que el queso funda antes.' ],
  [ "titulo"=>'Bocadillo de tortilla',"descripcion"=>'Pan crujiente relleno de una tortilla de patatas recién hecha, el bocadillo español por excelencia.',"tiempo"=>'30 min',"tiempoMin"=>30,"dificultad"=>'Fácil',"raciones_base"=>2,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/6063/6081932814_3263342a39_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['1 barra de pan','3 patatas','4 huevos','1 cebolla (opcional)','Aceite de oliva, sal'],"pasos"=>['Preparar una tortilla de patatas siguiendo la receta clásica: freír las patatas y la cebolla, mezclar con huevo batido y cuajar en la sartén.','Cortar el pan por la mitad a lo largo.','Colocar una porción generosa de tortilla dentro del pan.','Cerrar y prensar ligeramente antes de servir.'],"consejo"=>'Deja templar un poco la tortilla antes de meterla en el pan: si está muy caliente, reblandece la miga del bocadillo.' ],
  [ "titulo"=>'Wrap de pollo y verduras',"descripcion"=>'Tortilla de trigo enrollada con pollo a la plancha, lechuga y salsa, comida rápida y fácil de llevar.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>2,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/f/f8/Smoked_chicken_and_avocado_wrap.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['2 tortillas de trigo','1 pechuga de pollo','Lechuga, tomate','Salsa de yogur o mayonesa','Sal, pimienta, aceite de oliva'],"pasos"=>['Cocinar la pechuga de pollo a la plancha con sal y pimienta, y cortarla en tiras.','Calentar ligeramente las tortillas de trigo para que sean más flexibles.','Untar cada tortilla con un poco de salsa.','Rellenar con el pollo, la lechuga y el tomate.','Enrollar bien apretado y cortar por la mitad.'],"consejo"=>'Calienta la tortilla unos segundos antes de rellenarla: se enrolla mucho mejor y no se rompe.' ],
  [ "titulo"=>'Sandwich club',"descripcion"=>'Sandwich de tres pisos con pollo, bacon, lechuga y tomate, clásico americano ideal como plato único.',"tiempo"=>'20 min',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>2,"plato"=>'principal',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/b/bd/Club-sandwich.jpg',"dietas"=>['Para carnívoros'],"objetivos"=>['Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Principal'],"ingredientes"=>['6 rebanadas de pan de molde','1 pechuga de pollo cocinada','4 tiras de bacon','Lechuga, tomate','Mayonesa'],"pasos"=>['Tostar las rebanadas de pan.','Freír o dorar el bacon hasta que esté crujiente.','Untar el pan con mayonesa y montar la primera capa con pollo, lechuga y tomate sobre una rebanada de pan.','Cubrir con otra rebanada de pan, añadir el bacon, más lechuga y tomate, y cerrar con la tercera rebanada.','Sujetar con palillos y cortar en triángulos.'],"consejo"=>'Sujeta el sandwich con palillos antes de cortarlo: al tener varias capas, se desmonta con facilidad si no se fija bien.' ],
  // Postres sencillos
  [ "titulo"=>'Natillas caseras',"descripcion"=>'Crema dulce de huevo y leche, cocinada en el cazo, el postre casero español de toda la vida.',"tiempo"=>'20 min + frío',"tiempoMin"=>20,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/c/c1/Bowl_of_natillas_at_Madrid.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Postre'],"ingredientes"=>['500 ml de leche','4 yemas de huevo','80 g de azúcar','1 cucharada de maicena','1 rama de canela o piel de limón','Galletas y canela molida para decorar'],"pasos"=>['Calentar la leche con la canela o la piel de limón, sin que llegue a hervir.','Batir las yemas con el azúcar y la maicena.','Añadir un poco de leche caliente a las yemas, removiendo, y luego verter todo de nuevo en el cazo.','Cocinar a fuego bajo, removiendo sin parar, hasta que espese ligeramente, sin dejar que hierva.','Repartir en cuencos, dejar enfriar y decorar con una galleta y canela molida.'],"consejo"=>'No dejes que hierva una vez añadidas las yemas: si hierve con fuerza, se pueden cortar y quedar grumosas.' ],
  [ "titulo"=>'Arroz con leche',"descripcion"=>'Postre cremoso de arroz cocido lentamente en leche con azúcar, canela y piel de limón.',"tiempo"=>'50 min',"tiempoMin"=>50,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/b/ba/Arroz_con_leche.png',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Postre'],"ingredientes"=>['150 g de arroz de grano redondo','1 litro de leche','100 g de azúcar','1 rama de canela','Piel de un limón','Canela molida para decorar'],"pasos"=>['Cocer el arroz un par de minutos en agua para quitarle el exceso de almidón, y escurrir.','Calentar la leche con la canela en rama y la piel de limón.','Añadir el arroz escurrido y cocinar a fuego bajo, removiendo con frecuencia, durante 35-40 minutos hasta que esté cremoso.','Añadir el azúcar a media cocción.','Retirar la canela y la piel de limón, repartir en cuencos y espolvorear con canela molida al servir.'],"consejo"=>'Remueve con frecuencia durante toda la cocción: es lo que evita que se pegue al fondo y ayuda a que suelte el almidón para quedar cremoso.' ],
  [ "titulo"=>'Macedonia de frutas',"descripcion"=>'Mezcla fresca de frutas de temporada troceadas, con un chorrito de zumo de naranja, el postre más ligero de todos.',"tiempo"=>'15 min',"tiempoMin"=>15,"dificultad"=>'Fácil',"raciones_base"=>4,"plato"=>'postre',"cocina"=>'Fácil y casera',"photoUrl"=>'https://upload.wikimedia.org/wikipedia/commons/7/74/Fruktsallad_%28Fruit_salad%29.jpg',"dietas"=>['Vegana','Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food','Quitar el hambre rápido'],"etiquetas"=>['Fácil y casera','Postre'],"ingredientes"=>['1 manzana','1 plátano','1 naranja','Un puñado de uvas','Zumo de 1 naranja','Miel (opcional)'],"pasos"=>['Pelar y trocear toda la fruta en dados de tamaño similar.','Mezclar en un bol grande.','Añadir el zumo de naranja recién exprimido para evitar que la fruta se oxide.','Añadir un poco de miel si se desea más dulzor.','Refrigerar 30 minutos antes de servir.'],"consejo"=>'Añade el plátano en dados al final y remuévelo con suavidad: es la fruta que más rápido se oscurece y se deshace si se mezcla en exceso.' ],
  [ "titulo"=>'Galletas de mantequilla',"descripcion"=>'Galletas caseras crujientes con solo cuatro ingredientes básicos, listas para hornear en media hora.',"tiempo"=>'35 min',"tiempoMin"=>35,"dificultad"=>'Fácil',"raciones_base"=>6,"plato"=>'postre',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/7436/8726079227_8ab0c2dbbf_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Postre'],"ingredientes"=>['200 g de mantequilla a temperatura ambiente','100 g de azúcar','300 g de harina','1 huevo','Una pizca de sal'],"pasos"=>['Batir la mantequilla con el azúcar hasta que quede cremosa.','Añadir el huevo y mezclar bien.','Incorporar la harina y la sal, amasando hasta obtener una masa homogénea que no se pegue a las manos.','Estirar la masa y cortar con moldes, o formar bolitas y aplastarlas ligeramente.','Hornear a 180 °C 10-12 minutos, hasta que los bordes empiecen a dorar.'],"consejo"=>'Deja enfriar las galletas sobre la propia bandeja unos minutos antes de moverlas: recién salidas del horno están muy frágiles y se rompen con facilidad.' ],
  [ "titulo"=>'Brownie de chocolate fácil',"descripcion"=>'Bizcocho denso y húmedo de chocolate, con una costra ligeramente crujiente por encima, listo en menos de una hora.',"tiempo"=>'45 min',"tiempoMin"=>45,"dificultad"=>'Fácil',"raciones_base"=>8,"plato"=>'postre',"cocina"=>'Fácil y casera',"photoUrl"=>'https://live.staticflickr.com/2603/4009689469_87f65c9bdc_b.jpg',"dietas"=>['Vegetariana'],"objetivos"=>['Sorprender a alguien','Reconfortante / comfort food'],"etiquetas"=>['Fácil y casera','Postre'],"ingredientes"=>['200 g de chocolate negro','150 g de mantequilla','3 huevos','200 g de azúcar','100 g de harina','Una pizca de sal'],"pasos"=>['Precalentar el horno a 180 °C y forrar un molde con papel de horno.','Derretir el chocolate con la mantequilla al baño maría o en el microondas, removiendo hasta que quede liso.','Batir los huevos con el azúcar hasta que blanqueen un poco.','Mezclar el chocolate derretido con los huevos batidos, y añadir la harina tamizada con la sal, mezclando lo justo para integrar.','Verter en el molde y hornear 20-25 minutos: debe quedar húmedo por dentro, no seco como un bizcocho normal.'],"consejo"=>'Sácalo del horno un poco antes de lo que parezca necesario: el brownie sigue cuajando fuera del horno y debe quedar jugoso en el centro.' ],

];